window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s12-27","number":27,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿يلتقطه﴾؟","answer":"صوّر العثور على يوسف وأخذه بصورة التقاط الشيء الضائع في الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص259، تحت «بلاغة الاستعارة في الفعل ﴿يلتقطه﴾»","url":""}]},{"id":"s12-214","number":214,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما فائدة التعبير بـ﴿بعض﴾ في قوله تعالى: ﴿يلتقطه بعض السيارة﴾؟","answer":"لأن إنقاذه على يد أي فرد من المسافرين يحقق غرض القائل: إبعاده مع إبقائه حيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص260، تحت «فائدة التعبير بلفظ ﴿بعض﴾»","url":""}]},{"id":"s12-215","number":215,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما دلالة التعريف في لفظ ﴿السيارة﴾؟","answer":"المراد جماعة المسافرين المعهودة التي تمر بالطريق وترد الماء، لا المركبة المعروفة في الاستعمال الحديث.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص260، تحت «دلالة (ال) في كلمة ﴿السيارة﴾»","url":""}]},{"id":"s12-28","number":28,"surah":12,"verses":[11],"references":[{"surah":12,"verses":[11]}],"verseLabel":"يوسف: 11","question":"ما وجه قولهم: ﴿ما لك لا تأمنا على يوسف﴾؟","answer":"بدأوا باستنكار عدم الثقة قبل طلب إخراجه، ليجعلوا الأب في موقف المدافع ويزيلوا حاجزه النفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص269، تحت «معنى التركيب ﴿ما لك﴾، ودلالة الاستفهام»","url":""}]},{"id":"s12-29","number":29,"surah":12,"verses":[11],"references":[{"surah":12,"verses":[11]}],"verseLabel":"يوسف: 11","question":"ما دلالة كثرة التوكيد في قولهم: ﴿وإنا له لناصحون﴾؟","answer":"جمعوا إنَّ واللام وتقديم ﴿له﴾ لتغطية موضع الشك، وكثرة التوكيد نفسها تناسب كذبًا يحتاج إلى تدعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص272، تحت «بلاغة اجتماع المؤكدات في جملتي النصح والحفظ»","url":""}]},{"id":"s12-30","number":30,"surah":12,"verses":[12],"references":[{"surah":12,"verses":[12]}],"verseLabel":"يوسف: 12","question":"ما وجه قولهم: ﴿يرتع ويلعب﴾؟","answer":"اختاروا ما يلائم سنه ويستميل قلب الأب إلى الترفيه عنه، ثم ألحقوا ضمان الحفظ ليكتمل الإقناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص277، تحت «إيثار استعمال الفعلين: ﴿يرتع ويلعب﴾»","url":""}]},{"id":"s12-31","number":31,"surah":12,"verses":[13],"references":[{"surah":12,"verses":[13]}],"verseLabel":"يوسف: 13","question":"ما دلالة التعبير عن فراق يوسف بالحزن، وعن أكل الذئب بالخوف؟","answer":"الحزن ألم الفراق الذي يستشعره يعقوب، حتى إن مجرد عزمهم على الذهاب بيوسف يؤلمه؛ أما الخوف فمتعلق بخطر يتوقعه ولم يقع. فجمع الكلام بين ألم البعد عنه والخشية من الضرر الذي قد يصيبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص294، تحت «الحزن والخوف»","url":""}]},{"id":"s12-32","number":32,"surah":12,"verses":[13],"references":[{"surah":12,"verses":[13]}],"verseLabel":"يوسف: 13","question":"ما سرّ تخصيص الذئب بالذكر في خوف يعقوب على يوسف؟","answer":"لأنه خطر معروف في مراعيهم عند الغفلة، لكن ذكره منحهم من حيث لا يريد الحجة التي سيستعملونها لاحقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص293، تحت «سر تخصيص الذئب دون سائر الحيوانات المفترسة»","url":""}]},{"id":"s12-33","number":33,"surah":12,"verses":[14],"references":[{"surah":12,"verses":[14]}],"verseLabel":"يوسف: 14","question":"ما وجه قولهم: ﴿لئن أكله الذئب ونحن عصبة إنا إذا لخاسرون﴾؟","answer":"جعلوا كثرتهم وقوتهم ضمانًا لحفظه، حتى عدّوا عجزهم عن حمايته من ذئب خسارة تهدر قيمتهم ورجاء أبيهم فيهم. وجمعوا القسم والتوكيد لإقناعه بإرسال يوسف معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص302، تحت «بلاغة قوله في جواب الشرط: ﴿إنا إذًا لخاسرون﴾»","url":""}]},{"id":"s12-34","number":34,"surah":12,"verses":[15],"references":[{"surah":12,"verses":[15]}],"verseLabel":"يوسف: 15","question":"ما دلالة حذف جواب ﴿فلما ذهبوا به وأجمعوا أن يجعلوه في غيابت الجب﴾؟","answer":"على وجه حذف الجواب، دلّ السياق على أنهم أنفذوا ما عزموا عليه وألقوه في الجب. وفي الحذف إيجاز وتهويل؛ إذ يُترك للسامع أن يتصور فظاعة ما صنعوه، بدل تفصيل مشهد الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص311، تحت «دلالة حذف جواب (لما)»","url":""}]},{"id":"s12-35","number":35,"surah":12,"verses":[15],"references":[{"surah":12,"verses":[15]}],"verseLabel":"يوسف: 15","question":"ما دلالة الوعد ليوسف في الجب بقوله: ﴿لتنبئنهم بأمرهم هذا﴾؟","answer":"جاء الوعد في أشد لحظة ضعف ليغرس يقين العاقبة: سيأتي يوم يكون هو المخبر وهم لا يعرفونه؛ فالوحي سبق النجاة المادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص313، تحت «دلالة اللام في ﴿لتنبئنهم﴾، وإيثار التعبير بالإنباء»","url":""}]},{"id":"s12-36","number":36,"surah":12,"verses":[15],"references":[{"surah":12,"verses":[15]}],"verseLabel":"يوسف: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم لا يشعرون﴾؟","answer":"تحتمل أنهم لا يشعرون بالوحي أو لا يعرفونه عند تحقق الوعد؛ وفي الحالين يظهر أن تدبير الله يجري خارج إدراكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص314–315، تحت «إعراب جملة ﴿وهم لا يشعرون﴾، ودلالتها»","url":""}]},{"id":"s12-37","number":37,"surah":12,"verses":[16],"references":[{"surah":12,"verses":[16]}],"verseLabel":"يوسف: 16","question":"لماذا جاء إخوة يوسف أباهم ﴿عشاء﴾؟","answer":"اختاروا وقت العشاء وظلمته ليستتر اضطراب وجوههم ويقل تدقيق أبيهم في حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص321، تحت «إيثار كلمة ﴿عشاء﴾ دون مساء مثلًا»","url":""}]},{"id":"s12-216","number":216,"surah":12,"verses":[16],"references":[{"surah":12,"verses":[16]}],"verseLabel":"يوسف: 16","question":"ما سرّ استعمال ﴿يبكون﴾ في وصف مجيء إخوة يوسف؟","answer":"اتخذوا البكاء دليلًا مصطنعًا على صدق روايتهم، فصوّر السياق تمثيلهم للحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص322، تحت «سر استعمال ﴿يبكون﴾»","url":""}]},{"id":"s12-38","number":38,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"ما سرّ استعمال الفعل ﴿نستبق﴾ في اعتذار إخوة يوسف؟","answer":"اختاروا الاستباق لأنه نشاط مألوف يشغل الجماعة ويجعل ابتعادهم عن يوسف في ظاهر قصتهم معقولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص325، تحت «سر استعمال الفعل ﴿نستبق﴾، ودلالة الصيغة»","url":""}]},{"id":"s12-217","number":217,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"ما دلالة قولهم: ﴿وتركنا يوسف﴾؟","answer":"اعترافهم بترك يوسف يشرح سبب غيابهم عنه، لكنه يكشف في الوقت نفسه تقصيرهم في حفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص325، تحت «دلالة جملة ﴿وتركنا يوسف﴾»","url":""}]},{"id":"s12-218","number":218,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"ما فائدة قولهم: ﴿عند متاعنا﴾؟","answer":"جعلوا بقاء يوسف عند المتاع سببًا طبيعيًا لعدم مشاركته في الاستباق، لتبدو قصتهم أقرب إلى التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص326، تحت «فائدة الظرف ﴿عند﴾، وإضافته إلى ﴿متاعنا﴾»","url":""}]},{"id":"s12-39","number":39,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"لماذا عبّر إخوة يوسف بالإيمان في قولهم: ﴿وما أنت بمؤمن لنا﴾ بدل التصديق؟","answer":"الإيمان هنا يتضمن الثقة والطمأنينة إلى خبرهم، لا مجرد الحكم اللفظي بصدقه، وهم يعلمون أنهم فقدوا هذه الثقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص331، تحت «سر التعبير بالإيمان دون التصديق»","url":""}]},{"id":"s12-219","number":219,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"ما فائدة قولهم: ﴿ولو كنا صادقين﴾؟","answer":"حاولوا تصوير عدم قبول أبيهم للخبر بأنه ناشئ عن شدة محبته ليوسف وسوء ظنه بهم حتى مع افتراض صدقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص331، تحت «فائدة جملة ﴿ولو كنا صادقين﴾»","url":""}]},{"id":"s12-40","number":40,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما سرّ وصف الدم نفسه بالكذب في قوله: ﴿بدم كذب﴾؟","answer":"وصف الدم نفسه بالكذب مبالغة، لأنه دليل مصنوع ينطق بخلاف الحقيقة؛ والقميص السليم فضح تناقض روايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص340، تحت «بلاغة الوصف بالمصدر في ﴿بدم كذب﴾»","url":""}]},{"id":"s12-41","number":41,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما سرّ التعبير في قول يعقوب: ﴿بل سولت لكم أنفسكم أمرًا﴾؟","answer":"لم يعرف التفصيل لكنه أدرك أن النفس زينت لهم فعلًا قبيحًا؛ فانتقل من دليل القميص إلى تشخيص الجذر الداخلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص342، تحت «إيثار الفعل ﴿سولت﴾»","url":""}]},{"id":"s12-42","number":42,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما سر قوله: ﴿فصبر جميل﴾؟","answer":"جاءت عبارة موجزة تدل على ثباته على الصبر: فالتقدير «صبري صبر جميل» أو «فصبر جميل أمثل». وحذف أحد طرفي الجملة يبرز القرار نفسه، والجميل هو الصبر الذي لا يخالطه جزع ولا شكوى إلى الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص344، تحت «نكتة وصف الصبر بالجمال ومعناه»","url":""}]},{"id":"s12-43","number":43,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما دلالة قول يعقوب: ﴿والله المستعان﴾؟","answer":"فيه إظهار افتقاره إلى معونة الله على احتمال البلاء؛ فلا يتحقق الصبر الجميل إلا بعونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص345، تحت «نكتة الإخبار عن اسم الجلالة بـ﴿المستعان﴾»","url":""}]},{"id":"s12-220","number":220,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما بلاغة التعبير بقوله: ﴿على ما تصفون﴾؟","answer":"سمّى روايتهم وصفًا يقولونه ولم يقرّ بأنها حقيقة؛ ففيه تعريض بكذبهم وإبقاء لباب الأمل في يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص346، تحت «البلاغة في التعبير بـ﴿ما تصفون﴾»","url":""}]},{"id":"s12-44","number":44,"surah":12,"verses":[19],"references":[{"surah":12,"verses":[19]}],"verseLabel":"يوسف: 19","question":"ما سرّ التعبير في قول الوارد: ﴿يا بشرى هذا غلام﴾؟","answer":"نادى البشرى، أو خاطب أصحابه بها، فرحًا بما وجد؛ فالتعبير يصور مفاجأة العثور على الغلام وشدة الاستبشار به.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص360، تحت «بلاغة المجاز في ﴿يا بشرى﴾»","url":""}]},{"id":"s12-45","number":45,"surah":12,"verses":[19],"references":[{"surah":12,"verses":[19]}],"verseLabel":"يوسف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿وأسروه بضاعة﴾؟","answer":"أخفوا أمره وجعلوه في حكم البضاعة التي تُتجر؛ فجمع التعبير بين الكتمان واتخاذه متاعًا للبيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص363، تحت «دلالة الواو في ﴿وأسروه﴾، وإيثار التعبير بالفعل»","url":""}]},{"id":"s12-46","number":46,"surah":12,"verses":[19],"references":[{"surah":12,"verses":[19]}],"verseLabel":"يوسف: 19","question":"ما دلالة ختم مشهد إخراج يوسف من الجب بقوله: ﴿والله عليم بما يعملون﴾؟","answer":"تقرر الفاصلة أن أعمالهم وخفايا قصدهم لا تغيب عن الله. وفيها تطمين بأن ما يجري ليوسف داخل في تدبيره الحكيم؛ فقد بدا الأمر بيعًا وإبعادًا، وهو يساق إلى العاقبة التي وعده الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص366، تحت «أثر الفاصلة: ﴿والله عليم بما يعملون﴾»","url":""}]},{"id":"s12-47","number":47,"surah":12,"verses":[20],"references":[{"surah":12,"verses":[20]}],"verseLabel":"يوسف: 20","question":"ما دلالة وصف الثمن بأنه ﴿بخس﴾؟","answer":"يدل على ثمن ناقص زهيد لا يوافق قيمة يوسف، ويكشف استعجال البائعين التخلص منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص374، تحت «مدلول الوصف بـ﴿بخس﴾»","url":""}]},{"id":"s12-221","number":221,"surah":12,"verses":[20],"references":[{"surah":12,"verses":[20]}],"verseLabel":"يوسف: 20","question":"ما دلالة وصف الدراهم بأنها ﴿معدودة﴾؟","answer":"تصوّر قلتها حتى كانت تُعدّ باليد، فتزيد بيان زهْدهم في يوسف وجهلهم بقدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص375، تحت «إعراب ﴿دراهم﴾ ودلالة وصفها بـ﴿معدودة﴾»","url":""}]},{"id":"s12-48","number":48,"surah":12,"verses":[20],"references":[{"surah":12,"verses":[20]}],"verseLabel":"يوسف: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وكانوا فيه من الزاهدين﴾؟","answer":"أرادوا التخلص منه أو لم يعرفوا قدره، فباعوه بلا مساومة تليق به؛ والزهد فيه يزيد مفارقة ما سيبلغه من مكانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص376، تحت «فائدة التعبير في ﴿من الزاهدين﴾»","url":""}]},{"id":"s12-49","number":49,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما سرّ التعبير في قول عزيز مصر: ﴿أكرمي مثواه﴾؟","answer":"طلب حسن إقامته ورعايته، وفي إكرام المثوى كناية عن إكرام صاحبه ومبالغة فيه؛ إذ يشمل ما يحيط به من أسباب الراحة. وكان هذا الإكرام من أسباب ما هيّأه الله له من مكانة وتمكين في مصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص385، تحت «الكناية في ﴿أكرمي مثواه﴾»","url":""}]},{"id":"s12-50","number":50,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما دلالة الرجاء في قول العزيز: ﴿عسى أن ينفعنا﴾؟","answer":"رأى العزيز في يوسف مخايل النجابة، فرجا أن ينتفع به في شؤونه ويجد عنده الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص386، تحت «دلالة الرجاء الدال عليه ﴿عسى﴾»","url":""}]},{"id":"s12-222","number":222,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"لماذا قُدّم رجاء نفع يوسف على قوله: ﴿أو نتخذه ولدًا﴾؟","answer":"انتقل الكلام من النفع المعتاد إلى منزلة أخص وأشد تقريبًا؛ فاتخاذه ولدًا غاية ما رجاه العزيز له في بيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص387، تحت «سر تقديم رجاء نفعه على اتخاذه ولدًا»","url":""}]},{"id":"s12-51","number":51,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك مكنا ليوسف في الأرض﴾ وهو ما يزال مملوكًا؟","answer":"يذكر المصدر أن التمكين يشمل المكانة والرعاية التي هيأها الله له في مصر، وأن هذا الإكرام يمهّد لما سيبلغه من سلطان. وقيل إن الماضي يصوّر تحقق التمكين المستقبل؛ فظاهر المحنة لا يكشف وحده العاقبة التي يدبرها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص389، تحت «إيثار فعل التمكين، وصيغة الماضي»","url":""}]},{"id":"s12-52","number":52,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما سرّ التذييل بقوله تعالى: ﴿والله غالب على أمره﴾ في قصة يوسف؟","answer":"يقرر أن تدبير الله نافذ لا ترده مقاصد البشر؛ أراد الإخوة بيوسف السوء فساقه الله إلى ما أراد له من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص397، تحت «سر التذييل، وعلاقته بالمعنى»","url":""}]},{"id":"s12-223","number":223,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما فائدة الاحتراس في قوله تعالى: ﴿ولكن أكثر الناس لا يعلمون﴾؟","answer":"يبين أن أكثر الناس يقفون عند ظاهر الأسباب وتخفى عليهم حكمة العاقبة، مع إثبات العلم لمن علّمه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص398، تحت «فائدة الاحتراس في خاتمة الآية»","url":""}]},{"id":"s12-53","number":53,"surah":12,"verses":[22],"references":[{"surah":12,"verses":[22]}],"verseLabel":"يوسف: 22","question":"ما معنى بلوغ يوسف أشده، ولماذا لم تحدد الآية سنه؟","answer":"بلوغ الأشد اكتمال قوته الجسدية والنفسية، والعدول عن تحديد سن بعينها يوجه النظر إلى تحقق النضج نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص404، تحت «معنى بلوغ الأشد، والعدول عن تحديد سن»","url":""}]},{"id":"s12-224","number":224,"surah":12,"verses":[22],"references":[{"surah":12,"verses":[22]}],"verseLabel":"يوسف: 22","question":"ما فائدة الجمع بين الحكم والعلم في قوله تعالى: ﴿آتيناه حكمًا وعلمًا﴾؟","answer":"جمع الله له نضج الحكم والبصيرة والعلم، ليواجه الفتنة بعقل راشد ومعرفة تهديه إلى الصواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص406، تحت «فائدة الجمع بين الحكم والعلم، وعلة التقديم»","url":""}]},{"id":"s12-54","number":54,"surah":12,"verses":[22],"references":[{"surah":12,"verses":[22]}],"verseLabel":"يوسف: 22","question":"ما دلالة الانتقال من عطاء يوسف إلى قوله: ﴿وكذلك نجزي المحسنين﴾؟","answer":"نقل عطاء يوسف من حالة خاصة إلى سنة عامة: الإحسان سبب لعطاء العلم والحكمة، فيفتح القصة لكل مقتدٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص408، تحت «التشبيه في ﴿وكذلك نجزي المحسنين﴾»","url":""}]},{"id":"s12-55","number":55,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿وراودته التي هو في بيتها﴾ ولم يذكر اسمها؟","answer":"صلة الموصول تكشف عنصر الفتنة الأخطر: هو تحت سلطانها وفي بيتها، بينما إبهام الاسم يصرف النظر من الشخص إلى الموقف والعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص420، تحت «فائدة جمع الظرفية والإضافة في الآية»","url":""}]},{"id":"s12-56","number":56,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما دلالة فعل ﴿راودته﴾؟","answer":"يدل على طلب متكرر بلطف وحيلة، لا خاطر عابر؛ فالكلمة تختصر إلحاحًا ومقاومة امتدت ولم تستجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص415، تحت «سر انتخاب لفظة ﴿راودته﴾»","url":""}]},{"id":"s12-57","number":57,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما سرّ التعبير في قولها: ﴿هيت لك﴾ بعد إغلاق الأبواب؟","answer":"عبارة دعوة صريحة جاءت بعد إحكام المكان، فبلغت الفتنة ذروتها؛ وقابلها يوسف فورًا بـ﴿معاذ الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص424، تحت «سر الجمع بين المراودة القولية والعملية»","url":""}]},{"id":"s12-58","number":58,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما دلالة مبادرة يوسف إلى قوله: ﴿معاذ الله﴾؟","answer":"هي استعاذة واعتصام بالله، وفي تصدير جوابه بها حسم للمراودة وإظهار لقوة إيمانه. ثم علّل امتناعه بقبح الخيانة وكفر الإحسان؛ فجمع جوابه الالتجاء إلى الله وبيان سبب الرفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص426، تحت «نكتة التعبير بالمصدر الميمي ﴿معاذ﴾»","url":""}]},{"id":"s12-59","number":59,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما المراد بـ﴿ربي﴾ في قول يوسف: ﴿إنه ربي﴾؟","answer":"ذكر المصدر وجهين: أن المراد الله المنعم المدبر، أو العزيز الذي أكرم إقامته؛ وعلى الوجهين يمنع الوفاءُ والشكرُ الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص427، تحت «معنى (الرب) في قوله: ﴿إنه ربي﴾»","url":""}]},{"id":"s12-225","number":225,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما بلاغة التعبير في قول يوسف: ﴿أحسن مثواي﴾؟","answer":"جعل إحسان الإقامة كناية عن مجمل الرعاية والإكرام، فاستحضر النعمة سببًا للوفاء لا للمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص428، تحت «بلاغة المجاز في قوله: ﴿أحسن مثواي﴾»","url":""}]},{"id":"s12-60","number":60,"surah":12,"verses":[24],"references":[{"surah":12,"verses":[24]}],"verseLabel":"يوسف: 24","question":"ما دلالة تعليق همّ يوسف بقوله: ﴿لولا أن رأى برهان ربه﴾؟","answer":"على وجه تفسيري يختاره المصدر، يمتنع وقوع الهم لوجود البرهان؛ فالمعنى: لولا رؤيته البرهان لهمّ بها. ويذكر وجهًا آخر يحمل الهم على ميل الطبع العارض الذي لم يتحول إلى عزم أو فعل. وفي الوجهين يبرز حفظ الله ليوسف وصرف السوء عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص442، تحت «نكتة ذكر الهم وتعليقه بـ﴿لولا﴾»","url":""}]},{"id":"s12-61","number":61,"surah":12,"verses":[24],"references":[{"surah":12,"verses":[24]}],"verseLabel":"يوسف: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك لنصرف عنه السوء والفحشاء﴾؟","answer":"لم يقل صرفناه عنهما فقط، بل صرفهما عنه؛ فالعناية الإلهية أبعدت أسباب الشر من طريق العبد المخلص.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص444–446، تحت «علة التعبير بقوله: ﴿لنصرف عنه السوء﴾»","url":""}]},{"id":"s12-62","number":62,"surah":12,"verses":[24],"references":[{"surah":12,"verses":[24]}],"verseLabel":"يوسف: 24","question":"ما دلالة وصف يوسف بأنه من ﴿عبادنا المخلصين﴾؟","answer":"الإخلاص سر نجاته من الفتنة؛ وعلى قراءة المخلَصين هو ممن اصطفاهم الله، وعلى المخلِصين هو صادق القصد، والمعنيان متلازمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص448، تحت «سر اختلاف القراءة في لفظ ﴿المخلصين﴾»","url":""}]},{"id":"s12-63","number":63,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿واستبقا الباب﴾؟","answer":"فعل واحد جمع مقصدين متضادين: يوسف يسابق إلى الهرب، وهي تسابق لمنعه؛ فاختصر حركة المشهد وصراعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص455، تحت «دلالة الإيجاز في قوله: ﴿واستبقا﴾»","url":""}]},{"id":"s12-64","number":64,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"ما دلالة كون القميص قدّ ﴿من دبر﴾ في إثبات براءة يوسف؟","answer":"لأنه دليل مادي على أنه كان هاربًا وهي خلفه تمسكه؛ فتحول القميص من أثر اعتداء إلى شاهد براءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص460، تحت «دلالة قوله تعالى: ﴿من دبر﴾»","url":""}]},{"id":"s12-65","number":65,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"ما دلالة ﴿ما﴾ في قول امرأة العزيز: ﴿ما جزاء من أراد بأهلك سوءًا﴾؟","answer":"يرجح المصدر أنها نافية، فيكون الكلام حصرًا للجزاء فيما ذكرته، ويجوز حملها على الاستفهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص461، تحت «دلالة لفظ ﴿ما﴾»","url":""}]},{"id":"s12-226","number":226,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"لماذا بادرت امرأة العزيز بالقول عند الباب؟","answer":"بادرت بالاتهام لتدفع التهمة عن نفسها وتسبق يوسف إلى توجيه فهم العزيز لما وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص462، تحت «نكتة مبادرة المرأة بالقول»","url":""}]},{"id":"s12-227","number":227,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"لماذا صاغت اتهامها في قالب كلي: ﴿ما جزاء من أراد بأهلك سوءًا﴾؟","answer":"عرضت دعواها في صورة قاعدة عامة تستثير غيرة العزيز على أهله وتحمله على معاقبة يوسف قبل سماع دفاعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص462، تحت «دلالة تقديم الكلام في قالب كلي»","url":""}]},{"id":"s12-66","number":66,"surah":12,"verses":[26],"references":[{"surah":12,"verses":[26]}],"verseLabel":"يوسف: 26","question":"ما سرّ التعبير في قول يوسف باقتضاب: ﴿هي راودتني عن نفسي﴾؟","answer":"لم يتكلم حتى اتهمته، فاقتصر على دفع التهمة. وفي تقديم «هي» قصر للمراودة عليها وردّ لاتهامها؛ فالجملة الموجزة تبين الفاعل الحقيقي وتثبت براءته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص469، تحت «بلاغة القصر في قوله: ﴿هي راودتني عن نفسي﴾»","url":""}]},{"id":"s12-67","number":67,"surah":12,"verses":[26],"references":[{"surah":12,"verses":[26]}],"verseLabel":"يوسف: 26","question":"ما دلالة كون الشاهد ﴿من أهلها﴾؟","answer":"شهادة القريب أبعد عن تهمة الانحياز ليوسف وأقوى حجة على المرأة؛ فجاء البرهان من الجهة التي يُنتظر أن تدافع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص471، تحت «فائدة ذكر كون الشاهد من أهلها»","url":""}]},{"id":"s12-68","number":68,"surah":12,"verses":[27,28],"references":[{"surah":12,"verses":[27,28]}],"verseLabel":"يوسف: 27–28","question":"ما دلالة تعليق الشاهد الحكم على جهة شق القميص؟","answer":"حوّل النزاع من دعويين متعارضتين إلى أثر محسوس: شقه من الأمام يدل على إقبال، ومن الخلف يدل على هرب؛ فالبينة ناطقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص472، تحت «سر ذكر قد القميص من الشاهد»","url":""}]},{"id":"s12-69","number":69,"surah":12,"verses":[28],"references":[{"surah":12,"verses":[28]}],"verseLabel":"يوسف: 28","question":"ما أثر لفظ ﴿كيدكن﴾ في قول العزيز: ﴿إنه من كيدكن﴾؟","answer":"يكشف اللفظ التدبير الخفي الذي قلب البريء متهمًا وحاول صرف الأنظار عن الفاعل الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص481، تحت «أثر لفظ ﴿كيدكن﴾»","url":""}]},{"id":"s12-228","number":228,"surah":12,"verses":[28],"references":[{"surah":12,"verses":[28]}],"verseLabel":"يوسف: 28","question":"ما فائدة التذييل بقوله: ﴿إن كيدكن عظيم﴾؟","answer":"عمّم الحكم بعد الواقعة وبيّن عظم أثر ذلك الكيد في الموقف وما أحدثه من قلب للحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص483، تحت «فائدة التذييل في آخر الآية»","url":""}]},{"id":"s12-70","number":70,"surah":12,"verses":[29],"references":[{"surah":12,"verses":[29]}],"verseLabel":"يوسف: 29","question":"ما سرّ التعبير في قول العزيز: ﴿يوسف أعرض عن هذا﴾؟","answer":"أراد إغلاق الفضيحة وحفظ البيت، فطلب من يوسف الكتمان، ثم أمر المرأة بالاستغفار اعترافًا بخطئها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص487، تحت «دلالة فعل الأمر ﴿أعرض﴾»","url":""}]},{"id":"s12-71","number":71,"surah":12,"verses":[29],"references":[{"surah":12,"verses":[29]}],"verseLabel":"يوسف: 29","question":"ما سرّ التعبير في قوله لها: ﴿إنك كنت من الخاطئين﴾ بصيغة المذكر الجمع؟","answer":"﴿الخاطئين﴾ جمع يغلب فيه التذكير ويشمل جنس المذنبين، فيضع فعلها ضمن خطأ أخلاقي عام لا خصوص النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص489–490، تحت «نكتة التعبير بـ﴿الخاطئين﴾»","url":""}]},{"id":"s12-72","number":72,"surah":12,"verses":[30],"references":[{"surah":12,"verses":[30]}],"verseLabel":"يوسف: 30","question":"ما سرّ التعبير في قول نسوة المدينة: ﴿تراود فتاها عن نفسه﴾ بالمضارع؟","answer":"يستحضر المضارع صورة المراودة كأنها حاضرة، ويدل على استمرارها وتعلقها بيوسف وإصرارها؛ فزاد ذلك في لوم النسوة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص498، تحت «دلالة قولهن ﴿تراود﴾ بالمضارع»","url":""}]},{"id":"s12-73","number":73,"surah":12,"verses":[30],"references":[{"surah":12,"verses":[30]}],"verseLabel":"يوسف: 30","question":"ما دلالة قول النسوة: ﴿قد شغفها حبًا﴾؟","answer":"الشغاف غلاف القلب أو سويداؤه؛ فالصورة تجعل الحب قد نفذ إلى أعماقها واستولى عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص499، تحت «بلاغة الاستعارة في لفظ (الشغف)»","url":""}]},{"id":"s12-74","number":74,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما سرّ إعداد المتكأ للنسوة قبل خروج يوسف عليهن؟","answer":"هيأت لهن مجلس راحة وطعامًا يحتاج إلى القطع، لتجري المواجهة في حال اطمئنان وتكون دهشتهن عند ظهوره أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص512، تحت «سر التعبير بـ﴿متكأ﴾»","url":""}]},{"id":"s12-229","number":229,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما دلالة إيتاء كل واحدة من النسوة سكينًا؟","answer":"جعلت السكين في يد كل واحدة ليظهر أثر المفاجأة عليهن جميعًا حين ينشغلن بجمال يوسف عن الإحساس بأيديهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص514، تحت «دلالة التعبير بـ﴿وآتت كل واحدة منهن سكينًا﴾»","url":""}]},{"id":"s12-230","number":230,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما دلالة أمر امرأة العزيز يوسف بقولها: ﴿اخرج عليهن﴾؟","answer":"يدل الأمر على أنها رتبت ظهوره المفاجئ في اللحظة التي أرادتها لتقيم الحجة على النسوة بما سيشاهدنه بأنفسهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص516، تحت «دلالة الأمر في ﴿اخرج﴾»","url":""}]},{"id":"s12-75","number":75,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما نكتة تعليق إكبار النسوة ليوسف بمجرد رؤيته؟","answer":"يدل على أن رؤيته وحدها أحدثت في نفوسهن دهشة بالغة قبل كلام أو تعامل، تصويرًا لقوة أثر جماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص518، تحت «نكتة تعليق الإكبار بالرؤية»","url":""}]},{"id":"s12-231","number":231,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما دلالة تضعيف الفعل في قوله: ﴿وقطعن أيديهن﴾؟","answer":"صيغة التفعيل تصور تكرر الجرح أو شدته في أيديهن من فرط الانبهار، والمراد الجرح لا إبانة الأيدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص519، تحت «دلالة تضعيف الفعل ﴿قطعن﴾»","url":""}]},{"id":"s12-76","number":76,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما دلالة قول النسوة: ﴿ما هذا بشرًا إن هذا إلا ملك كريم﴾؟","answer":"لم يجدن في معيارهن البشري جمالًا يفسر المشهد، فنفين عنه البشرية على سبيل المبالغة وشبهنه بملك متخيل الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص523، تحت «براعة التشبيه في ﴿ما هذا بشرًا إن هذا إلا ملك كريم﴾»","url":""}]},{"id":"s12-77","number":77,"surah":12,"verses":[32],"references":[{"surah":12,"verses":[32]}],"verseLabel":"يوسف: 32","question":"ما نكتة تعبير امرأة العزيز عن المراودة بصيغة الأمر؟","answer":"تحولت بعد تصريحها بالمراودة إلى طلب الطاعة والإلزام، كأن الاستجابة لها أمر يجب تنفيذه لا رغبة قابلة للرفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص534، تحت «نكتة التعبير عن المراودة بالأمر»","url":""}]},{"id":"s12-232","number":232,"surah":12,"verses":[32],"references":[{"surah":12,"verses":[32]}],"verseLabel":"يوسف: 32","question":"ما سرّ تهديد امرأة العزيز يوسف بالسجن بعد مراودته؟","answer":"لما عجز الترغيب استعانت بسلطانها وهددته بعقوبة تسلب حريته وتذله، لتكرهه على ما امتنع منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص535، تحت «سر التعبير بـ(السجن)»","url":""}]},{"id":"s12-78","number":78,"surah":12,"verses":[32],"references":[{"surah":12,"verses":[32]}],"verseLabel":"يوسف: 32","question":"ما دلالة اختلاف التوكيد في ﴿ليسجنن وليكونًا من الصاغرين﴾؟","answer":"أكدت تهديدها بالنونين. ومن الأوجه التي يذكرها المصدر تخصيص السجن بالنون الثقيلة لأنها أقدر عليه من إيقاع الصغار به؛ فجاءت الخفيفة مع الصغار. ووصفه بأنه من الصاغرين يصور إرادتها إلحاقه بجملة الأذلاء بعد عزته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص535، تحت «نكتة التأكيد بالنونين: الثقيلة والخفيفة»","url":""}]},{"id":"s12-79","number":79,"surah":12,"verses":[33],"references":[{"surah":12,"verses":[33]}],"verseLabel":"يوسف: 33","question":"ما سرّ التعبير في قول يوسف: ﴿السجن أحب إلي مما يدعونني إليه﴾؟","answer":"ليس السجن محبوبًا لذاته، وإنما هو أهون عليه من الوقوع في المعصية. فعبّر بالحب عن اختياره أخف الضررين، مبينًا قوة تمسكه بالعفة وإن أدى ذلك إلى السجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص544، تحت «نكتة التعبير عن المبغوض بشدة الحب»","url":""}]},{"id":"s12-80","number":80,"surah":12,"verses":[33],"references":[{"surah":12,"verses":[33]}],"verseLabel":"يوسف: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلا تصرف عني كيدهن أصب إليهن﴾؟","answer":"مع طهارته لم يعتمد على نفسه، بل اعترف بضعف الطبيعة البشرية وطلب الصرف الإلهي؛ وهذا أبلغ في صدق العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص549، تحت «بلاغة التعبير بالصرف وبالمضارع»","url":""}]},{"id":"s12-81","number":81,"surah":12,"verses":[34],"references":[{"surah":12,"verses":[34]}],"verseLabel":"يوسف: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستجاب له ربه فصرف عنه كيدهن﴾؟","answer":"استجاب الله دعاءه فصرف عنه كيدهن، أي أبعد عنه أثر الإغراء وحماه من الميل إليهن؛ أما السجن فجاء بعد ذلك بقرار القوم، وليس هو عين الاستجابة المذكورة في الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص554، تحت «نكتة التعبير بـ﴿فاستجاب﴾»","url":""}]},{"id":"s12-82","number":82,"surah":12,"verses":[34],"references":[{"surah":12,"verses":[34]}],"verseLabel":"يوسف: 34","question":"ما دلالة ختم الاستجابة بقوله: ﴿إنه هو السميع العليم﴾؟","answer":"هو السميع لدعاء يوسف، العليم بحاله وصدق التجائه إليه وما يحيط به من كيد؛ فجاء الاسمان تعليلًا مناسبًا لاستجابة دعائه وصرف السوء عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص558، تحت «سر ختم الآية بـ﴿السميع العليم﴾»","url":""}]},{"id":"s12-83","number":83,"surah":12,"verses":[35],"references":[{"surah":12,"verses":[35]}],"verseLabel":"يوسف: 35","question":"ما دلالة قوله: ﴿من بعد ما رأوا الآيات﴾ في سياق قرار سجن يوسف؟","answer":"الآيات دلائل براءته التي ظهرت لهم؛ فذكر رؤيتها يبين أنهم سجنوه مع علمهم ببراءته، لإخفاء الخبر وتهدئة الحديث عنه. وبذلك يكشف السياق ظلم القرار، لا خفاء الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص563، تحت «سر التعبير بالرؤية ﴿رأوا﴾»","url":""}]},{"id":"s12-84","number":84,"surah":12,"verses":[35],"references":[{"surah":12,"verses":[35]}],"verseLabel":"يوسف: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿ليسجننه حتى حين﴾ دون تحديد؟","answer":"لأن غرضهم إبعاد القضية إلى أن تخمد، لا تنفيذ عقوبة ثابتة؛ فناسبه زمن مجهول يخضع لمصلحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص564، تحت «دلالة تنكير ﴿حين﴾»","url":""}]},{"id":"s12-85","number":85,"surah":12,"verses":[36],"references":[{"surah":12,"verses":[36]}],"verseLabel":"يوسف: 36","question":"ما سرّ التعبير في قول أحد الفتيين: ﴿إني أراني أعصر خمرًا﴾ مع أنه يعصر عنبًا؟","answer":"سمّى الشيء بما سيؤول إليه؛ فالرؤيا تعرض النتيجة في مقدماتها، وهذا من المجاز باعتبار المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص573، تحت «بلاغة المجاز في ﴿أعصر خمرًا﴾»","url":""}]},{"id":"s12-86","number":86,"surah":12,"verses":[36],"references":[{"surah":12,"verses":[36]}],"verseLabel":"يوسف: 36","question":"ما دلالة تعليل طلب تأويل الرؤيا بقول الفتيين: ﴿إنا نراك من المحسنين﴾؟","answer":"جاءت الجملة تعليلًا لطلبهما؛ فقد شاهدا من إحسانه ما بعث ثقتهما به ورجاءهما أن يحسن إليهما بالتأويل. وفي إدخاله في جماعة المحسنين ثناء عليه واستمالة له إلى إجابة سؤالهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص576، تحت «علة الفصل في ﴿إنا نراك من المحسنين﴾»","url":""}]},{"id":"s12-87","number":87,"surah":12,"verses":[37],"references":[{"surah":12,"verses":[37]}],"verseLabel":"يوسف: 37","question":"ما دلالة تقديم يوسف الدعوة إلى التوحيد على تأويل رؤيا الفتيين؟","answer":"اغتنم إقبالهما عليه وثقتهما بعلمه ليبين لهما ما هو أهم من تعبير الرؤيا: توحيد الله. وقدم ما يطمئنهما إلى علمه، ثم نسبه إلى تعليم ربه، فمهّد لقبول دعوته قبل بيان مصير الرؤيتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص582، تحت «نكتة تقديم الهداية على تقديم تأويل الرؤيا»","url":""}]},{"id":"s12-88","number":88,"surah":12,"verses":[37],"references":[{"surah":12,"verses":[37]}],"verseLabel":"يوسف: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكما مما علمني ربي﴾؟","answer":"نسب علمه إلى تعليم ربه، فبيّن مصدر هذه المعرفة وأثار شوق السائلين إلى معرفة الرب الذي علّمه. و«مما» تفيد أن ما أظهره بعض ما وهبه الله من العلم، مع التواضع له وشكر إحسانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص588، تحت «علة الفصل: ﴿ذلكما مما علمني ربي﴾»","url":""}]},{"id":"s12-89","number":89,"surah":12,"verses":[38],"references":[{"surah":12,"verses":[38]}],"verseLabel":"يوسف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿واتبعت ملة آبائي إبراهيم وإسحاق ويعقوب﴾؟","answer":"أثبت أن توحيده امتداد لرسالة راسخة لا فكرة نشأت في السجن، وجمع نسب النبوة مع شكر فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص603، تحت «غرض جملة: ﴿واتبعت ملة آبائي﴾»","url":""}]},{"id":"s12-90","number":90,"surah":12,"verses":[38],"references":[{"surah":12,"verses":[38]}],"verseLabel":"يوسف: 38","question":"ما دلالة صيغة الجحود في قوله: ﴿ما كان لنا أن نشرك بالله﴾؟","answer":"تفيد شدة انتفاء الشرك عن يوسف وآبائه وعدم استقامته في حقهم، لما ثبتوا عليه من التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص606، تحت «دلالة التعبير بصيغة الجحود»","url":""}]},{"id":"s12-233","number":233,"surah":12,"verses":[38],"references":[{"surah":12,"verses":[38]}],"verseLabel":"يوسف: 38","question":"ما دلالة ﴿من﴾ في قوله: ﴿أن نشرك بالله من شيء﴾؟","answer":"جاءت لاستغراق النفي، فأغلقت باب استثناء أي شيء يمكن أن يتخذ شريكًا مع الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص608، تحت «دلالة دخول ﴿من﴾»","url":""}]},{"id":"s12-91","number":91,"surah":12,"verses":[39],"references":[{"surah":12,"verses":[39]}],"verseLabel":"يوسف: 39","question":"ما سرّ التعبير في قوله تعالى: ﴿يا صاحبي السجن﴾؟","answer":"جمعهما معه في وصف الصحبة بمكان يشتركون في شدته، فآنسهما وتحبب إليهما وقرّب نفوسهما إلى قبول النصيحة. فالنداء يمهّد لسماع الدعوة إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص619، تحت «نكتة ندائهما بـ﴿يا صاحبي السجن﴾»","url":""}]},{"id":"s12-92","number":92,"surah":12,"verses":[39],"references":[{"surah":12,"verses":[39]}],"verseLabel":"يوسف: 39","question":"ما دلالة السؤال: ﴿أأرباب متفرقون خير أم الله الواحد القهار﴾؟","answer":"عرض المقارنة في صورة سؤال ليحمل المخاطبين على إعمال العقل: أرباب مختلفة عاجزة مقهورة، أم الله المتفرد بالألوهية والقاهر لكل شيء؟ والمفاضلة تنزّل في المحاورة لإبطال عبادتهم، وليست إثباتًا لخيرية الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص620، تحت «معنى الاستفهام في ﴿أأرباب متفرقون﴾»","url":""}]},{"id":"s12-93","number":93,"surah":12,"verses":[40],"references":[{"surah":12,"verses":[40]}],"verseLabel":"يوسف: 40","question":"ما دلالة وصف المعبودات بأنها ﴿أسماء سميتموها﴾؟","answer":"نزع عنها كل حقيقة وسلطان؛ لم يبق من ألوهيتها إلا أسماء اخترعها البشر وورثوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص631، تحت «براعة التعبير بالأسماء في باب العبادة»","url":""}]},{"id":"s12-94","number":94,"surah":12,"verses":[40],"references":[{"surah":12,"verses":[40]}],"verseLabel":"يوسف: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الحكم إلا لله﴾ بعد نفي سلطان الأصنام؟","answer":"بعد أن نفى وجود حجة على ألوهية الأصنام، حصر الحكم في الله وحده؛ فهو الذي يأمر عباده، وقد أمر بإفراده بالعبادة. وبذلك جاء الأمر بالتوحيد نتيجة لما تقرر من اختصاصه بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص637، تحت «دلالة التعقيب بـ﴿أمر ألا تعبدوا إلا إياه﴾»","url":""}]},{"id":"s12-95","number":95,"surah":12,"verses":[40],"references":[{"surah":12,"verses":[40]}],"verseLabel":"يوسف: 40","question":"ما دلالة وصف التوحيد بأنه ﴿الدين القيم﴾؟","answer":"لأنه مستقيم في دليله، مقيم لحياة الإنسان، لا اعوجاج فيه كتعدد الآلهة؛ لكن أكثر الناس لا يدركون هذه الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص639، تحت «سر وصف الدين بالقيم»","url":""}]},{"id":"s12-96","number":96,"surah":12,"verses":[41],"references":[{"surah":12,"verses":[41]}],"verseLabel":"يوسف: 41","question":"ما دلالة تكرار نداء ﴿يا صاحبي السجن﴾ عند تأويل الرؤيا؟","answer":"بعد الاستطراد الدعوي أعاد رابط الصحبة لينقل إلى الجواب الشخصي برفق، حتى مع قسوة مصير أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص646، تحت «دلالة التكرار في ﴿يا صاحبي السجن﴾»","url":""}]},{"id":"s12-97","number":97,"surah":12,"verses":[41],"references":[{"surah":12,"verses":[41]}],"verseLabel":"يوسف: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿قضي الأمر الذي فيه تستفتيان﴾؟","answer":"التأويل وحي محقق لا ظن قابل للتغيير؛ فجاء الماضي ﴿قضي﴾ ليصور النتيجة كأنها انتهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص653، تحت «سر التعبير بالماضي ﴿قضي﴾»","url":""}]},{"id":"s12-98","number":98,"surah":12,"verses":[42],"references":[{"surah":12,"verses":[42]}],"verseLabel":"يوسف: 42","question":"ما سرّ التعبير في قوله للناجي: ﴿اذكرني عند ربك﴾؟","answer":"الأمر هنا التماس من صاحب عُرف بالمودة؛ طلب أن يذكر الناجي قضيته ومظلوميته عند الملك ليظهر أمره وتنظر قضيته. واكتفى بـ«اذكرني» عن تفصيل الحال التي كان مخاطبه يعرفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص662، تحت «معنى الأمر في الفعل ﴿اذكرني﴾»","url":""}]},{"id":"s12-99","number":99,"surah":12,"verses":[42],"references":[{"surah":12,"verses":[42]}],"verseLabel":"يوسف: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنساه الشيطان ذكر ربه﴾، ومن الذي أنساه؟","answer":"يذكر المصدر وجهين لمرجع الضمير: يوسف، فيكون النسيان متعلقًا بذكر ربه؛ أو الناجي، فيكون قد نسي ذكر يوسف عند سيده. ثم يبين السياق امتداد لبث يوسف في السجن، وتختلف صلة ذلك بالنسيان باختلاف الوجه التفسيري.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص663، تحت «وجه تعدد مرجع الضمير في ﴿فأنساه﴾»","url":""}]},{"id":"s12-100","number":100,"surah":12,"verses":[43],"references":[{"surah":12,"verses":[43]}],"verseLabel":"يوسف: 43","question":"ما دلالة تطابق العدد في البقرات والسنابل مع سنوات تأويل يوسف؟","answer":"تقابل البقرات السمان والسنابل الخضر سبع سنوات الخصب، وتقابل العجاف واليابسات سبع سنوات القحط. فالتطابق يربط صور الرؤيا بمددها التي بُني عليها إرشاد يوسف إلى الزراعة والادخار، دون أن يبيّن النص علة اختيار العدد سبعة في ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص731، تحت «وجه تشبيه البقرات والسنبلات بالسنين»","url":""}]},{"id":"s12-101","number":101,"surah":12,"verses":[43],"references":[{"surah":12,"verses":[43]}],"verseLabel":"يوسف: 43","question":"ما نكتة طلب الملك تعبير الرؤيا بلفظ ﴿أفتوني﴾؟","answer":"يدل الإفتاء على طلب بيان قائم على علم واختصاص، لا مجرد حدس عابر، لأن الرؤيا أقلقت الملك وأراد جوابًا موثوقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص678، تحت «نكتة التعبير بالإفتاء في تعبير الرؤيا»","url":""}]},{"id":"s12-234","number":234,"surah":12,"verses":[43],"references":[{"surah":12,"verses":[43]}],"verseLabel":"يوسف: 43","question":"ما دلالة الشرط في قوله: ﴿إن كنتم للرؤيا تعبرون﴾؟","answer":"يختبر قدرتهم ويعلق طلب الجواب على تحقق خبرتهم في التعبير، وفيه تعريض بالشك في بلوغهم منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص678، تحت «دلالة ﴿إن﴾»","url":""}]},{"id":"s12-102","number":102,"surah":12,"verses":[44],"references":[{"surah":12,"verses":[44]}],"verseLabel":"يوسف: 44","question":"ما دلالة وصف الرؤيا بأنها ﴿أضغاث أحلام﴾ بالجمع؟","answer":"شبّهوا ما رأوه أخلاطًا من الرؤى بحزم النبات المختلط، فزعموا أنها لا تنتظم في تأويل. ومن أوجه الجمع أن الرؤيا الواحدة تضمنت صورًا وأجزاء مختلفة؛ ويذكر المصدر أيضًا المبالغة في وصفها بالأباطيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص684، تحت «بلاغة الاستعارة في تركيب ﴿أضغاث أحلام﴾»","url":""}]},{"id":"s12-103","number":103,"surah":12,"verses":[44],"references":[{"surah":12,"verses":[44]}],"verseLabel":"يوسف: 44","question":"ما دلالة قول الملأ: ﴿وما نحن بتأويل الأحلام بعالمين﴾؟","answer":"من أوجه تفسيره أنهم نفوا علمهم بتأويل الأخلاط التي زعموا أنها ليست رؤيا صادقة، اعتذارًا عن الجواب مع الاحتفاظ بدعوى معرفة التعبير. ويذكر المصدر وجهًا آخر يحمل كلامهم على الاعتراف بالعجز عن التأويل عمومًا؛ فلا ينحصر معنى الجملة في الوجه الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص688، تحت «دلالة النفي في ﴿وما نحن﴾»","url":""}]},{"id":"s12-104","number":104,"surah":12,"verses":[45],"references":[{"surah":12,"verses":[45]}],"verseLabel":"يوسف: 45","question":"ما سرّ التعبير في وصف الناجي بقوله تعالى: ﴿وادكر بعد أمة﴾؟","answer":"تذكر يوسف بعد مدة طويلة؛ والكلمة تصور غياب الذكر وسط زمن ممتد ثم عودته فجأة عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص703، تحت «بلاغة التعبير بلفظ ﴿أمة﴾»","url":""}]},{"id":"s12-105","number":105,"surah":12,"verses":[45],"references":[{"surah":12,"verses":[45]}],"verseLabel":"يوسف: 45","question":"ما بلاغة قول الناجي: ﴿أنا أنبئكم بتأويله﴾ مع أن يوسف هو الذي سيؤوله؟","answer":"أسند الإنباء إلى نفسه لأنه سبب الوصول إلى صاحب التأويل وناقل جوابه إلى الملك، وهذا من المجاز العقلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص703، تحت «بلاغة المجاز العقلي في ﴿أنا أنبئكم بتأويله﴾»","url":""}]},{"id":"s12-235","number":235,"surah":12,"verses":[45],"references":[{"surah":12,"verses":[45]}],"verseLabel":"يوسف: 45","question":"ما دلالة الفاء في قول الناجي: ﴿فأرسلون﴾؟","answer":"تفيد سرعة ترتيب طلب الإرسال على وعده بالإتيان بالتأويل؛ فطريق الحل عنده يتوقف على بلوغ يوسف في السجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص706، تحت «بلاغة العطف بالفاء في قوله: ﴿فأرسلون﴾»","url":""}]},{"id":"s12-106","number":106,"surah":12,"verses":[46],"references":[{"surah":12,"verses":[46]}],"verseLabel":"يوسف: 46","question":"ما دلالة نداء يوسف بوصف ﴿أيها الصديق﴾؟","answer":"خاطبه بالوصف الذي عرفه به من صدق القول والتأويل وحسن السيرة في السجن؛ فـ﴿الصديق﴾ صيغة مبالغة في الصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص711، تحت «بلاغة اصطفاء جملة النداء ﴿أيها الصديق﴾»","url":""}]},{"id":"s12-107","number":107,"surah":12,"verses":[46],"references":[{"surah":12,"verses":[46]}],"verseLabel":"يوسف: 46","question":"ما دلالة إعادة وصف البقرات والسنابل بالتفصيل عند سؤال يوسف؟","answer":"إعادة الرؤيا بلفظها تدفع توهم أن الساقي تصرف فيها أو حكاها بالمعنى؛ فتؤكد أمانته في النقل. كما أن اختلاف اللفظ قد يؤثر في التأويل، فاقتضى المقام الحفاظ على تفاصيلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص713، تحت «دلالة الإطناب بتكرار نص الرؤيا وإعادتها بلفظها»","url":""}]},{"id":"s12-108","number":108,"surah":12,"verses":[47],"references":[{"surah":12,"verses":[47]}],"verseLabel":"يوسف: 47","question":"ما دلالة اقتران تأويل الرؤيا بإرشادهم إلى الزراعة والادخار؟","answer":"لم يقتصر على تأويل الرؤيا، بل ضم إليه إرشادهم إلى ما يفعلونه في سنوات الخصب؛ فدلهم على الزراعة المتتابعة وحفظ أكثر الحصاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص723، تحت «دلالة العدول من الخبر إلى الأمر»","url":""}]},{"id":"s12-109","number":109,"surah":12,"verses":[47],"references":[{"surah":12,"verses":[47]}],"verseLabel":"يوسف: 47","question":"ما دلالة الأمر في قوله: ﴿فما حصدتم فذروه في سنبله﴾؟","answer":"هو إرشاد عملي إلى إبقاء أكثر المحصول في سنبله ليحفظ مدة أطول استعدادًا لسنوات القحط.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص723، تحت «دلالة الخطاب بالأمر في قوله: ﴿فذروه﴾»","url":""}]},{"id":"s12-236","number":236,"surah":12,"verses":[47],"references":[{"surah":12,"verses":[47]}],"verseLabel":"يوسف: 47","question":"ما دلالة الاستثناء في قوله: ﴿إلا قليلًا مما تأكلون﴾؟","answer":"يحصر المستهلك في قدر قليل للحاجة، ويوجه إلى ادخار معظم الحصاد بدل استهلاكه في سنوات الخصب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص724، تحت «دلالة الاستثناء في قوله: ﴿إلا قليلًا﴾»","url":""}]},{"id":"s12-110","number":110,"surah":12,"verses":[48],"references":[{"surah":12,"verses":[48]}],"verseLabel":"يوسف: 48","question":"ما دلالة وصف السنوات بـ﴿سبع شداد﴾؟","answer":"نقل الشدة من الناس إلى السنين نفسها، كأن الزمن كله اشتد عليهم؛ وهي صورة لشمول القحط وطوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص730، تحت «بلاغة المجاز في وصف السني بالشداد»","url":""}]},{"id":"s12-111","number":111,"surah":12,"verses":[48],"references":[{"surah":12,"verses":[48]}],"verseLabel":"يوسف: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿يأكلن ما قدمتم لهن﴾ عن السنين؟","answer":"شخص سنوات القحط ككائنات جائعة تلتهم المخزون؛ فالصورة توقظ الخوف وتدفع إلى الادخار المنظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص730، تحت «بلاغة الاستعارة في إسناد فعل الأكل إلى السنين»","url":""}]},{"id":"s12-112","number":112,"surah":12,"verses":[49],"references":[{"surah":12,"verses":[49]}],"verseLabel":"يوسف: 49","question":"ما دلالة قوله تعالى بعد سنوات الشدة: ﴿فيه يغاث الناس﴾؟","answer":"يبشر بانكشاف القحط؛ فاللفظ يحتمل نزول الغيث وإغاثة الناس من الشدة، وصيغته تصور الفرج واقعًا عليهم من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص737، تحت «دلالة التعبير بلفظ ﴿يغاث﴾ مادة وصيغة»","url":""}]},{"id":"s12-237","number":237,"surah":12,"verses":[49],"references":[{"surah":12,"verses":[49]}],"verseLabel":"يوسف: 49","question":"ما براعة ختام التأويل بقوله: ﴿وفيه يعصرون﴾؟","answer":"العصر دليل وفرة الثمار بعد الجدب وعودة الانتفاع بها؛ فختم التأويل بصورة محسوسة لتجدد الخصب والنماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص739، تحت «براعة الختام بلفظ ﴿يعصرون﴾»","url":""}]},{"id":"s12-113","number":113,"surah":12,"verses":[50],"references":[{"surah":12,"verses":[50]}],"verseLabel":"يوسف: 50","question":"ما دلالة تقديم يوسف طلب التحقيق على الخروج من السجن؟","answer":"أراد براءة علنية قبل الحرية، حتى لا يخرج بعفو يوهم بقاء التهمة؛ فقدم صفاء السمعة على عجلة الخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص746، تحت «بلاغة صوغ مضمون السؤال ﴿ما بال النسوة﴾»","url":""}]},{"id":"s12-114","number":114,"surah":12,"verses":[50],"references":[{"surah":12,"verses":[50]}],"verseLabel":"يوسف: 50","question":"ما دلالة السؤال عن النسوة دون التصريح بامرأة العزيز؟","answer":"يذكر المصدر أوجهًا منها أن النسوة شاهدات على أصل القصة، فالسؤال عنهن يؤسس لإظهار البراءة بالحجة؛ ومنها التلطف وعدم مواجهة العزيز بإفراد زوجته بالاتهام، مع إمكان وصول التحقيق إلى الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص747، تحت «نكتة تعيين ﴿النسوة﴾ موضوعًا لسؤاله دون (امرأة العزيز)»","url":""}]},{"id":"s12-115","number":115,"surah":12,"verses":[50],"references":[{"surah":12,"verses":[50]}],"verseLabel":"يوسف: 50","question":"ما دلالة ختم كلام يوسف بقوله: ﴿إن ربي بكيدهن عليم﴾؟","answer":"على تفسير «ربي» بالله، يتضمن الكلام تفويض الأمر إلى من أحاط علمه بحقيقة الكيد، والثقة بظهور البراءة، مع عدم سرد تفاصيل القصة للرسول. واسم الرب المضاف إليه يستحضر لطف الله به وإحسانه، وصفة العلم تلائم خفاء الكيد على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص751، تحت «علة ختم الآية بصفة العلم»","url":""}]},{"id":"s12-116","number":116,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما سرّ التعبير في قول الملك: ﴿ما خطبكن إذ راودتن يوسف﴾ فنسب المراودة إليهن جميعًا؟","answer":"يعرض المصدر أوجهًا: أنهن شاركن في المراودة أو التحريض عليها؛ أو أن تعميم السؤال كان طريقًا إلى استنطاق الحقيقة من غير تعيين المرأة ابتداء. ففي توجيه الخطاب إليهن جميعًا استقصاء للقضية وتمهيد لظهور الاعتراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص755، تحت «نكتة إسناد المراودة إلى ضمير النسوة»","url":""}]},{"id":"s12-117","number":117,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما براعة استهلال النسوة جوابهن بقولهن: ﴿حاش لله﴾؟","answer":"بدأن بالتنزيه والتعجب من نسبة السوء إلى يوسف، فمهد الاستهلال لشهادة قاطعة ببراءته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص758، تحت «براعة الاستهلال في جملة ﴿حاش لله﴾»","url":""}]},{"id":"s12-238","number":238,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما فائدة ﴿من﴾ في قول النسوة: ﴿ما علمنا عليه من سوء﴾؟","answer":"تفيد استغراق النفي، فتشمل شهادتهن نفي أدنى سوء يمكن أن ينسب إلى يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص761، تحت «فائدة ﴿من﴾ في قوله: ﴿من سوء﴾»","url":""}]},{"id":"s12-118","number":118,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما سرّ التعبير في قول امرأة العزيز: ﴿الآن حصحص الحق﴾؟","answer":"حصحص أي ظهر وتمكن بعد خفاء؛ و﴿الآن﴾ تعلن انتهاء زمن المواربة أمام تحقيق أعاد القضية من جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص763، تحت «إيثار لفظ ﴿حصحص﴾ على (ظهر)»","url":""}]},{"id":"s12-119","number":119,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما بلاغة قول امرأة العزيز: ﴿أنا راودته عن نفسه﴾؟","answer":"قدمت ضميرها لتخص نفسها بالفعل وتتحمل مسؤوليته صراحة، فصدر الاعتراف من مصدر الاتهام نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص766، تحت «بلاغة تقديم المسند إليه على المسند الفعلي»","url":""}]},{"id":"s12-239","number":239,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما دلالة إتباع اعتراف امرأة العزيز بقولها: ﴿وإنه لمن الصادقين﴾؟","answer":"جاءت الجملة توكيدًا لبراءة يوسف؛ فجمعت اعترافها بفعلها وشهادتها بصدقه، فأبطلت التهمة من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص767، تحت «موقع جملة ﴿وإنه لمن الصادقين﴾ مما قبله»","url":""}]},{"id":"s12-120","number":120,"surah":12,"verses":[52],"references":[{"surah":12,"verses":[52]}],"verseLabel":"يوسف: 52","question":"ما دلالة اختلاف المفسرين في قائل: ﴿ذلك ليعلم أني لم أخنه بالغيب﴾؟","answer":"إذا كان من كلام يوسف، فهو يبين أن التحقيق لإثبات أمانته وعدم خيانته العزيز. وإذا كان من كلام امرأة العزيز، فهي تبين أن اعترافها يبرئ يوسف في غيبته من الكذب عليه. ويرجح المصدر اتصال الكلام باعترافها؛ لأن حمله على كلام يوسف يستلزم انتقالًا وحذفًا في سياق الحوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص786، تحت «دلالة آراء المفسرين في تحديد القائل في السياق»","url":""}]},{"id":"s12-121","number":121,"surah":12,"verses":[52],"references":[{"surah":12,"verses":[52]}],"verseLabel":"يوسف: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿وأن الله لا يهدي كيد الخائنين﴾؟","answer":"لا يوصله إلى غايته المحمودة؛ فقد طال الكيد لكنه انتهى إلى ظهور البراءة ورفعة من أريد إسقاطه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص776، تحت «بلاغة المجاز في إسناد الهدي إلى الكيد»","url":""}]},{"id":"s12-122","number":122,"surah":12,"verses":[53],"references":[{"surah":12,"verses":[53]}],"verseLabel":"يوسف: 53","question":"ما نكتة توالي المؤكدات في قوله: ﴿إن النفس لأمارة بالسوء﴾؟","answer":"تقرر المؤكدات تمكن هذا الميل في النفس إذا تركت لهواها، وأنها كثيرة الأمر بالسوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص788، تحت «نكتة توالي المؤكدات»","url":""}]},{"id":"s12-240","number":240,"surah":12,"verses":[53],"references":[{"surah":12,"verses":[53]}],"verseLabel":"يوسف: 53","question":"ما دلالة الاستثناء في قوله: ﴿إلا ما رحم ربي﴾؟","answer":"يبين أن العصمة من اندفاع النفس إلى السوء ليست بقوة الإنسان وحده، وإنما برحمة الله وتوفيقه وتزكيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص789، تحت «دلالة الاستثناء في ﴿إلا ما رحم ربي﴾»","url":""}]},{"id":"s12-123","number":123,"surah":12,"verses":[53],"references":[{"surah":12,"verses":[53]}],"verseLabel":"يوسف: 53","question":"ما دلالة ختم الكلام عن النفس بقوله: ﴿إن ربي غفور رحيم﴾؟","answer":"يحث الختام على الرجوع إلى الله والطمع في مغفرته ورحمته بعد الاعتراف بالتقصير. وقدم «غفور» لأن المغفرة رفع للمؤاخذة بالذنب، ثم ذكر الرحمة التي تتضمن الإحسان إلى من غفر له.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص792، تحت «فائدة تذييل الآية بـ﴿غفور رحيم﴾»","url":""}]},{"id":"s12-124","number":124,"surah":12,"verses":[54],"references":[{"surah":12,"verses":[54]}],"verseLabel":"يوسف: 54","question":"ما سرّ التعبير في قول الملك أولًا: ﴿ائتوني به﴾ ثم قال بعد كلامه: ﴿إنك اليوم لدينا مكين أمين﴾؟","answer":"طلبه أولًا إعجابًا بعلمه وبراءته، فلما كلمه اختبر شخصيته فزاده قربًا وثقة؛ انتقل من الاستدعاء إلى التمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص801، تحت «دلالة ذكر جملة ﴿كلمه﴾»","url":""}]},{"id":"s12-125","number":125,"surah":12,"verses":[54],"references":[{"surah":12,"verses":[54]}],"verseLabel":"يوسف: 54","question":"ما دلالة الجمع بين ﴿مكين﴾ و﴿أمين﴾ في وصف يوسف؟","answer":"جمع له المكانة التي يتمكن بها من التصرف والأمانة التي تحفظ ما يوكل إليه. فالصفتان أساس لصلاح من يتولى مصالح الدولة؛ ويذكر المصدر تقديم المكانة لأنها عنوان القدرة على الولاية وتنفيذ شؤونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص804، تحت «علة تقديم ﴿مكين﴾ على ﴿أمين﴾ في السياق»","url":""}]},{"id":"s12-126","number":126,"surah":12,"verses":[55],"references":[{"surah":12,"verses":[55]}],"verseLabel":"يوسف: 55","question":"ما دلالة طلب يوسف تولّي ﴿خزائن الأرض﴾؟","answer":"رأى أزمة قادمة وعلم قدرته على إدارتها، فطلب الولاية للمصلحة العامة لا لمجرد الجاه؛ ويجوز للخبير أن يعرف بكفايته عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص805، تحت «دلالة التعبير في ﴿اجعلني﴾»","url":""}]},{"id":"s12-127","number":127,"surah":12,"verses":[55],"references":[{"surah":12,"verses":[55]}],"verseLabel":"يوسف: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿إني حفيظ عليم﴾؟","answer":"الحفظ أمانة الموارد، والعلم حسن التدبير؛ فجمع الصفتين اللتين تحتاجهما خزائن دولة تستقبل مجاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص807، تحت «نكتة اختيار هذين الوصفين: ﴿حفيظ عليم﴾»","url":""}]},{"id":"s12-128","number":128,"surah":12,"verses":[56],"references":[{"surah":12,"verses":[56]}],"verseLabel":"يوسف: 56","question":"ما نكتة اسم الإشارة للبعيد في قوله: ﴿وكذلك مكنا ليوسف في الأرض﴾؟","answer":"يشير إلى التمكين العظيم الذي دبره الله ليوسف على نحو بعيد المنزلة، بعد انتقاله من السجن إلى الولاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص13، تحت «نكتة التعبير باسم الإشارة للبعيد ﴿وكذلك﴾»","url":""}]},{"id":"s12-241","number":241,"surah":12,"verses":[56],"references":[{"surah":12,"verses":[56]}],"verseLabel":"يوسف: 56","question":"ما بلاغة قوله: ﴿يتبوأ منها حيث يشاء﴾؟","answer":"هو كناية عن سعة تصرف يوسف واستقراره وتمكنه في أرض مصر بعد أن كان مقيدًا في السجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص18، تحت «بلاغة الكناية في ﴿يتبوأ منها حيث يشاء﴾»","url":""}]},{"id":"s12-129","number":129,"surah":12,"verses":[56],"references":[{"surah":12,"verses":[56]}],"verseLabel":"يوسف: 56","question":"ما دلالة قوله بعد تمكين يوسف: ﴿نصيب برحمتنا من نشاء﴾؟","answer":"جاءت الجملة مستأنفة لتقرر أن التمكين أثر من رحمة الله يخص بها من يشاء بحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص18، تحت «نكتة الفصل: ﴿نصيب برحمتنا من نشاء﴾»","url":""}]},{"id":"s12-242","number":242,"surah":12,"verses":[56],"references":[{"surah":12,"verses":[56]}],"verseLabel":"يوسف: 56","question":"ما فائدة عطف قوله: ﴿ولا نضيع أجر المحسنين﴾ على ذكر الرحمة؟","answer":"جمع بين الفضل الإلهي وحفظ جزاء الإحسان؛ فتمكين يوسف رحمة من الله، وهو أيضًا ثمرة إحسان محفوظ لا يضيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص20، تحت «فائدة العطف في ﴿ولا نضيع﴾»","url":""}]},{"id":"s12-130","number":130,"surah":12,"verses":[57],"references":[{"surah":12,"verses":[57]}],"verseLabel":"يوسف: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿ولأجر الآخرة خير للذين آمنوا وكانوا يتقون﴾ بعد تمكين يوسف؟","answer":"حتى لا تنتهي القصة عند نجاح دنيوي؛ فما عند الله خير وأبقى، والتمكين لا يعوض عن أجر الإيمان والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص23، تحت «نكتة إضافة الأجر إلى ﴿الآخرة﴾»","url":""}]},{"id":"s12-131","number":131,"surah":12,"verses":[58],"references":[{"surah":12,"verses":[58]}],"verseLabel":"يوسف: 58","question":"ما دلالة مقابلة ﴿فعرفهم﴾ بقوله: ﴿وهم له منكرون﴾؟","answer":"عرفهم يوسف بمجرد النظر لأن ملامحهم لم تتغير كثيرًا، أما هم فلم يتوقعوا لقاءه في هذه المكانة بعد طول العهد وتغير سنه وهيئته. والجملة الاسمية تصور تمكن عدم معرفتهم به، في مقابل سرعة معرفته لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص33، تحت «نكتة العدول من الجملة الفعلية إلى الاسمية»","url":""}]},{"id":"s12-132","number":132,"surah":12,"verses":[59],"references":[{"surah":12,"verses":[59]}],"verseLabel":"يوسف: 59","question":"ما سرّ التعبير في قول يوسف: ﴿ائتوني بأخ لكم من أبيكم﴾؟","answer":"طلب إحضار أخيهم من أبيهم من غير أن يكشف لهم معرفته بهم، وجعل مجيئه شرطًا لاستمرار الكيل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص36، تحت «معنى الباء، ودلالة تنكير ﴿بأخ﴾»","url":""}]},{"id":"s12-133","number":133,"surah":12,"verses":[59],"references":[{"surah":12,"verses":[59]}],"verseLabel":"يوسف: 59","question":"ما دلالة ترغيبهم بقوله: ﴿ألا ترون أني أوفي الكيل وأنا خير المنزلين﴾؟","answer":"جمع الترغيب المادي وحسن الضيافة ليطمئنوا إلى العودة، ثم أتبع ذلك بالتهديد إن لم يأتوا بأخيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص38، تحت «بلاغة الاستفهام، ونوعه، وغرضه»","url":""}]},{"id":"s12-134","number":134,"surah":12,"verses":[60],"references":[{"surah":12,"verses":[60]}],"verseLabel":"يوسف: 60","question":"ما نكتة قوله: ﴿فلا كيل لكم عندي﴾؟","answer":"نفت ﴿لا﴾ حصول أي كيل لهم نفيًا شاملًا، فجعل إحضار أخيهم شرطًا لا يقبل نقصًا أو تحايلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص44، تحت «نكتة التعبير بـ(لا) النافية للجنس»","url":""}]},{"id":"s12-243","number":243,"surah":12,"verses":[60],"references":[{"surah":12,"verses":[60]}],"verseLabel":"يوسف: 60","question":"ما بلاغة قوله: ﴿ولا تقربون﴾ بعد منع الكيل؟","answer":"هو كناية عن الطرد وقطع المعاملة والضيافة، فزاد التهديد على منع الطعام بمنع القرب كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص47، تحت «بلاغة الكناية في النهي عن القرب»","url":""}]},{"id":"s12-135","number":135,"surah":12,"verses":[61],"references":[{"surah":12,"verses":[61]}],"verseLabel":"يوسف: 61","question":"ما دلالة اختيار فعل المراودة في ﴿سنراود عنه أباه﴾؟","answer":"المراودة طلب متكرر برفق واستمالة، فاختيارها يدل على أنهم يتوقعون شدة تمسك الأب بابنه، وسيبذلون جهدًا لإقناعه. وفي إضافته إلى ضمير أخيهم «أباه» استحضار لخصوص تعلقه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص50، تحت «نكتة التعبير بالمراودة من حيث المادة والصيغة»","url":""}]},{"id":"s12-136","number":136,"surah":12,"verses":[62],"references":[{"surah":12,"verses":[62]}],"verseLabel":"يوسف: 62","question":"ما دلالة رد يوسف بضاعتهم خفية في رحالهم؟","answer":"أراد أن يجدوا ثمن الطعام عند رجوعهم فيعرفوا إكرامه لهم، ويكون ذلك أدعى إلى عودتهم مع أخيهم ويعينهم على شراء الطعام مرة أخرى. ويذكر المصدر أيضًا أنهم قد يتحرجون من المال فيرجعون لرده؛ ولفظ «لعل» يدل على رجاء الرجوع، لا ضمانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص59، تحت «معنى (لعل) في السياق»","url":""}]},{"id":"s12-137","number":137,"surah":12,"verses":[63],"references":[{"surah":12,"verses":[63]}],"verseLabel":"يوسف: 63","question":"ما دلالة بدء خطاب أبيهم بقولهم: ﴿منع منا الكيل﴾؟","answer":"قدموا خبر المنع ليربطوا طلب إرسال أخيهم بالحاجة إلى الطعام. والمراد قرار منع الكيل في الرحلة القادمة إن لم يأتوا به، لا أنهم عادوا هذه المرة بلا طعام؛ ثم جاءت الفاء في «فأرسل» لترتب طلبهم على هذا الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص68، تحت «نكتة تقديم شبه الجملة ﴿منا﴾»","url":""}]},{"id":"s12-138","number":138,"surah":12,"verses":[63],"references":[{"surah":12,"verses":[63]}],"verseLabel":"يوسف: 63","question":"ما دلالة تكرار ضمانهم: ﴿وإنا له لحافظون﴾؟","answer":"كرروا الضمان نفسه الذي قالوه في يوسف، فاستدعى كلامهم ذاكرة الجرح القديم بدل أن يطمئن الأب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71، تحت «بلاغة تتابع المؤكدات في ﴿وإنا له لحافظون﴾»","url":""}]},{"id":"s12-139","number":139,"surah":12,"verses":[64],"references":[{"surah":12,"verses":[64]}],"verseLabel":"يوسف: 64","question":"ما سرّ التعبير في قول يعقوب: ﴿هل آمنكم عليه إلا كما أمنتكم على أخيه من قبل﴾؟","answer":"واجه التكرار بذاكرة التجربة: الضمان البشري فشل من قبل، ولذلك نقل الحفظ إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص79، تحت «الغرض من التشبيه في ﴿إلا كما أمنتكم﴾»","url":""}]},{"id":"s12-140","number":140,"surah":12,"verses":[64],"references":[{"surah":12,"verses":[64]}],"verseLabel":"يوسف: 64","question":"ما دلالة قول يعقوب: ﴿فالله خير حافظًا﴾؟","answer":"يقابل ضمان أبنائه بتفويض الحفظ إلى الله، فحفظه أكمل وأوثق من حفظ المخلوقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص82، تحت «دلالة التعبير بالمسند أفعل تفضيل ﴿خير﴾»","url":""}]},{"id":"s12-244","number":244,"surah":12,"verses":[64],"references":[{"surah":12,"verses":[64]}],"verseLabel":"يوسف: 64","question":"ما بلاغة تذييل قول يعقوب بقوله: ﴿وهو أرحم الراحمين﴾؟","answer":"تذييل ثابت المعنى يستجلب رحمة الله ويرجو أن يحفظ ابنه ويرده، وألا يجمع على يعقوب مصيبتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص84، تحت «بلاغة التذييل بالجملة الاسمية»","url":""}]},{"id":"s12-141","number":141,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما دلالة ﴿ما﴾ في قولهم: ﴿ما نبغي﴾؟","answer":"تحتمل الاستفهام: أي شيء نطلب بعد هذا الإحسان؟ وتحتمل النفي: لا نطلب فوق ما وجدنا؛ وفي الوجهين يظهر تعجبهم من رد بضاعتهم واستعطافهم أباهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص96، تحت «دلالة ﴿ما﴾ في قوله ﴿ما نبغي﴾»","url":""}]},{"id":"s12-245","number":245,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما موقع قولهم ﴿هذه بضاعتنا ردت إلينا﴾ من حجتهم؟","answer":"جاءت الجملة بيانًا عمليًا لما قبلها؛ فرد البضاعة برهان على إكرام العزيز لهم، وحجة يقنعون بها أباهم بإرسال أخيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص98، تحت «موقع ﴿هذه بضاعتنا﴾ مما قبلها ودلالته»","url":""}]},{"id":"s12-142","number":142,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما سر التعبير بـ﴿كيل بعير﴾ في قولهم: ﴿ونزداد كيل بعير﴾؟","answer":"حددت الإضافة مقدار الزيادة تحديدًا محسوسًا: حمل بعير كامل يخص أخاهم إذا صحبهم، فقرّبت المنفعة التي يرجونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص106، تحت «سر التعبير بالمفعول به مضافًا ﴿كيل بعير﴾»","url":""}]},{"id":"s12-246","number":246,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما دلالة قولهم: ﴿ذلك كيل يسير﴾؟","answer":"طمأنوا أباهم بأن زيادة حمل بعير أمر يسير على العزيز، ويحتمل أيضًا أن الموجود عندهم يسير لا يكفيهم؛ وكلا الوجهين يقوي طلب الرجوع بأخيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص107، تحت «موقع قوله: ﴿ذلك كيل يسير﴾ ودلالته»","url":""}]},{"id":"s12-143","number":143,"surah":12,"verses":[66],"references":[{"surah":12,"verses":[66]}],"verseLabel":"يوسف: 66","question":"ما دلالة طلب يعقوب ﴿موثقًا من الله﴾؟","answer":"أراد عهدًا عظيمًا مؤكدًا بالله، يجعل الوفاء به مسؤولية دينية لا مجرد وعد عائلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص118، تحت «الغرض من تنكير المفعول به ﴿موثقًا﴾»","url":""}]},{"id":"s12-247","number":247,"surah":12,"verses":[66],"references":[{"surah":12,"verses":[66]}],"verseLabel":"يوسف: 66","question":"لماذا استثنى يعقوب قوله: ﴿إلا أن يحاط بكم﴾؟","answer":"استثنى ما يغلب طاقتهم من هلاك أو عجز يسد سبل الخلاص؛ لأن العهد إنما يلزمهم فيما يملكون فعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص119، تحت «دلالة الاستثناء في ﴿إلا أن يحاط بكم﴾»","url":""}]},{"id":"s12-144","number":144,"surah":12,"verses":[66],"references":[{"surah":12,"verses":[66]}],"verseLabel":"يوسف: 66","question":"ما سر قول يعقوب: ﴿الله على ما نقول وكيل﴾ في جملة اسمية؟","answer":"تفيد الجملة ثبوت رقابة الله وحفظه للعهد؛ فانتقل التوثق من اتفاق بينهم إلى مسؤولية دائمة أمام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص124، تحت «سر التعبير بمقول قوله جملة اسمية»","url":""}]},{"id":"s12-145","number":145,"surah":12,"verses":[67],"references":[{"surah":12,"verses":[67]}],"verseLabel":"يوسف: 67","question":"لماذا أمر يعقوب أبناءه أن يدخلوا من أبواب ﴿متفرقة﴾؟","answer":"أخذ بسبب الحذر من لفت الأنظار أو إصابة العين وهم جماعة ذوو هيئة، من غير اعتقاد أن السبب يرد قدر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص136، تحت «سر وصف أبواب بـ﴿متفرقة﴾»","url":""}]},{"id":"s12-146","number":146,"surah":12,"verses":[67],"references":[{"surah":12,"verses":[67]}],"verseLabel":"يوسف: 67","question":"ما دلالة النفي في قول يعقوب: ﴿وما أغني عنكم من الله من شيء﴾؟","answer":"ينفي أن تكون نصيحته ضامنة للسلامة؛ فهي سبب يؤخذ به، أما دفع قضاء الله فليس في قدرة بشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص137، تحت «دلالة ﴿ما﴾ النافية في قوله: ﴿وما أغني﴾»","url":""}]},{"id":"s12-248","number":248,"surah":12,"verses":[67],"references":[{"surah":12,"verses":[67]}],"verseLabel":"يوسف: 67","question":"ما دلالة القصر في قوله: ﴿إن الحكم إلا لله﴾؟","answer":"قصر الحكم على الله يقرر أن التدبير كله خاضع لقضائه، ولذلك صح أن يعقبه بتخصيصه بالتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص140، تحت «غرض التعبير بالقصر في السياق»","url":""}]},{"id":"s12-147","number":147,"surah":12,"verses":[68],"references":[{"surah":12,"verses":[68]}],"verseLabel":"يوسف: 68","question":"ما دلالة الاستثناء في قوله: ﴿إلا حاجة في نفس يعقوب قضاها﴾؟","answer":"يبين أن الدخول المتفرق لم يغير قدرًا مقدرًا، وإنما حقق حاجة يعقوب إلى الاحتياط والأخذ بالسبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص152، تحت «دلالة الاستثناء في قوله: ﴿إلا حاجة﴾»","url":""}]},{"id":"s12-148","number":148,"surah":12,"verses":[69],"references":[{"surah":12,"verses":[69]}],"verseLabel":"يوسف: 69","question":"ما دلالة قوله تعالى: ﴿آوى إليه أخاه﴾؟","answer":"صور ضم يوسف أخاه وتقريبه إليه بالإيواء؛ فانتقل به من الوحشة والخوف إلى الأنس والأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص168، تحت «غرض التعبير بالمجاز في قوله ﴿آوى﴾»","url":""}]},{"id":"s12-249","number":249,"surah":12,"verses":[69],"references":[{"surah":12,"verses":[69]}],"verseLabel":"يوسف: 69","question":"لماذا أكد يوسف قوله لأخيه: ﴿إني أنا أخوك﴾؟","answer":"تتابع التوكيد ليزيل استغراب الأخ بعد طول الغياب، ويثبت له حقيقة الأخوة بما يبدد خوفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص170، تحت «سر التعبير بالجملة الاسمية المؤكدة ثلاثًا»","url":""}]},{"id":"s12-250","number":250,"surah":12,"verses":[69],"references":[{"surah":12,"verses":[69]}],"verseLabel":"يوسف: 69","question":"ما غرض قوله لأخيه: ﴿فلا تبتئس بما كانوا يعملون﴾؟","answer":"نهى عن الحزن تسليةً له عما لقيه من إخوته، وطمأنه إلى أن الاجتماع بعد الفرقة قد أبدل الوحشة أمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص172، تحت «الغرض من التعبير بأسلوب النهي»","url":""}]},{"id":"s12-149","number":149,"surah":12,"verses":[70],"references":[{"surah":12,"verses":[70]}],"verseLabel":"يوسف: 70","question":"ما مناسبة جعل السقاية في رحل أخي يوسف لما سبق من تدبيره؟","answer":"كان جعل السقاية سببًا ظاهرًا يفتح طريق التفتيش ثم استبقاء أخيه وفق الحكم الذي سيقرره الإخوة أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص178، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s12-251","number":251,"surah":12,"verses":[70],"references":[{"surah":12,"verses":[70]}],"verseLabel":"يوسف: 70","question":"ما دلالة قوله تعالى: ﴿كذلك كدنا ليوسف﴾؟","answer":"ينسب السياق تعليم هذا التدبير المحكم إلى الله؛ فالكيد هنا تدبير خفي لتحقيق غاية مشروعة، لا سرقة حقيقية ولا ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص227، تحت «دلالة التعبير بالكيد على التعليم»","url":""}]},{"id":"s12-150","number":150,"surah":12,"verses":[70],"references":[{"surah":12,"verses":[70]}],"verseLabel":"يوسف: 70","question":"ما أثر التوكيد في النداء: ﴿أيتها العير إنكم لسارقون﴾؟","answer":"جاء النداء والاسمية و«إن» واللام لتوقيف القافلة واستدعاء جوابها، وتصوير الاتهام في صورة جازمة بحسب ظاهر الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص186، تحت «بلاغة جمع المؤكدات في جملة الفاصلة»","url":""}]},{"id":"s12-252","number":252,"surah":12,"verses":[70],"references":[{"surah":12,"verses":[70]}],"verseLabel":"يوسف: 70","question":"كيف يوجه إطلاق السرقة على إخوة يوسف؟","answer":"من أوجهه أن المنادي تكلم بحسب ظنه، أو أن الوصف عرّض بفعلهم القديم حين أخذوا يوسف من أبيه؛ فلا يلزم منه إثبات سرقة السقاية عليهم حقيقةً.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص187، تحت «وجه إطلاق السرقة عليهم»","url":""}]},{"id":"s12-151","number":151,"surah":12,"verses":[71],"references":[{"surah":12,"verses":[71]}],"verseLabel":"يوسف: 71","question":"ما دلالة إقبال الإخوة وسؤالهم: ﴿ماذا تفقدون﴾؟","answer":"إقبالهم على المنادي، بدل الهرب أو التجنب، يدل على ثقتهم ببراءتهم واستعدادهم للمواجهة. وقد سمعوا اتهام السرقة، لكنهم لم يعرفوا الشيء المفقود؛ فسألوا عنه بلفظ الفقد، مترفعين عن نسبة السرقة إلى أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص191–193، تحت «إيثار لفظ «وأقبلوا»؛ دلالة شبه الجملة؛ دلالة الاستفهام؛ إيثار التعبير بـ«تفقدون»»","url":""}]},{"id":"s12-152","number":152,"surah":12,"verses":[72],"references":[{"surah":12,"verses":[72]}],"verseLabel":"يوسف: 72","question":"ما دلالة الجمع بين ﴿حمل بعير﴾ و﴿وأنا به زعيم﴾؟","answer":"حمل البعير مكافأة وافرة من الطعام في وقت المجاعة، تحث على إحضار الصواع أو الدلالة عليه. ثم أكد المنادي ضمانه لها بقوله ﴿وأنا به زعيم﴾، أي كفيل ملتزم بأدائها؛ فاجتمع الترغيب بالمكافأة والتطمين إلى الوفاء بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص198–201، تحت «نكتة تخصيص المكافأة بـ«حمل بعير»؛ سر إيثار التعبير بـ«زعيم»؛ نكتة التعبير بصيغة فعيل»","url":""}]},{"id":"s12-153","number":153,"surah":12,"verses":[73],"references":[{"surah":12,"verses":[73]}],"verseLabel":"يوسف: 73","question":"ما أثر القسم بالتاء في قولهم: ﴿تالله لقد علمتم﴾؟","answer":"يفيد التعجب من اتهامهم مع تقوية احتجاجهم، إذ استشهدوا بما عرفه المخاطبون من سيرتهم وأمانتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص204، تحت «وجه القسم بالتاء وأثره»","url":""}]},{"id":"s12-253","number":253,"surah":12,"verses":[73],"references":[{"surah":12,"verses":[73]}],"verseLabel":"يوسف: 73","question":"لماذا قالوا: ﴿ما جئنا لنفسد﴾ ثم ﴿وما كنا سارقين﴾؟","answer":"نفوا أولًا قصد الإفساد وهو أعم، ثم نفوا أن تكون السرقة وصفًا ثابتًا فيهم؛ فجمعوا بين نفي القصد السيئ ونفي رسوخ الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص209، تحت «براعة تباين الأسلوب في نفي السرقة، ونفي الإفساد»","url":""}]},{"id":"s12-154","number":154,"surah":12,"verses":[74,75],"references":[{"surah":12,"verses":[74,75]}],"verseLabel":"يوسف: 74–75","question":"ما دلالة سؤالهم: ﴿فما جزاؤه إن كنتم كاذبين﴾؟","answer":"أرادوا أن يقر الإخوة بأنفسهم جزاء من توجد السقاية في رحله، ليجري استبقاء أخي يوسف وفق الحكم الذي اختاروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص213، تحت «بلاغة الاستفهام ودلالته»","url":""}]},{"id":"s12-155","number":155,"surah":12,"verses":[76],"references":[{"surah":12,"verses":[76]}],"verseLabel":"يوسف: 76","question":"ما سر البدء بأوعية الإخوة ثم وعاء أخي يوسف؟","answer":"أفادت ﴿ثم﴾ الترتيب المقصود؛ فأخر وعاء أخيه ليجري التفتيش في صورة طبيعية بعيدة عن التهمة، ثم يظهر المطلوب في النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص225، تحت «سر إيثار العطف بـ«ثم»»","url":""}]},{"id":"s12-156","number":156,"surah":12,"verses":[76],"references":[{"surah":12,"verses":[76]}],"verseLabel":"يوسف: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك كدنا ليوسف﴾؟","answer":"المقصود تدبير الله ليوسف وتعليمه الحيلة التي أبقى بها أخاه، بأن أجرى الأخذ وفق الحكم الذي قرره الإخوة أنفسهم. وإسناد الكيد إلى الله هنا يدل على تدبير نافذ خفي عنهم، والإشارة في ﴿كذلك﴾ تعظم شأن هذا التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص226–228، تحت «توجيه الإشارة في «كذلك»؛ سر التعبير بلفظ الكيد مضافًا إلى ضمير التعظيم؛ دلالة التعبير بالكيد على التعليم»","url":""}]},{"id":"s12-157","number":157,"surah":12,"verses":[76],"references":[{"surah":12,"verses":[76]}],"verseLabel":"يوسف: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان ليأخذ أخاه في دين الملك إلا أن يشاء الله﴾؟","answer":"قانون الملك لا يجيز استبقاء السارق بهذه الصورة، فجعل الله الإخوة ينطقون بالحكم الذي يسمح ليوسف بأخذ أخيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص228–230، تحت «دلالة النفي في «ما كان ليأخذ»؛ دلالة اللام في حيز النفي؛ دلالة تعليق فعل الأخذ، بالجار والمجرور؛ بلاغة جملة الاستثناء»","url":""}]},{"id":"s12-158","number":158,"surah":12,"verses":[76],"references":[{"surah":12,"verses":[76]}],"verseLabel":"يوسف: 76","question":"ما دلالة قوله تعالى: ﴿وفوق كل ذي علم عليم﴾؟","answer":"يجعل العلم درجات لا يحيط صاحب درجة بما فوقها، وينتهي كمال العلم إلى الله؛ فمهما بلغ العالم بقي فوقه من هو أعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص234، تحت «بلاغة التعبير بـ«ذي علم»»","url":""}]},{"id":"s12-159","number":159,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"ما دلالة قولهم: ﴿إن يسرق فقد سرق أخ له من قبل﴾ في جملة شرطية؟","answer":"علقوا اتهامهم القديم على فرض سرقته الحاضرة، ليوهموا أن الفعل متكرر في الأخوين ويبعدوا التهمة عن أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص239، تحت «دلالة التعبير بالجملة الشرطية»","url":""}]},{"id":"s12-254","number":254,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"لماذا قالوا: ﴿أخ له﴾ ولم يصرحوا بأخوتهم جميعًا؟","answer":"أضافوا الأخ إليه وحده تنصلًا منهما وإشعارًا بأنهما منفصلان عن بقية الإخوة في هذا الوصف المزعوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص240، تحت «علة التعبير بشبه الجملة «له»»","url":""}]},{"id":"s12-160","number":160,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"ما دلالة الجمع بين ﴿فأسرها يوسف في نفسه﴾ و﴿ولم يبدها لهم﴾؟","answer":"أكد الجمع بين الإسرار ونفي الإبداء شدة كظمه وتحمله للأذى؛ فلم يظهر لهم غضبه ولا ما يدور في نفسه بقول أو فعل. ويبين السياق ما قاله في نفسه: ﴿أنتم شر مكانًا والله أعلم بما تصفون﴾؛ فالمقام ثناء على ضبط النفس مع شدة الإساءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص240–244، تحت «نكتة تضعيف فعل الإسرار «فأسرها»؛ بلاغة الإطناب؛ إيثار لفظ يبدي على يظهر؛ بلاغة الاستئناف»","url":""}]},{"id":"s12-161","number":161,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"ما دلالة اسم التفضيل في قول يوسف: ﴿أنتم شر مكانًا﴾؟","answer":"رد الاتهام عن أخيه بأن مكانهم في الشر أشد، لأنهم جمعوا الإساءة القديمة إلى يوسف مع الافتراء الجديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص245، تحت «دلالة التعبير باسم التفضيل»","url":""}]},{"id":"s12-255","number":255,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"ما دلالة قوله: ﴿والله أعلم بما تصفون﴾؟","answer":"سمى كلامهم وصفًا لا حقيقة مقررة، وفوض علم باطنه إلى الله؛ فجمع الرد المهذب مع تكذيب افترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص246، تحت «دلالة الفعل «تصفون»»","url":""}]},{"id":"s12-162","number":162,"surah":12,"verses":[78],"references":[{"surah":12,"verses":[78]}],"verseLabel":"يوسف: 78","question":"لماذا نادوا يوسف بقولهم: ﴿يا أيها العزيز﴾؟","answer":"توسلوا إليه بلقب سلطانه واستعطفوا صاحب القدرة على تنفيذ طلبهم، وفيه تعظيم يهيئ لقبول الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص249، تحت «وجه نداء يوسف بصفة العزيز»","url":""}]},{"id":"s12-256","number":256,"surah":12,"verses":[78],"references":[{"surah":12,"verses":[78]}],"verseLabel":"يوسف: 78","question":"ما أثر جمعهم صفات أبيهم عند التماسهم أخذ أحدهم مكان أخيهم؟","answer":"جمعوا كبره وضعفه وشدة تعلقه بابنه في أوصاف منكرة تفخم الحال، ليستدروا عطف يوسف ويقووا طلب المبادلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص251، تحت «سر جمع ثلاث صفات منكرة»","url":""}]},{"id":"s12-163","number":163,"surah":12,"verses":[78],"references":[{"surah":12,"verses":[78]}],"verseLabel":"يوسف: 78","question":"ما دلالة قول إخوة يوسف: ﴿إنا نراك من المحسنين﴾ في مقام استعطافه؟","answer":"جعلوا ما عرفوه من إحسانه علةً لرجاء استجابته وأخذ أحدهم مكان أخيهم؛ فالوصف مبني على أثر رأوه منه، لا على مدح مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص255، تحت «وجه التعليل في جملة الفاصلة»","url":""}]},{"id":"s12-164","number":164,"surah":12,"verses":[79],"references":[{"surah":12,"verses":[79]}],"verseLabel":"يوسف: 79","question":"ما سر قول يوسف: ﴿معاذ الله﴾ عند طلب أخذ بريء مكان أخيه؟","answer":"المصدر الميمي يصور استعاذة راسخة والتجاءً إلى الله من فعل الظلم، فجاء رفضه مبدئيًا لا مجرد تعذر إداري.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص257، تحت «نكتة التعبير بالمصدر الميمي»","url":""}]},{"id":"s12-257","number":257,"surah":12,"verses":[79],"references":[{"surah":12,"verses":[79]}],"verseLabel":"يوسف: 79","question":"لماذا قال يوسف: ﴿إلا من وجدنا متاعنا عنده﴾ ولم يقل: من سرق؟","answer":"التزم بالحقيقة التي ثبتت في المشهد وهي وجود المتاع عنده، ولم ينسب إليه سرقة لم تقع؛ وفي ذلك دقة وعدل في العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص261، تحت «نكتة العدول عن الفعل سرق إلى الفعل «وجدنا»»","url":""}]},{"id":"s12-165","number":165,"surah":12,"verses":[80],"references":[{"surah":12,"verses":[80]}],"verseLabel":"يوسف: 80","question":"ما سرّ التعبير عن جماعة الإخوة بالمفرد ﴿نجيًا﴾؟","answer":"انفردوا عن الناس يتناجون سرًا بعد يأسهم من إطلاق أخيهم. و«نجي» يصح إطلاقه على الواحد والجماعة، ومن توجيهاته أنه مصدر وصف به الجمع للمبالغة، فكأنهم في تلك الساعة صاروا مناجاة خالصة؛ فجمعت العبارة القصيرة اعتزال الناس والتشاور المكتوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص267–270، تحت «نكتة التعبير بلفظ «نجيًا»، في هذه الآية القرآنية؛ دلالة مجيء الحال «نجيًا»، مصدرًا في السياق؛ بلاغة الإيجاز في قولهم «خلصوا نجيًا»»","url":""}]},{"id":"s12-166","number":166,"surah":12,"verses":[80],"references":[{"surah":12,"verses":[80]}],"verseLabel":"يوسف: 80","question":"ما سرّ التعبير في قول كبيرهم: ﴿ومن قبل ما فرطتم في يوسف﴾؟","answer":"ذكّرهم كبيرهم بتقصيرهم السابق في حق يوسف ليزيد تأكيد مسؤوليتهم عن الميثاق الجديد. ولفظ التفريط يصور تضييع الحق وإهمال حفظه؛ فاجتمع في عتابه العهد الذي قطعوه الآن والسابقة التي تجعل رجوعهم دون أخيهم أشد على أبيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص274–276، تحت «موقع جملة «ومن قبل ما فرطتم»؛ دلالة التعبير بالتفريط في «فرطتم»؛ دلالة الظرفية في قوله «في يوسف»»","url":""}]},{"id":"s12-167","number":167,"surah":12,"verses":[80],"references":[{"surah":12,"verses":[80]}],"verseLabel":"يوسف: 80","question":"ما دلالة قرار كبيرهم: ﴿فلن أبرح الأرض حتى يأذن لي أبي أو يحكم الله لي﴾؟","answer":"فرع قراره بالبقاء في مصر على الميثاق الذي أخذه أبوهم وعلى تفريطهم السابق في يوسف؛ فلا يرجع من تلقاء نفسه، بل ينتظر إذن أبيه أو ما يقضي الله به في أمره. وتقديم إذن الأب يراعي حقه المباشر في العهد، ثم تفويض الأمر إلى الله يدل على الرضا بحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص271–272، 275–277، 279–282، تحت «نوع الاستفهام وغرضه، في «ألم تعلموا»؛ معنى الفاء في قوله تعالى «فلن أبرح»؛ وجه تقديم إذن الأب، على إذن الله تعالى؛ سر حذف متعلق «يحكم»، في السياق المحكم»","url":""}]},{"id":"s12-168","number":168,"surah":12,"verses":[81],"references":[{"surah":12,"verses":[81]}],"verseLabel":"يوسف: 81","question":"لماذا قال كبيرهم: ﴿ارجعوا إلى أبيكم﴾ ولم يقل: أبينا؟","answer":"واجههم بمسؤوليتهم في الرجوع والخبر، وأضاف الأب إليهم ليحملهم تبعة الموقف، مع ما يشعر به من انفرادٍ عن تصرفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص273، تحت «سر إضافة الأب إلى ضمير المخاطب، دون التكلم»","url":""}]},{"id":"s12-169","number":169,"surah":12,"verses":[81],"references":[{"surah":12,"verses":[81]}],"verseLabel":"يوسف: 81","question":"ما وجه قولهم: ﴿وما شهدنا إلا بما علمنا وما كنا للغيب حافظين﴾؟","answer":"قصروا شهادتهم على ما ظهر لهم من استخراج الصواع من وعاء أخيهم، ثم احترسوا بقولهم ﴿وما كنا للغيب حافظين﴾: فهم لم يشاهدوا فعل السرقة نفسه، ولا يعلمون خفايا الواقعة. فالمقصود بيان مستند خبرهم وحدوده، لا الجزم بأن ظاهر الأمر يكشف حقيقته كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص288–291، تحت «بلاغة القصر في قوله «وما شهدنا إلا بما علمنا»؛ لفظ العلم بين المجاز والاستعارة؛ بلاغة الاحتراس، في السياق»","url":""}]},{"id":"s12-170","number":170,"surah":12,"verses":[82],"references":[{"surah":12,"verses":[82]}],"verseLabel":"يوسف: 82","question":"ما دلالة قولهم: ﴿واسأل القرية التي كنا فيها﴾؟","answer":"أسند السؤال إلى المكان والمراد أهله، ليبلغ الكلام غاية الاختصار ويؤكد أن الخبر مشهور يمكن التثبت منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص292، تحت «بلاغة المجاز العقلي، في إسناد السؤال للقرية»","url":""}]},{"id":"s12-258","number":258,"surah":12,"verses":[82],"references":[{"surah":12,"verses":[82]}],"verseLabel":"يوسف: 82","question":"ما دلالة قولهم: ﴿والعير التي أقبلنا فيها﴾؟","answer":"أطلقوا العير وأرادوا أصحاب القافلة، فوسعوا دائرة الشهادة وأظهروا أن الواقعة معلومة لمن صحبهم أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص294، تحت «بلاغة المجاز في سؤال العير»","url":""}]},{"id":"s12-171","number":171,"surah":12,"verses":[83],"references":[{"surah":12,"verses":[83]}],"verseLabel":"يوسف: 83","question":"ما دلالة تكرر ﴿بل سولت لكم أنفسكم أمرًا فصبر جميل﴾ في محنتي يوسف وأخيه؟","answer":"يعيد اللفظ تذكيرهم بما وقع في يوسف، ويصل المحنة الجديدة بأثر تلك السابقة، مع تعدد توجيهات التسويل في الموضع الثاني. وفي الحالين يلجأ يعقوب إلى الصبر الجميل، ثم يصرح هنا برجاء اجتماع أبنائه بقوله ﴿عسى الله أن يأتيني بهم جميعًا﴾؛ فتجدد المصاب لم يقطع رجاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص300–305، تحت «دلالة وصف الصبر بلفظ «جميل»؛ المتشابه اللفظي في «بل سولت»»","url":""}]},{"id":"s12-172","number":172,"surah":12,"verses":[83],"references":[{"surah":12,"verses":[83]}],"verseLabel":"يوسف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يأتيني بهم جميعًا﴾ مع أن الخبر عن بنيامين؟","answer":"يرجو يعقوب اجتماع يوسف وأخيه والكبير الذي بقي في مصر؛ فجاء ضمير الجمع و﴿جميعًا﴾ ليتسع الرجاء لكل الغائبين. وهذا رجاء مؤسس على علم الله وحكمته، كما دل ختام الآية، لا مجرد انشغال بالمفقود الأخير وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص303–304، 308، تحت «معنى لفظ «عسى» في سياق الآية الكريمة؛ دلالة الموقع النحوي للفظ «جميعًا»؛ نكتة التذييل بالاسمين «العليم الحكيم»»","url":""}]},{"id":"s12-173","number":173,"surah":12,"verses":[84],"references":[{"surah":12,"verses":[84]}],"verseLabel":"يوسف: 84","question":"ما دلالة نداء يعقوب: ﴿يا أسفى على يوسف﴾؟","answer":"صور الأسف كأنه حاضر ينادى، مبالغةً في استحضار الحزن وتجدد الألم حين أعاد فقد الابن ذكرى يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص309، تحت «مجازات النداء وغرضه، في قوله «يا أسفى»»","url":""}]},{"id":"s12-259","number":259,"surah":12,"verses":[84],"references":[{"surah":12,"verses":[84]}],"verseLabel":"يوسف: 84","question":"لماذا خص يعقوب يوسف بالأسف مع تجدد فقد أخيه؟","answer":"لأن حزن يوسف كان الأصل الأقدم والأعمق، فجددت المصيبة الجديدة ذلك الجرح الكامن فغلب اسمه على التعبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص310، تحت «نكتة الاقتصار على التأسف على يوسف دون غيره»","url":""}]},{"id":"s12-174","number":174,"surah":12,"verses":[84],"references":[{"surah":12,"verses":[84]}],"verseLabel":"يوسف: 84","question":"ما دلالة الجمع بين ﴿وابيضت عيناه من الحزن﴾ و﴿فهو كظيم﴾؟","answer":"يصور ابيضاض العينين شدة أثر الحزن والبكاء في الجسد، بينما يدل ﴿كظيم﴾ على حبس الحزن وكتمه؛ وأصله إغلاق السقاء على ما فيه. فاجتمع ظهور أثر الألم مع إمساك النفس عن بث الشكوى للناس، دون أن ينافي ذلك شكواه إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص312–315، تحت «بلاغة الكناية في «وابيضت عيناه»؛ نكتة إيثار التعبير بـ«كظيم»، مادة وصيغة؛ بلاغة الاستعارة في لفظ كظيم»","url":""}]},{"id":"s12-175","number":175,"surah":12,"verses":[85],"references":[{"surah":12,"verses":[85]}],"verseLabel":"يوسف: 85","question":"ما وجه قولهم: ﴿تالله تفتأ تذكر يوسف حتى تكون حرضًا أو تكون من الهالكين﴾؟","answer":"تعجبوا من استمرار ذكره يوسف، وحذروه من أن ينتهي به الحزن إلى شدة المرض أو الهلاك؛ فـ﴿تفتأ﴾ هنا بمعنى لا تزال، وقد حذف النفي لدلالة القسم والسياق عليه. ثم أوضح يعقوب في جوابه أن شكواه إلى الله، فلا يصح أن يفهم حزنه على أنه انقطاع للرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص319–323، 328–329، تحت «نكتة القسم بـ«تالله» دون غيرها؛ نكتة التعبير بـ«تفتأ»، مادة وصيغة؛ نكتة التعبير بلفظ «حرضًا»؛ بلاغة تقديم الحرض على الهلاك؛ بلاغة القصر بالأداة «إنما»»","url":""}]},{"id":"s12-176","number":176,"surah":12,"verses":[86],"references":[{"surah":12,"verses":[86]}],"verseLabel":"يوسف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما أشكو بثي وحزني إلى الله﴾؟","answer":"حصر شكواه في الله؛ والبث حزن لا يستطيع صاحبه كتمانه، أما الصبر الجميل فلا يمنع إظهار الافتقار للخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص328–332، تحت «بلاغة القصر بالأداة «إنما»؛ دلالة تسمية الهم الثقيل بالبث؛ نكتة الجمع بين البث والحزن»","url":""}]},{"id":"s12-177","number":177,"surah":12,"verses":[86],"references":[{"surah":12,"verses":[86]}],"verseLabel":"يوسف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿وأعلم من الله ما لا تعلمون﴾؟","answer":"يبين يعقوب أن رجاءه يستند إلى علم من الله لا يحيط به أبناؤه. ومن توجيهات ذلك علمه بلطف الله ورحمته، أو بما أعلمه من حياة يوسف؛ وتذكر الموسوعة ثقته بأن رؤيا يوسف لم يتم تأويلها بعد. لذلك لم يحكم على الأمر بظاهره، ولم ينقطع أمله في الفرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص332–334، 340، تحت «نكتة العطف في جملة «وأعلم»؛ معنى الحرف «من» في سياق الآية؛ معنى الحرف «ما» في السياق الكريم؛ براعة توطئة الأمر بالنداء»","url":""}]},{"id":"s12-178","number":178,"surah":12,"verses":[87],"references":[{"surah":12,"verses":[87]}],"verseLabel":"يوسف: 87","question":"ما دلالة الأمر ﴿اذهبوا فتحسسوا من يوسف وأخيه﴾؟","answer":"التحسس طلب أخبارهما والتعرف إلى موضعهما بالحواس، سماعًا أو مشاهدة. وقد قدم الأمر بالذهاب ليربط البحث بالحركة والوصول إلى موضع السؤال؛ فرجاؤه في الله دفعه إلى توجيههم للتحري والعمل، ولم يبق رجاءً بلا سعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص340–342، تحت «نكتة انتقاء مفردة «اذهبوا»؛ بلاغة تفريع الأمر بالتحسس على الذهاب؛ معنى حرف «من»»","url":""}]},{"id":"s12-179","number":179,"surah":12,"verses":[87],"references":[{"surah":12,"verses":[87]}],"verseLabel":"يوسف: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تيأسوا من روح الله﴾؟","answer":"روح الله فرجه ورحمته التي تحيي القلب بعد الاختناق؛ واليأس منها سوء معرفة بسعة قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص343–347، تحت «براعة التعبير بمفردة «روح»؛ دلالة الإضافة؛ بلاغة القصر؛ توجيه تخصيص الكفر بالذكر»","url":""}]},{"id":"s12-180","number":180,"surah":12,"verses":[88],"references":[{"surah":12,"verses":[88]}],"verseLabel":"يوسف: 88","question":"ما غرض قولهم: ﴿مسنا وأهلنا الضر﴾؟","answer":"قدموا وصف حاجتهم لاستدرار الرحمة، وذكر الأهل يزيد الاستعطاف لأن وراءهم من ينتظر القوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص355، تحت «غرض الإخبار بالاحتياج والعوز»","url":""}]},{"id":"s12-260","number":260,"surah":12,"verses":[88],"references":[{"surah":12,"verses":[88]}],"verseLabel":"يوسف: 88","question":"ما دلالة وصف بضاعتهم بأنها ﴿مزجاة﴾؟","answer":"تصف بضاعة قليلة أو رديئة تُدفع ولا يرغب فيها عادة، فبينت ضعف ما يملكونه من ثمن وشدة حاجتهم إلى المسامحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص358، تحت «نكتة وصف البضاعة بلفظ «مزجاة»»","url":""}]},{"id":"s12-181","number":181,"surah":12,"verses":[88],"references":[{"surah":12,"verses":[88]}],"verseLabel":"يوسف: 88","question":"ما غرض قولهم: ﴿فأوف لنا الكيل﴾؟","answer":"طلبوا إتمام الكيل وألا ينقص بسبب قلة بضاعتهم أو رداءتها، بعد أن مهدوا بذكر حاجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص358، تحت «غرض الأمر»","url":""}]},{"id":"s12-261","number":261,"surah":12,"verses":[88],"references":[{"surah":12,"verses":[88]}],"verseLabel":"يوسف: 88","question":"ما دلالة إطلاق قولهم: ﴿وتصدق علينا﴾ من غير تعيين؟","answer":"حذف متعلق التصدق ليتسع لكل إحسان ممكن؛ من المسامحة في الثمن أو الزيادة في الكيل أو تفريج كربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص360، تحت «بلاغة إطلاق الفعل بحذف متعلقه»","url":""}]},{"id":"s12-182","number":182,"surah":12,"verses":[89],"references":[{"surah":12,"verses":[89]}],"verseLabel":"يوسف: 89","question":"ما دلالة تمهيد يوسف للتعريف بنفسه بسؤال ﴿هل علمتم ما فعلتم بيوسف وأخيه إذ أنتم جاهلون﴾؟","answer":"ذكّرهم بسوء ما فعلوه ليوقظ إدراكهم لقبحه، وفي السؤال توبيخ على أمر يعلمونه. ثم لطف بهم بإرجاع ذلك إلى زمن جهلهم، إيماءً إلى إمكان الرجوع عن تلك الحال؛ فجمع بين تذكيرهم بالذنب وفتح باب الاعتذار، دون تعيير جارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص368–372، تحت «نكتة إيثار أداة «هل» على الهمزة؛ معنى «ما» ودلالتها؛ براعة الإيماء دون التصريح»","url":""}]},{"id":"s12-183","number":183,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"ما أثر التوكيد في قولهم: ﴿أإنك لأنت يوسف﴾؟","answer":"تراكم الاستفهام و«إن» واللام وضمير الفصل يصور صدمة التعرف: فالعزيز الذي أمامهم هو أخوهم الذي ألقوه في الجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص373، تحت «براعة التأكيد وأثره في تصوير المشهد النفسي»","url":""}]},{"id":"s12-184","number":184,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"لماذا أجاب يوسف: ﴿أنا يوسف﴾ ولم يكتف بنعم؟","answer":"صرح باسمه ليحقق التعرف ويستحضر القصة الماضية، فجاء الجواب أوقع في نفوسهم من مجرد التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص374، تحت «بلاغة العدول عن الجواب الموجز إلى التكرار»","url":""}]},{"id":"s12-262","number":262,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"ما دلالة قوله: ﴿وهذا أخي﴾؟","answer":"أشار إلى أخيه الحاضر تشريفًا له وإظهارًا لاجتماعهما بعد الفرقة، وفي القرب الحسي ما يجسد تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص374، تحت «دلالة التعبير باسم الإشارة للقريب»","url":""}]},{"id":"s12-263","number":263,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"لماذا قال يوسف: ﴿قد من الله علينا﴾؟","answer":"اختار المن ليجعل ما حصلا عليه من حفظ وتمكين واجتماع فضلًا عظيمًا خالصًا من الله، لا ثمرة قدرة ذاتية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص375، تحت «نكتة اختيار لفظ المن»","url":""}]},{"id":"s12-185","number":185,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"ما دلالة قوله: ﴿من يتق ويصبر فإن الله لا يضيع أجر المحسنين﴾؟","answer":"جعلها قاعدة عامة بالشرط: كل من يجمع التقوى والصبر فهو من المحسنين الذين لا يضيع الله أجرهم، فلا تختص العبرة بقصة يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص377، تحت «معنى «من» ودلالتها الشرطية»","url":""}]},{"id":"s12-186","number":186,"surah":12,"verses":[91],"references":[{"surah":12,"verses":[91]}],"verseLabel":"يوسف: 91","question":"ما دلالة اعترافهم: ﴿لقد آثرك الله علينا﴾؟","answer":"أقروا بأن رفعة يوسف اختيار وتفضيل من الله، فظهر بطلان حسدهم القديم وأن الفضل ليس مما يدفعه تدبيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص383، تحت «براعة إيثار لفظ الإيثار»","url":""}]},{"id":"s12-264","number":264,"surah":12,"verses":[91],"references":[{"surah":12,"verses":[91]}],"verseLabel":"يوسف: 91","question":"ما دلالة قولهم: ﴿وإن كنا لخاطئين﴾؟","answer":"استعمال «كان» مع المؤكدات يصور اعترافًا صريحًا بثبوت الخطأ في ماضيهم، لا زلة عارضة يدفعون مسؤوليتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص385، تحت «براعة استعمال فعل الكون»","url":""}]},{"id":"s12-187","number":187,"surah":12,"verses":[92],"references":[{"surah":12,"verses":[92]}],"verseLabel":"يوسف: 92","question":"ما دلالة قول يوسف: ﴿لا تثريب عليكم﴾؟","answer":"التثريب هو اللوم والتقريع على الذنب؛ فنفاه يوسف نفيًا كاملًا إعلانًا للعفو والصفح عند القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص386، تحت «بلاغة استعمال لفظ التثريب»","url":""}]},{"id":"s12-265","number":265,"surah":12,"verses":[92],"references":[{"surah":12,"verses":[92]}],"verseLabel":"يوسف: 92","question":"بم يتعلق لفظ ﴿اليوم﴾ في قوله: ﴿لا تثريب عليكم اليوم يغفر الله لكم﴾؟","answer":"يجوز تعليقه بنفي التثريب، أي يعفو يوم قدرته عليهم وهو أحرى باللوم، ويجوز وصله بدعاء المغفرة؛ فلا ينحصر توجيهه في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص386، تحت «توجيه الوقف على لفظ «اليوم»»","url":""}]},{"id":"s12-188","number":188,"surah":12,"verses":[92],"references":[{"surah":12,"verses":[92]}],"verseLabel":"يوسف: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿يغفر الله لكم وهو أرحم الراحمين﴾؟","answer":"بعد أن عفا عن حقه دعا لهم بالمغفرة من الله، مالك المغفرة وقابل التوبة. ويحتمل التعبير أيضًا البشارة بالمغفرة مع توبتهم وندمهم. وختمه بـ﴿وهو أرحم الراحمين﴾ تعليل للرجاء في عفو الله؛ فرحمته أوسع من رحمة كل راحم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص387–389، تحت «دلالة التعبير بالمضارع «يغفر» دون الماضي؛ فائدة بناء فعل المغفرة للفاعل؛ فائدة العطف بين الجمل؛ نكتة استعمال صيغة التفضيل»","url":""}]},{"id":"s12-189","number":189,"surah":12,"verses":[93],"references":[{"surah":12,"verses":[93]}],"verseLabel":"يوسف: 93","question":"ما دلالة عودة القميص في ختام قصة يوسف؟","answer":"حمل أولًا الدم الكاذب، ثم كان قدّه دليل البراءة، ثم عاد بالبشرى ورد البصر؛ فتحول من أداة حزن إلى علامة فرج واجتماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص395، تحت «رمزية القميص في القصة كلها»","url":""}]},{"id":"s12-266","number":266,"surah":12,"verses":[93],"references":[{"surah":12,"verses":[93]}],"verseLabel":"يوسف: 93","question":"ما دلالة علم يوسف بأن قميصه سيرد بصر أبيه؟","answer":"يعده المصدر من دلائل ما أطلع الله عليه نبيه يوسف؛ فتحقق الأثر بإذن الله شاهدًا على النبوة وصدق البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص399، تحت «دلالات غيب ودلائل إعجاز»","url":""}]},{"id":"s12-190","number":190,"surah":12,"verses":[94],"references":[{"surah":12,"verses":[94]}],"verseLabel":"يوسف: 94","question":"ما سرّ التعبير في قول يعقوب قبل وصول البشير: ﴿إني لأجد ريح يوسف﴾؟","answer":"وجد ريح يوسف قبل وصول البشير على بُعد، وهو إدراك أكرمه الله به؛ ولذلك استبعد الحاضرون قوله وظنوه من تعلقه القديم بيوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص405–408، 410–412، تحت «دلالة جواب «لما»؛ سر التعبير بالريح المضافة إلى يوسف؛ دلالة الوصف بالقديم»","url":""}]},{"id":"s12-191","number":191,"surah":12,"verses":[95],"references":[{"surah":12,"verses":[95]}],"verseLabel":"يوسف: 95","question":"ما أثر المؤكدات في قولهم: ﴿تالله إنك لفي ضلالك القديم﴾؟","answer":"كشف القسم و«إن» واللام رسوخ حكمهم الخاطئ على يعقوب، وشدة جزمهم بأن رجاءه لقاء يوسف بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص411، تحت «غرض اجتماع المؤكدات»","url":""}]},{"id":"s12-267","number":267,"surah":12,"verses":[95],"references":[{"surah":12,"verses":[95]}],"verseLabel":"يوسف: 95","question":"ما الصورة في قولهم: ﴿لفي ضلالك﴾؟","answer":"صور حرف الظرفية الضلال كأنه وعاء يحيط بيعقوب ويتمكن منه، بحسب زعمهم؛ ثم كشفت البشرى خطأ تقديرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص411، تحت «بلاغة الاستعارة باستعمال حرف الظرفية»","url":""}]},{"id":"s12-268","number":268,"surah":12,"verses":[95],"references":[{"surah":12,"verses":[95]}],"verseLabel":"يوسف: 95","question":"ما دلالة وصفهم ضلاله المزعوم بأنه ﴿القديم﴾؟","answer":"أرادوا أنه ما زال منذ زمن طويل متعلقًا بيوسف ويرجو لقاءه، فدل الوصف على استمرار ما أنكروه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص412، تحت «دلالة الوصف بالقديم»","url":""}]},{"id":"s12-192","number":192,"surah":12,"verses":[96],"references":[{"surah":12,"verses":[96]}],"verseLabel":"يوسف: 96","question":"ما غرض الاستفهام في قول يعقوب: ﴿ألم أقل لكم إني أعلم من الله ما لا تعلمون﴾؟","answer":"استفهام تقريري يذكرهم بقوله السابق، وقد صار تحقق البشرى شاهدًا على صدق رجائه وعلمه من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص423، تحت «غرض الاستفهام «ألم أقل لكم»»","url":""}]},{"id":"s12-269","number":269,"surah":12,"verses":[96],"references":[{"surah":12,"verses":[96]}],"verseLabel":"يوسف: 96","question":"لماذا قال: ﴿ما لا تعلمون﴾ ولم يقل: إنكم جاهلون؟","answer":"نفى عنهم العلم الخاص الذي آتاه الله إياه من غير أن يواجههم بالتجهيل، فجمع تثبيت الحقيقة مع لطف الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص425، تحت «نكتة نفي العلم لا التجهيل»","url":""}]},{"id":"s12-193","number":193,"surah":12,"verses":[97],"references":[{"surah":12,"verses":[97]}],"verseLabel":"يوسف: 97","question":"ما أثر قول الأبناء: ﴿يا أبانا﴾ قبل طلب المغفرة؟","answer":"استعطفوا أباهم بنداء الأبوة، وأظهروا الرجوع إلى قربه بعد ما سببوه له من ألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص427، تحت «غرض ذكر جملة النداء»","url":""}]},{"id":"s12-270","number":270,"surah":12,"verses":[97],"references":[{"surah":12,"verses":[97]}],"verseLabel":"يوسف: 97","question":"ما دلالة طلبهم: ﴿استغفر لنا ذنوبنا﴾؟","answer":"أقروا بحاجتهم إلى مغفرة الله وطلبوا من أبيهم أن يدعو لهم، فحل الندم محل الدفاع عن فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص428، تحت «غرض الأمر ودلالته»","url":""}]},{"id":"s12-271","number":271,"surah":12,"verses":[97],"references":[{"surah":12,"verses":[97]}],"verseLabel":"يوسف: 97","question":"لماذا جمعوا الذنوب في قولهم: ﴿استغفر لنا ذنوبنا﴾؟","answer":"يتسع الجمع لما ارتكبوه من ظلم يوسف وإيذاء أبيهم والكذب عليه، فكان اعترافهم شاملًا لا محصورًا في فعل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص430، تحت «نكتة الجمع في قولهم «ذنوبنا»»","url":""}]},{"id":"s12-194","number":194,"surah":12,"verses":[98],"references":[{"surah":12,"verses":[98]}],"verseLabel":"يوسف: 98","question":"ما دلالة ﴿سوف﴾ في قول يعقوب ﴿سوف أستغفر لكم ربي﴾؟","answer":"هي وعد بالاستغفار في الاستقبال، لا رفض لطلبهم. وتذكر الموسوعة توجيهات، منها تحري وقت أنسب للإجابة كالسحر، وزيادة إخلاص الدعاء ودوامه، وتأديبهم حتى يزداد تضرعهم. ولا يلزم من اللفظ تعيين سبب واحد للتأخير؛ وخاتمة الآية ﴿إنه هو الغفور الرحيم﴾ تقوي رجاءهم في المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص432–435، تحت «فائدة إيثار «سوف» على حرف السين؛ دلالة السين والتاء؛ براعة اقتران اسمي «الغفور الرحيم»»","url":""}]},{"id":"s12-195","number":195,"surah":12,"verses":[99],"references":[{"surah":12,"verses":[99]}],"verseLabel":"يوسف: 99","question":"ما دلالة إيواء يوسف أبويه إليه في مشهد الدخول إلى مصر؟","answer":"الإيواء يدل على الضم والرعاية الخاصة والحنان؛ فجاء جوابًا للدخول ليصور مبادرته إلى إكرام أبويه بعد الفراق. ثم دعاهم إلى دخول مصر دخول استقرار وأمن. وتذكر الموسوعة في ترتيب المشهد احتمال استقبالهم خارجها، واحتمال أن يكون المراد الانتقال من دخول الضيوف إلى الإقامة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص442–445، تحت «فائدة جعل «آوى» جواب «لما»؛ بلاغة استعمال الفعل «آوى»؛ دلالة عطف «وقال ادخلوا»؛ معنى الأمر في «ادخلوا مصر»»","url":""}]},{"id":"s12-196","number":196,"surah":12,"verses":[99],"references":[{"surah":12,"verses":[99]}],"verseLabel":"يوسف: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿إن شاء الله آمنين﴾ وهو صاحب سلطة؟","answer":"في تعليق الأمن بمشيئة الله تفويض له، وإقرار بأن تحقق المطلوب لا يستقل به تدبير البشر. فهو أدب يصحب وعد يوسف لهم بالأمن مع ما أعطي من تمكين، ولفظ ﴿آمنين﴾ يشمل طمأنينة النفس وانتفاء الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص445–446، تحت «بلاغة الاحتراس في «إن شاء الله»؛ سر إيثار لفظ «آمنين» على سالمين»","url":""}]},{"id":"s12-197","number":197,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"لماذا قال: ﴿ورفع أبويه على العرش﴾ ولم يقل: أقعدهما؟","answer":"دل الرفع على التشريف وعلو المنزلة مع الارتفاع الحسي إلى سرير الملك، فجمع الإكرام المعنوي والمكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص446، تحت «سر التعبير بالرفع لا بالإقعاد»","url":""}]},{"id":"s12-272","number":272,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما أثر إظهار لفظ ﴿أبويه﴾ بدل الضمير؟","answer":"يعيد استحضار منزلتهما في نفس يوسف ويبرز كمال بره وإكرامه لهما بعد طول الفراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص447، تحت «نكتة إظهار ما حقه الإضمار»","url":""}]},{"id":"s12-198","number":198,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما دلالة التعبير بالخرور في قوله: ﴿وخروا له سجدًا﴾؟","answer":"صور سرعة هويهم إلى السجود وتمام خضوعهم في المشهد الذي تحقق فيه تأويل رؤيا يوسف القديمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص448، تحت «بلاغة الاستعارة بالخرور»","url":""}]},{"id":"s12-273","number":273,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"هل تدل اللام في ﴿وخروا له سجدًا﴾ على عبادة يوسف؟","answer":"تعلق السجود بيوسف من جهة التحية والتعظيم أو لكونه سبب النعمة، مع كون الشكر والعبادة لله؛ فلا تحمل الآية على عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص449، تحت «دلالة اللام في «له»»","url":""}]},{"id":"s12-199","number":199,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما سرّ التعبير في قول يوسف: ﴿هذا تأويل رؤياي من قبل قد جعلها ربي حقًا﴾؟","answer":"التأويل ما آلت إليه الرؤيا وظهر مصداقه في الواقع؛ فالمشهد الحاضر حقق ما رآه من قبل. ونسب يوسف ذلك إلى ربه اعترافًا برعايته وتدبيره، ووصفه بالحق لأنه صار واقعًا ثابتًا بعد أن كان رؤيا رمزية تنتظر تحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص449–452، تحت «سر إيثار «تأويل» على تعبير؛ غرض التأكيد بحرف «قد»؛ نكتة إيثار «ربي» على اسم الجلالة؛ بلاغة استعمال الحق دون الصدق»","url":""}]},{"id":"s12-200","number":200,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما سرّ ذكر نعمة الخروج من السجن دون الخروج من الجب؟","answer":"سترًا لإخوته في مقام الصفح والاجتماع، ولأن السجن أقرب النعم إلى التمكين؛ فلم يجدّد ذكر جريمتهم بعد العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص453–455، تحت «براعة تقييد الإحسان بالإخراج من السجن»","url":""}]},{"id":"s12-201","number":201,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"لماذا قال يوسف: ﴿نزغ الشيطان﴾ ولم يقل: وسوس؟","answer":"النزغ أدل على الإفساد والإغراء الذي أوقع العداوة والفعل، فهو أبلغ من مجرد حديث خفي في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص457، تحت «بلاغة التعبير بالنزغ دون الوسوسة»","url":""}]},{"id":"s12-274","number":274,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما دلالة قوله: ﴿نزغ الشيطان بيني وبين إخوتي﴾؟","answer":"جعل الإفساد واقعًا بين الطرفين ترفقًا بإخوته، فلم يواجههم بإسناد الجناية إليهم وحدهم في مقام الصفح.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص458، تحت «دلالة استعمال البينية»","url":""}]},{"id":"s12-275","number":275,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"لماذا قال يوسف: ﴿وبين إخوتي﴾ ولم يقل: وبينكم؟","answer":"آثر الغيبة ووصف الأخوة ليلطف الخطاب ويطوي أثر المواجهة بالذنب، مؤكدًا بقاء رابطة الأخوة بعد العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص459، تحت «فائدة إيثار الغيبة على الخطاب»","url":""}]},{"id":"s12-202","number":202,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما دلالة وصف الله بـ﴿لطيف لما يشاء﴾ بعد اجتماع الأسرة؟","answer":"اللطيف يعلم خفايا الأمور ويدبر مصالح عباده ويوصل الإحسان إليهم برفق ومن طرق تخفى عليهم. وهذا يلائم قصة يوسف؛ إذ تتابع لطف الله به حتى خرج من الجب والسجن واجتمع بأهله. وتعقيب الوصف بالعلم والحكمة يبين أن هذا التدبير قائم على إحاطة وحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص459–462، تحت «بلاغة المناسبة في صفة «لطيف»؛ سر التعدية باللام؛ سر اقتران صفتي «العليم الحكيم»»","url":""}]},{"id":"s12-203","number":203,"surah":12,"verses":[101],"references":[{"surah":12,"verses":[101]}],"verseLabel":"يوسف: 101","question":"ما دلالة دعاء يوسف ﴿توفني مسلمًا وألحقني بالصالحين﴾ بعد نعمة الملك والعلم؟","answer":"المقصود، وفق التوجيه الذي تعرضه الموسوعة، سؤال الثبات على الإسلام حتى الوفاة، لا استعجال الموت. وبعد ذكر نعم الله عليه سأل تمامها بحسن الخاتمة واللحاق بالصالحين؛ وفي طلب الإلحاق تواضع ورغبة في صحبتهم والاقتداء بمن سبقوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص467–469، 473–475، تحت «بلاغة اختيار فعل «توفني» دون أمتني؛ فائدة التعبير بـ«مسلمًا» دون مؤمنًا؛ بلاغة الكناية في استعمال «ألحقني»»","url":""}]},{"id":"s12-204","number":204,"surah":12,"verses":[101],"references":[{"surah":12,"verses":[101]}],"verseLabel":"يوسف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿فاطر السماوات والأرض أنت وليي في الدنيا والآخرة﴾؟","answer":"وصفه بفاطر السماوات والأرض يستحضر كمال قدرته وخلقه، ثم يقر بولايته ورعايته في الدنيا والآخرة جميعًا. وجملة ﴿أنت وليي﴾ تجمع الاعتراف بهذه الولاية والدعاء بدوامها؛ فالمعنى: كن وليي بالرعاية والنصرة والنجاة، لا أن نعمة الملك تغنيه عن ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص470–473، تحت «نكتة استعمال «فاطر»؛ بديع فن الطباق «السماوات والأرض»؛ فائدة تقديم المسند إليه؛ بلاغة إيراد الخبر وإرادة الإنشاء؛ فن الطباق «الدنيا والآخرة»»","url":""}]},{"id":"s12-205","number":205,"surah":12,"verses":[102],"references":[{"surah":12,"verses":[102]}],"verseLabel":"يوسف: 102","question":"ما دلالة الانتقال إلى خطاب النبي ﷺ بقوله ﴿ذلك من أنباء الغيب نوحيه إليك﴾؟","answer":"بعد اكتمال القصة استخرج دليل الوحي: لم يشهد النبي مؤامرة الإخوة، ومع ذلك جاءه خبرها المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص479–484، تحت «علة الفصل في «ذلك من أنباء»؛ نكتة استعمال الإشارة للبعيد؛ فائدة ذكر النبأ دون الخبر؛ فن المذهب الكلامي»","url":""}]},{"id":"s12-206","number":206,"surah":12,"verses":[102],"references":[{"surah":12,"verses":[102]}],"verseLabel":"يوسف: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم يمكرون﴾ بعد ﴿أجمعوا أمرهم﴾؟","answer":"﴿أجمعوا أمرهم﴾ يدل على عزمهم واتفاقهم على تدبيرهم، وجملة ﴿وهم يمكرون﴾ حال تصف ما صاحب ذلك من احتيال وإخفاء. والمضارع يستحضر صورة مكرهم كأنها مشاهدة، مع التصريح بأن النبي ﷺ لم يكن حاضرًا لديهم؛ فمعرفته بالتفاصيل من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص483–486، تحت «بلاغة استعمال «أجمعوا» دون جمعوا؛ نكتة التعبير عن صنيعهم بالأمر؛ موقع جملة «وهم يمكرون»؛ نكتة التعبير بالمضارع «يمكرون»»","url":""}]},{"id":"s12-207","number":207,"surah":12,"verses":[103],"references":[{"surah":12,"verses":[103]}],"verseLabel":"يوسف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أكثر الناس ولو حرصت بمؤمنين﴾؟","answer":"يواسي النبي بأن وضوح القصة وحرصه لا يجبران القلوب؛ البلاغ عليه والهداية بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص487–489، تحت «دلالة الواو في «وما أكثر الناس»؛ بلاغة التعريض؛ فائدة الاعتراض؛ نكتة حذف متعلق «حرصت»»","url":""}]},{"id":"s12-208","number":208,"surah":12,"verses":[104],"references":[{"surah":12,"verses":[104]}],"verseLabel":"يوسف: 104","question":"ما دلالة قوله: ﴿وما تسألهم عليه من أجر﴾؟","answer":"ينفي أن تكون دعوة النبي طلبًا لأي منفعة مالية، وتؤكد «من» مع تنكير الأجر شمول النفي للقليل والكثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص493، تحت «نكتة استعمال ما في النفي وفائدته»","url":""}]},{"id":"s12-276","number":276,"surah":12,"verses":[104],"references":[{"surah":12,"verses":[104]}],"verseLabel":"يوسف: 104","question":"ما موقع قوله: ﴿إن هو إلا ذكر للعالمين﴾ بعد نفي طلب الأجر؟","answer":"يبين حقيقة القرآن وغايته: تذكير وهداية عامة للعالمين، لا وسيلة لتحصيل عوض ممن يدعوهم النبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص495، تحت «الموقع البياني لقوله «إن هو إلا ذكر للعالمين»»","url":""}]},{"id":"s13-1","number":1,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ آيَاتُ الْكِتَابِ﴾ باسم الإشارة للبعيد؟","answer":"للتعظيم ورفع المنزلة؛ فالآيات الحاضرة في التلاوة بعيدة الرتبة لا بعيدة المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص588، تحت «بلاغة الاستعارة في الإشارة بأداة البعيد»","url":""}]},{"id":"s13-2","number":2,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما دلالة إضافة الآيات إلى الكتاب في ﴿تلك آيات الكتاب﴾؟","answer":"تربط الإضافة الآيات بالكتاب الذي تنتظم فيه، ومن توجيهاتها أن معناها «آيات من كتاب الله». وتذكر الموسوعة أن في كل آية من خصائص البيان والإعجاز ما يدل على كمال الكتاب كله؛ فذكر الآيات يوجه النظر إلى أجزائه، وإضافتها إلى الكتاب تصلها بكله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص589، تحت «معنى الإضافة ونكتتها»","url":""}]},{"id":"s13-3","number":3,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالَّذِي أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ الْحَقُّ﴾؟","answer":"بعد التنويه بآيات الكتاب، صرحت الجملة بأن المنزل على النبي من ربه هو الحق. وتعريف طرفي الإسناد يقوي اختصاصه بالحق في مقام الرد على المكذبين، وذكر مصدره الإلهي يجمع تعظيم الرسالة وتشريف من أنزلت إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص592، تحت «نكتة الإخبار بصيغة القصر»","url":""}]},{"id":"s13-4","number":4,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ رَبِّكَ﴾ لا من الله؟","answer":"إضافة الرب إلى النبي تشعر بالرعاية والتثبيت: الذي تولى تربيته هو الذي أنزل إليه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص594، تحت «نكتة إيثار عنوان الربوبية على لفظ الجلالة»","url":""}]},{"id":"s13-6","number":6,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما دلالة التعبير بالمضارع في قوله تعالى: ﴿لا يؤمنون﴾؟","answer":"يصور المضارع استمرار عنادهم وتجدد امتناعهم من الإيمان بالحق الذي جاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص597، تحت «نكتة التعبير بالمضارع»","url":""}]},{"id":"s13-126","number":126,"surah":13,"verses":[1],"references":[{"surah":13,"verses":[1]}],"verseLabel":"الرعد: 1","question":"ما غرض حذف متعلق ﴿يؤمنون﴾؟","answer":"يجعل الحذف النفي شاملًا لوجوه الإيمان المذكورة في السياق: بالقرآن، وبمن أنزل عليه، وبمصدره الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص597، تحت «غرض حذف متعلق «يؤمنون»»","url":""}]},{"id":"s13-7","number":7,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿رَفَعَ السَّمَاوَاتِ﴾، دون أن يقال: خلق السماوات؟","answer":"لفظ الرفع يستحضر هيئة السماوات العالية وما فيها من دلالة على القدرة، فلا يقتصر على الإخبار بأصل خلقها. ثم يأتي ﴿بغير عمد ترونها﴾ ليزيد المشهد عجبًا؛ وتعرض الموسوعة توجيه نفي العمد أصلًا، وتوجيه نفي العمد المرئية، والمقصود في الحالين إبراز كمال القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص603–604، تحت «دلالة التعبير بمفردة «رفع» دون خلق؛ دلالة النفي وتوجيهه بين الحقيقة والمجاز»","url":""}]},{"id":"s13-8","number":8,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما دلالة جمع ﴿السماوات﴾ مع ذكر الأرض مفردة؟","answer":"تربط الموسوعة جمع السماوات بتعددها وتنوع الآيات في جهة العلو. وعند مناقشة جمع السماوات وإفراد الأرض تذكر توجيهات بلاغية متعددة، منها زيادة الاعتناء بالسماوات لشرفها وعظم ما فيها من الآيات. فهذا وجه من وجوه التعبير، ولا ينحصر تعليله في تصور الأرض قرارًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص471، 603–604، تحت «نكتة جمع «السماوات»، وإفراد «الأرض»؛ نكتة جمع السماوات دون إفرادها»","url":""}]},{"id":"s13-9","number":9,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"لماذا عُبّر بـ﴿الأجل﴾ دون الوقت في قوله تعالى: ﴿لأجل مسمى﴾؟","answer":"الأجل مدة مقدرة لها نهاية، بخلاف الوقت الذي قد يذكر لمطلق الزمان؛ فدل على أن جريان الشمس والقمر منتهٍ إلى حد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص609، تحت «نكتة ذكر الأجل دون الوقت»","url":""}]},{"id":"s13-127","number":127,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما فائدة وصف الأجل بأنه ﴿مسمى﴾؟","answer":"يؤكد أن نهايته معلومة مقدرة عند الله لا تتقدم ولا تتأخر ولا تمضي بلا غاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص609، تحت «فائدة ذكر الصفة»","url":""}]},{"id":"s13-10","number":10,"surah":13,"verses":[2],"references":[{"surah":13,"verses":[2]}],"verseLabel":"الرعد: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لِقَاءِ رَبِّكُمْ تُوقِنُونَ﴾ لا تؤمنون؟","answer":"لأن المطلوب هنا علم ثابت يطرد الشك في البعث، فالإيقان أخص من مطلق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص613، تحت «سر التعبير بالإيقان دون الإيمان»","url":""}]},{"id":"s13-11","number":11,"surah":13,"verses":[3],"references":[{"surah":13,"verses":[3]}],"verseLabel":"الرعد: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿مَدَّ الْأَرْضَ﴾؟","answer":"المد بسط الأرض وتهيئتها للانتفاع؛ فالتعبير يوجه النظر إلى امتدادها الذي يسير عليه الإنسان ويستقر فيه وينتفع به. وهو في السياق مظهر للنعمة والقدرة، بعد ذكر آيات السماوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص616، 618–619، تحت «دلالة استعمال مفردة «مد»»","url":""}]},{"id":"s13-12","number":12,"surah":13,"verses":[3],"references":[{"surah":13,"verses":[3]}],"verseLabel":"الرعد: 3","question":"ما دلالة تنكير ﴿رواسي وأنهارًا﴾ في مشهد الأرض؟","answer":"يفيد التنكير هنا التكثير والتعظيم: جبالًا عظيمة وأنهارًا كثيرة تجري بالماء الذي تنتفع به الزروع والأشجار. فالمشهد يعدد مظاهر القدرة والإنعام في الأرض، ويهيئ القارئ للتفكر في آثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص622، تحت «غرض التنكير»","url":""}]},{"id":"s13-13","number":13,"surah":13,"verses":[3],"references":[{"surah":13,"verses":[3]}],"verseLabel":"الرعد: 3","question":"ما دلالة ختام الآية بـ﴿لقوم يتفكرون﴾؟","answer":"المشاهد المذكورة من مد الأرض والرواسي والثمار وتعاقب الليل تستدعي إعمال النظر في دلالتها على الخالق. وصيغة ﴿يتفكرون﴾ تدعو إلى تفكر متجدد، ينتقل بصاحبه من مشاهدة المصنوعات إلى إدراك حكمة صانعها وقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص632، تحت «نكتة ذكر التفكر دون التدبر أو التعقل»","url":""}]},{"id":"s13-14","number":14,"surah":13,"verses":[3,4],"references":[{"surah":13,"verses":[3,4]}],"verseLabel":"الرعد: 3-4","question":"ما سرّ التعبير في قوله تعالى في الآية 3: ﴿يتفكرون﴾، وفي الآية 4: ﴿يعقلون﴾؟","answer":"تذكر الموسوعة أن التفكر في المشاهد الكونية يهيئ لإدراك دلالتها، ثم يأتي التعقل ثمرة لذلك النظر. كما أن اختلاف الثمر مع تجاور الأرض واتحاد الماء يجعل الحجة ظاهرة للعقل؛ فناسب تقديم التفكر ثم ختام المشهد التالي بالتعقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص644، تحت «توجيه تشابه فواصل الآيات بذكر التعقل بعد التفكر»","url":""}]},{"id":"s13-15","number":15,"surah":13,"verses":[4],"references":[{"surah":13,"verses":[4]}],"verseLabel":"الرعد: 4","question":"ما دلالة جمع ﴿لآيات﴾ بعد ذكر اختلاف الأرض والثمار مع اتحاد الماء؟","answer":"لأن المشهد يضم دلائل متعددة: تجاور القطع مع اختلاف خصائصها، وتنوع الجنات والنخيل، وتفاوت الثمر مع الماء الواحد. فكل واحد من هذه الوجوه آية، واجتماعها يقوي الدلالة على القدرة والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص634، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s13-16","number":16,"surah":13,"verses":[4],"references":[{"surah":13,"verses":[4]}],"verseLabel":"الرعد: 4","question":"ما سر قوله: ﴿صِنْوَانٌ وَغَيْرُ صِنْوَانٍ﴾؟","answer":"الصنوان نخلات يجمعها أصل واحد، وغير الصنوان ما تفرقت أصوله. وذكر الحالين يزيد تنوع المشهد، ثم يجيء اتحاد الماء مع تفاوت الثمر ليبين أن تشابه بعض أسباب النمو لا يمنع اختلاف الناتج، فيدعو ذلك إلى التفكر في قدرة المدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص639، تحت «فائدة ذكر نوعي النخيل»","url":""}]},{"id":"s13-17","number":17,"surah":13,"verses":[4],"references":[{"surah":13,"verses":[4]}],"verseLabel":"الرعد: 4","question":"ما دلالة إسناد ﴿ونفضل بعضها على بعض في الأكل﴾ إلى ضمير العظمة؟","answer":"في قراءة النون يلتفت السياق من الغيبة إلى التكلم، وينسب تفاوت الثمار في الطعم والجودة إلى الله صراحة. وقد ذُكر تجاور الأرض واتحاد الماء، فكان التصريح بفاعل التفضيل موضع العبرة؛ ليتوجه العقل من الاختلاف المشاهد إلى تقدير الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص641–643، تحت «توجيه القراءات القرآنية في «ونفضل»؛ نكتة إسناد التفضيل إلى الله دون سائر المتقدم»","url":""}]},{"id":"s13-18","number":18,"surah":13,"verses":[5],"references":[{"surah":13,"verses":[5]}],"verseLabel":"الرعد: 5","question":"ما وجه قولهم: ﴿أَئِذَا كُنَّا تُرَابًا أَئِنَّا لَفِي خَلْقٍ جَدِيدٍ﴾؟","answer":"في القراءة بالاستفهام في الموضعين يتكرر الإنكار للمبالغة في استبعاد البعث بعد صيرورتهم ترابًا؛ فموضع استبعادهم هو اجتماع هذين الحالين. وتذكر الموسوعة اختلاف القراءات بين الاستفهام والخبر في الموضعين، مع اتفاقها على تصوير إنكارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص650، تحت «غرض الاستفهام ومعناه»","url":""}]},{"id":"s13-19","number":19,"surah":13,"verses":[5],"references":[{"surah":13,"verses":[5]}],"verseLabel":"الرعد: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿خَلْقٍ جَدِيدٍ﴾، دون أن يقال: أنُبعث؟","answer":"يحكي اللفظ استبعادهم أن يعودوا أحياء بعد تحولهم إلى تراب؛ فالمراد بالخلق الجديد إعادة الخلق، لا إيجاد أشخاص آخرين. وقد سبق عرض دلائل الخلق الأول، فصار إنكارهم الإعادة مع إقرارهم بتلك القدرة موضع التعجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص652، تحت «دلالة التعبير بالخلق الجديد»","url":""}]},{"id":"s13-20","number":20,"surah":13,"verses":[5],"references":[{"surah":13,"verses":[5]}],"verseLabel":"الرعد: 5","question":"ما سرّ التعبير بالكفر في ﴿أولئك الذين كفروا بربهم﴾؟","answer":"السياق في جحود القدرة على البعث بعد ظهور دلائل الخلق الأول؛ فلفظ الكفر يلائم ستر تلك الدلائل وإنكار ما تدل عليه. فهو يصف موقفهم من حجة ظاهرة، لا مجرد ذكر اتخاذ الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص652–653، تحت «سر التعبير بالكفر دون الشرك»","url":""}]},{"id":"s13-21","number":21,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَسْتَعْجِلُونَكَ﴾ بخطاب النبي؟","answer":"يوجه الضمير طلبهم إلى النبي مع أن إنزال العذاب بيد الله؛ فقد كانوا يستعجلونه بما ينذرهم به، استهزاءً بوعيده أو طعنًا في صدق رسالته. فيصور الخطاب تعنتهم في مواجهته، بينما وظيفته تبليغ الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص662–664، تحت «نكتة ضمير المخاطب في «ويستعجلونك»»","url":""}]},{"id":"s13-22","number":22,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿ذُو مَغْفِرَةٍ﴾، دون أن يقال: ذو رحمة؟","answer":"المغفرة تلائم ذكر الظلم واستعجال العقوبة؛ ومن توجيهاتها هنا إمهالهم وتأخير العذاب ليرجعوا، كما تحتمل المغفرة لمن تاب. و﴿ذو مغفرة﴾ تفيد رسوخ هذه الصفة وسعتها؛ فالتعبير يفتح باب الرجاء مع التحذير من العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص670–673، تحت «سر إضافة «لذو» إلى «مغفرة»؛ نكتة استعمال صفة المغفرة في الآية»","url":""}]},{"id":"s13-23","number":23,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَى ظُلْمِهِمْ﴾ لا مع ظلمهم؟","answer":"تذكر الموسوعة أن ﴿على﴾ تؤدي معنى المصاحبة هنا، مع إبقاء إيحاء الاستعلاء: فرحمة الله ومغفرته فوق ما يستحقه الظلم من العقوبة. وفي تفسير المغفرة بالإمهال، يكون المعنى أنه يؤخر العقوبة مع تلبسهم بالظلم لعلهم يرجعون؛ فلا يعني ذلك إسقاط الوعيد عن المصرين مطلقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص672–673، تحت «معنى حرف الاستعلاء ودلالته في «على ظلمهم»»","url":""}]},{"id":"s13-24","number":24,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"ما فائدة الاحتراس بقوله تعالى: ﴿شديد العقاب﴾ بعد ذكر المغفرة؟","answer":"يمنع أن يُفهم الإمهال والمغفرة إهمالًا دائمًا أو عجزًا عن المؤاخذة، فيجمع المقام بين الرجاء والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص675، تحت «فن الاحتراس في الآية الكريمة»","url":""}]},{"id":"s13-128","number":128,"surah":13,"verses":[6],"references":[{"surah":13,"verses":[6]}],"verseLabel":"الرعد: 6","question":"لماذا استعمل لفظ ﴿العقاب﴾ في قوله تعالى: ﴿شديد العقاب﴾؟","answer":"يلائم العقاب الجزاء الذي يعقب الذنب ويأتي بعده، فينذر المصر على معصيته بعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص677، تحت «سر استعمال مفردة «العقاب»»","url":""}]},{"id":"s13-25","number":25,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"ما سرّ اختيارهم لفظ ﴿أُنْزِلَ﴾ دون «جاءت»؟","answer":"اختيار الإنزال يصور طلبهم آية من عند الله تكون حسية وعلى وفق اقتراحهم. وقد عدلوا عن الاعتداد بما أنزل فعلًا من الآيات، وفي هذا اللفظ تعنت ظاهر؛ إذ لا يطلبون مطلق الدليل بعد قيامه، بل آية مخصوصة يختارونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص683–684، تحت «نكتة استعمال الإنزال دون المجيء»","url":""}]},{"id":"s13-26","number":26,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"ما سرّ تقديم ﴿عَلَيْهِ﴾ في قولهم؟","answer":"قدم ﴿عليه﴾ للاهتمام بمن تنزل عليه الآية؛ فاعتراضهم متعلق باختصاص محمد ﷺ بالرسالة. وتربط الموسوعة هذا التقديم بما في نفوسهم من حسد ومكابرة، إذ يريدون آيةً تقنعهم بأن هذا الاختصاص حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص684، تحت «سر التقديم في قوله «لولا أنزل عليه آية»»","url":""}]},{"id":"s13-27","number":27,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"ما دلالة القصر في ﴿إنما أنت منذر﴾؟","answer":"القصر إضافي يرد اقتراحاتهم: وظيفته إبلاغ الإنذار، أما إنشاء الآيات فإلى الله. فلا يعني أنه لا يبشر ولا يهدي بالدلالة؛ وإنما يحدد ما يلائم مقام الرد، ثم يجيء ﴿ولكل قوم هاد﴾ ليصل الإنذار بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص686–688، تحت «بلاغة القصر في «إنما أنت منذر»؛ نكتة قصر الموصوف على صفة الإنذار؛ فن الاحتباك»","url":""}]},{"id":"s13-28","number":28,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"لماذا عبّر بقوله: ﴿ولكل قوم﴾ لا «لكل أمة»؟","answer":"يلائم لفظ القوم سياق مخاطبة جماعة النبي ﷺ ومفارقتهم له في الاستجابة إلى دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص687، تحت «دلالة إيثار التعبير بلفظ قوم»","url":""}]},{"id":"s13-129","number":129,"surah":13,"verses":[7],"references":[{"surah":13,"verses":[7]}],"verseLabel":"الرعد: 7","question":"لماذا عبّر بـ﴿هاد﴾ بدل منذر؟","answer":"الهداية أوسع من مجرد الإنذار؛ فهي تشمل الدعوة إلى الحق والإنذار والبشارة والإرشاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص688، تحت «سر إيثار لفظ هاد»","url":""}]},{"id":"s13-29","number":29,"surah":13,"verses":[8],"references":[{"surah":13,"verses":[8]}],"verseLabel":"الرعد: 8","question":"ما دلالة الابتداء باسم الجلالة في ﴿الله يعلم﴾؟","answer":"التصريح باسم الله يثبت أن هذا العلم المحيط من شأنه وحده، وتقديم الاسم على الفعل يقوي الحكم؛ إذ يعود عليه ضمير الفعل أيضًا. ثم يأتي تفصيل دقائق الحمل ليجسد سعة هذا العلم فيما يخفى على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص692–693، تحت «براعة الابتداء والتقديم في «الله يعلم»»","url":""}]},{"id":"s13-30","number":30,"surah":13,"verses":[8],"references":[{"surah":13,"verses":[8]}],"verseLabel":"الرعد: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَحْمِلُ كُلُّ أُنْثَى﴾ بالمضارع؟","answer":"المضارع يستحضر الحمل في مراحله المتجددة، ويدل على تعلق علم الله بما تحمل كل أنثى حالًا واستقبالًا. فالعلم محيط بتفاصيل الحمل وأطواره، ولا يختص بحمل مضى أو بجنس دون جنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص693–696، تحت «دلالة التعبير بالمضارع في «تحمل»؛ غرض استعمال أداة العموم»","url":""}]},{"id":"s13-31","number":31,"surah":13,"verses":[8],"references":[{"surah":13,"verses":[8]}],"verseLabel":"الرعد: 8","question":"ما دلالة ترتيب ﴿ما تحمل كل أنثى وما تغيض الأرحام وما تزداد﴾؟","answer":"بدأ بذكر الحمل، ثم ذكر النقص والزيادة المتقابلين، ليشمل البيان أحواله المختلفة. وتوضح الموسوعة أن الغيض عدم أو نقص، والزيادة إثبات لما زاد، فناسب تقديم النقص ثم الزيادة في هذا النسق؛ وليس المعنى أن كل حمل لا بد أن يمر بنقص ثم زيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص697–700، تحت «بلاغة مقابلة «تغيض» بـ«تزداد»؛ بلاغة ترتيب المعطوفات في الآية الكريمة»","url":""}]},{"id":"s13-32","number":32,"surah":13,"verses":[8],"references":[{"surah":13,"verses":[8]}],"verseLabel":"الرعد: 8","question":"ما سرّ تقديم ﴿عِنْدَهُ﴾ في قوله تعالى: ﴿وَكُلُّ شَيْءٍ عِنْدَهُ بِمِقْدَارٍ﴾؟","answer":"يفيد التخصيص والتوكيد: فالله هو العالم بمقادير الأشياء والمدبّر لها بحكمة، فلا يخرج شيء عن علمه وتقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص701–702، تحت «نكتة تقديم «عنده» على المسند «بمقدار»»","url":""}]},{"id":"s13-33","number":33,"surah":13,"verses":[9],"references":[{"surah":13,"verses":[9]}],"verseLabel":"الرعد: 9","question":"ما دلالة حذف الياء من ﴿الْمُتَعَالِ﴾ في توجيه الموسوعة البلاغي؟","answer":"تربط الموسوعة الحذف بالدلالة على كمال العلو، حتى يجتمع اللفظ والمعنى في تنزيه الله عن كل نقص؛ وتذكر معه مراعاة الفواصل الساكنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص705، تحت «توجيه حذف الياء من قوله: «المتعال»»","url":""}]},{"id":"s13-34","number":34,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير بقوله تعالى: ﴿أَسَرَّ الْقَوْلَ﴾ لا أخفاه؟","answer":"لأن الإسرار أدلّ على الكتمان، فهو أنسب للقول؛ أما الخفاء فيناسب أيضًا استتار الأعيان عن البصر. فاختيار الإسرار يبرز إحاطة علم الله بالقول مهما بالغ صاحبه في كتمانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص710–711، تحت «نكتة التعبير بلفظ «أسرّ»»","url":""}]},{"id":"s13-35","number":35,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ الاكتفاء بذكر القول في ﴿مَنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ﴾؟","answer":"لأن القول داخل في العمل، وهو عمل اللسان وقد يكون حديثًا في النفس من عمل القلب؛ فذكره يدل على العلم بالفعل أيضًا. ثم ذُكرت أحوال الحركة والاستخفاء في ﴿مُسْتَخْفٍ بِاللَّيْلِ وَسَارِبٌ بِالنَّهَارِ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص713–714، تحت «بلاغة الاكتفاء بذكر القول دون الفعل»","url":""}]},{"id":"s13-36","number":36,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير بقوله تعالى: ﴿جَهَرَ بِهِ﴾؟","answer":"الجهر إعلان وإظهار يكون إدراكه بالسمع، ولذلك ناسب القول وقابل الإسرار به؛ ولا يلزم أن يسبقه خفاء بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص714، تحت «نكتة التعبير بلفظ «جهر»»","url":""}]},{"id":"s13-37","number":37,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿مُسْتَخْفٍ﴾ و﴿سَارِبٌ﴾؟","answer":"جمع بين طالب الخفاء في الليل والظاهر المنطلق في النهار؛ فالعلم محيط بأقصى حالتي الاستتار والظهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص717، تحت «سرّ التعبير بـ«سارب» و«مستخف»»","url":""}]},{"id":"s13-38","number":38,"surah":13,"verses":[10],"references":[{"surah":13,"verses":[10]}],"verseLabel":"الرعد: 10","question":"ما سرّ تكرار ﴿مَنْ﴾ في ﴿مَنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ﴾، وعدم تكرارها قبل ﴿سَارِبٌ بِالنَّهَارِ﴾؟","answer":"عدم تكرارها قبل «سارب» يوجز العبارة ويفسح لاحتمال حالتي شخص واحد، أو شخصين: أحدهما مستخفّ والآخر ظاهر، والجميع سواء في علم الله. أما تكرارها مع الإسرار والجهر فيلائم المقابلة بين مسرّ القول والجاهر به؛ فالقول الواحد لا يكون سرًّا وجهرًا في الوقت نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص718–719، تحت «سرّ الاكتفاء بلا إضافة (من هو)»","url":""}]},{"id":"s13-39","number":39,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سرّ إفراد الضمير في ﴿لَهُ مُعَقِّبَاتٌ﴾ مع شمول الكلام للناس؟","answer":"يرجع الضمير إلى كل فرد ممّن تقدّم ذكرهم في ﴿مَنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ﴾ وما بعدها؛ فالإفراد يلحظ الإنسان بعينه، مع دخول الجميع في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص726–727، تحت «نكتة إفراد الضمائر في الآية الكريمة»","url":""}]},{"id":"s13-40","number":40,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"هل في قوله تعالى: ﴿لَهُ مُعَقِّبَاتٌ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ يَحْفَظُونَهُ مِنْ أَمْرِ اللَّهِ﴾ تقديم وتأخير؟","answer":"ذهب بعض المفسرين إلى تقدير تقديم وتأخير، وجعلوا المعنى: له معقبات من أمر الله يحفظونه. لكن المصدر رجّح إبقاء النظم على ترتيبه؛ لأن حمل القرآن على التقديم والتأخير خلاف الأصل مع إمكان فهمه من غير عكس للترتيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص730–731، تحت «بلاغة ترتيب الكلام في الآية الكريمة»","url":""}]},{"id":"s13-41","number":41,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ أَمْرِ اللَّهِ﴾؟","answer":"من توجيهات العبارة أن حفظ الملائكة سببه أمر الله، فهم يحفظون الإنسان بأمره وإذنه، لا استقلالًا عنه. وتعرض الموسوعة توجيهات أخرى لـ«من»؛ لذا لا يُجعل هذا المعنى الوجه الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص729–731، تحت «معنى «من» في قوله: «من أمر الله»»","url":""}]},{"id":"s13-42","number":42,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ﴾ بالمضارع المنفي؟","answer":"يؤكد نفيَ سلب النعمة في الأحوال المتجددة، حتى يغيّر الناس ما بأنفسهم من الخير إلى ضده؛ فليس النفي مقصورًا على حالة واحدة منقضية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص733، تحت «نكتة المضارع المنفي في «لا يغيّر»»","url":""}]},{"id":"s13-43","number":43,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا بِقَوْمٍ﴾، دون أن يقال: حال قوم؟","answer":"تُبهم «ما» الأحوال وتعمّمها، ثم يعيّن السياق المراد: ما بالقوم من نعمة وخير. ويستحضر لفظ «قوم» اجتماعهم؛ فالتغيير وما يعقبه قد يعمّ الجماعة بسبب ما يقع منها أو من بعضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص733–734، تحت «فائدة مجيء الموصول بأداة «ما»»","url":""}]},{"id":"s13-44","number":44,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ دُونِهِ مِنْ وَالٍ﴾؟","answer":"«من دونه» تنفي أن يكون لهم وليّ سواه يدفع عنهم ما أراده؛ و«والٍ» من يتولى التدبير والنفع. وجاءت «من» قبل «والٍ» لتؤكد استغراق النفي: فلا ناصر يحميهم من قضائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص739–740، تحت «دلالة التعبير بقوله: «من دونه»»","url":""}]},{"id":"s13-45","number":45,"surah":13,"verses":[12],"references":[{"surah":13,"verses":[12]}],"verseLabel":"الرعد: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا﴾ فجمع الضدين؟","answer":"البرق نفسه باعث للخوف من صواعقه وللطمع في الغيث الذي يبشّر به؛ فجمع الوصفين يذكّر بأن من تُخشى عقوبته هو الذي تُرجى رحمته ورزقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص748، تحت «بلاغة الجمع في «خوفًا وطمعًا»»","url":""}]},{"id":"s13-46","number":46,"surah":13,"verses":[12],"references":[{"surah":13,"verses":[12]}],"verseLabel":"الرعد: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿يُنْشِئُ السَّحَابَ﴾ لا يخلق؟","answer":"الإنشاء يصور تكوينه المتجدد شيئًا بعد شيء من بدايات دقيقة حتى يثقل بالماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص749–750، تحت «نكتة التعبير بلفظ «ينشئ»»","url":""}]},{"id":"s13-47","number":47,"surah":13,"verses":[12],"references":[{"surah":13,"verses":[12]}],"verseLabel":"الرعد: 12","question":"ما دلالة وصف السحاب بـ﴿الثِّقَالِ﴾؟","answer":"ليحس القارئ بما حمله من ماء كثير، فتقوى صورة القدرة والبشارة بالمطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص750، تحت «فائدة وصف السحاب بـ«الثقال»»","url":""}]},{"id":"s13-48","number":48,"surah":13,"verses":[13],"references":[{"surah":13,"verses":[13]}],"verseLabel":"الرعد: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ﴾؟","answer":"التسبيح تنزيه لله عن النقص، والحمد ثناء عليه؛ ويقترنان هنا لأن الرعد مع دلالته على القدرة يبشّر بقرب الغيث، وهو نعمة تستوجب الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص753–754، تحت «سرّ تعلّق صفة الحمد بتسبيح الرعد»","url":""}]},{"id":"s13-49","number":49,"surah":13,"verses":[13],"references":[{"surah":13,"verses":[13]}],"verseLabel":"الرعد: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ يَشَاءُ﴾ في إرسال الصواعق؟","answer":"يبين أن الإصابة بالصواعق تابعة لمشيئة الله، فلا يجبره أحد على إنزال العذاب ولا يعجز عن إنزاله؛ وتأخيره عن المكذبين لا يدل على العجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص755–756، تحت «فائدة التعبير بقوله: «من يشاء»»","url":""}]},{"id":"s13-50","number":50,"surah":13,"verses":[13],"references":[{"surah":13,"verses":[13]}],"verseLabel":"الرعد: 13","question":"ما دلالة التعبير بـ﴿يُجَادِلُونَ فِي اللَّهِ﴾ مع أن جدالهم في دلائل توحيده وقدرته؟","answer":"في العبارة حذف يقدَّر بحسب السياق، كجدالهم في توحيد الله أو قدرته على البعث. وإضافة الجدال إلى اسم الله مباشرة تهوّل موقفهم وتبيّن شناعة جدالهم بعد ظهور الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص759–760، تحت «براعة المجاز بالحذف في ذكر لفظ الجلالة»","url":""}]},{"id":"s13-51","number":51,"surah":13,"verses":[13],"references":[{"surah":13,"verses":[13]}],"verseLabel":"الرعد: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿شَدِيدُ الْمِحَالِ﴾؟","answer":"تذكر الموسوعة في «المحال» معنى قوة الأخذ والمماحلة والمكر بالمعاندين من حيث لا يشعرون؛ فوصفه بالشدة يناسب تهديد من يجادل في الله مع ظهور قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص761–762، تحت «بلاغة التعبير بقوله: «المحال»»","url":""}]},{"id":"s13-52","number":52,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿لَهُ دَعْوَةُ الْحَقِّ﴾؟","answer":"تقديم «له» يفيد اختصاص الله بدعوة الحق في مقابل دعاء الأصنام؛ فهو الذي يسمع ويجيب، أما المعبودات الباطلة فلا تملك لداعيها نفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص769–770، تحت «سرّ تقديم الجارّ والمجرور في السياق»","url":""}]},{"id":"s13-53","number":53,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَجِيبُونَ﴾ لا يجيبون؟","answer":"توجّه الموسوعة الاستجابة بأنها إجابة توافق طلب السائل وتحقّق مراده؛ فنفيها يفضح عجز الأصنام عن إسعاف داعيها. وتذكر أيضًا أن السين والتاء قد تفيدان تقوية الفعل، فلا يُحصر معناهما هنا في مجرد طلب الإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص773–774، تحت «سرّ إيثار الفعل «يستجيبون» دون «يجيبون»»","url":""}]},{"id":"s13-54","number":54,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما دلالة تشبيه داعي الأصنام بباسط كفّيه إلى الماء ليبلغ فاه؟","answer":"يصوّر تعلّقًا شديدًا بمطلوب لا يُنال بهذه الوسيلة: فالعطشان يدعو الماء أن يأتي فاه، والماء لا يستجيب له. كذلك من يدعو ما لا يسمع ولا ينفع؛ فالصورة تكشف عجز المعبود وخيبة داعيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص776–777، تحت «بلاغة (التشبيه التمثيلي) أو (المركّب العقلي)»","url":""}]},{"id":"s13-55","number":55,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿كفَّيه﴾ لا يديه؟","answer":"لأن الكفين موضع غرف الماء وتلقيه، فهما أدق في الصورة من عموم اليدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص778، تحت «إيثار الكفّين على اليدين في السياق المبين»","url":""}]},{"id":"s13-56","number":56,"surah":13,"verses":[14],"references":[{"surah":13,"verses":[14]}],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ﴾؟","answer":"جعل الدعاء نفسه غارقًا في الضلال، مبالغة في تصوير ضياعه وعدم بلوغه غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص782، تحت «معنى الحرف «في» من السياق المحكم»","url":""}]},{"id":"s13-57","number":57,"surah":13,"verses":[15],"references":[{"surah":13,"verses":[15]}],"verseLabel":"الرعد: 15","question":"كيف يسجد لله من في الكون ﴿طَوْعًا وَكَرْهًا﴾؟","answer":"المؤمن يسجد اختيارًا، والجميع خاضعون قهرًا لسننه وقدره؛ فلا يخرج مخلوق عن سلطان ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص788–789، 791، تحت «دلالة الطوع والكره على العموم»","url":""}]},{"id":"s13-58","number":58,"surah":13,"verses":[15],"references":[{"surah":13,"verses":[15]}],"verseLabel":"الرعد: 15","question":"ما دلالة ذكر سجود الظلال بعد سجود أصحابها؟","answer":"الظلال تابعة لأصحابها، ومع ذلك لا يملكون منع امتدادها وانقباضها وفق ما سخّرها الله له؛ فذكرها يجسّد شمول الخضوع، حتى ظلّ المعاند منقاد لربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص792–793، تحت «سرّ التعبير بلفظ (الظلال) في الآية الكريمة»","url":""}]},{"id":"s13-59","number":59,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْلِيَاءَ﴾ لا أربابًا؟","answer":"الوليّ والناصر أعمّ من الرب؛ فالتوبيخ على طلب النصرة من غير الله، مع عجز المعبودات المذكورة، يستلزم التوبيخ على اتخاذها أربابًا، وهو الوصف الأخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص19، تحت «إيثار التعبير بالأولياء دون الأرباب»","url":""}]},{"id":"s13-60","number":60,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَمْلِكُونَ لِأَنْفُسِهِمْ نَفْعًا وَلَا ضَرًّا﴾؟","answer":"بدأ بعجزهم عن أنفسهم؛ فمن عجز عن نفع نفسه ودفع ضرها كان أعجز عن غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص20، تحت «دلالة نفي الملكية للنفس»","url":""}]},{"id":"s13-61","number":61,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما دلالة تكرار ﴿لَا﴾ في ﴿لَا يَمْلِكُونَ لِأَنْفُسِهِمْ نَفْعًا وَلَا ضَرًّا﴾؟","answer":"للنص على استقلال النفي بكل واحد من النفع والضر، فلا يتوهم ثبوت أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص21، تحت «نكتة تكرار (لا) النافية»","url":""}]},{"id":"s13-62","number":62,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما بلاغة تصوير الكفر بالظلمات والإيمان بالنور؟","answer":"يصوّر الكافر كمن يتخبط في الظلام، والمؤمن كمن يبصر طريقه ويهتدي بالنور.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص22، تحت «بلاغة الاستعارتين التصريحيتين في سياق الآية»","url":""}]},{"id":"s13-130","number":130,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"لماذا جُمعت ﴿الظلمات﴾ وأُفرد ﴿النور﴾؟","answer":"جُمعت الظلمات لتعدد طرق الشك والباطل، وأُفرد النور لاتحاد طريق الإيمان والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص24، تحت «سرّ جمع الظلمات وإفراد النور»","url":""}]},{"id":"s13-63","number":63,"surah":13,"verses":[16],"references":[{"surah":13,"verses":[16]}],"verseLabel":"الرعد: 16","question":"ما سرّ ختام الآية بـ﴿الْوَاحِدُ الْقَهَّارُ﴾؟","answer":"«الواحد» يهدم تعدد الشركاء، و«القهار» يهدم توهم استقلالهم بالقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص30، تحت «إيثار اسمي «الواحد» و«القهّار» دون غيرهما»","url":""}]},{"id":"s13-64","number":64,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْزَلَ مِنَ السَّمَاءِ مَاءً﴾ لا غيثًا؟","answer":"«الماء» أعمّ، فيشمل ما يكون رحمة وما يكون عذابًا؛ أما «الغيث» فغالب وروده في مقام الإنعام والرحمة. والسياق هنا يضرب مثلًا للحق والباطل، فلا يقتصر على معنى الإغاثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص38، تحت «إيثار لفظ الماء على الغيث»","url":""}]},{"id":"s13-65","number":65,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ إسناد السيلان إلى الأودية في ﴿فَسَالَتْ أَوْدِيَةٌ﴾؟","answer":"يصوّر الماء المتدفق بين جانبي الوادي حتى يخيل للناظر أن الوادي نفسه يسيل معه؛ فإسناد السيلان إلى محله يبرز قوة المشهد وكثرة الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص41–42، تحت «سرّ إسناد السيلان إلى الوادي دون الماء»","url":""}]},{"id":"s13-66","number":66,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿بِقَدَرِهَا﴾؟","answer":"تحمل الأودية من الماء بحسب سعتها؛ وفي هذا احتراس من توهّم سيل مدمّر يجاوز طاقتها. وعلى تفسير المثل بالقرآن والقلوب، تنتفع القلوب بالوحي بحسب ما تقبله وتعيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص39–40، 44–45، تحت «فائدة الحال في قوله تعالى «بقدرها»»","url":""}]},{"id":"s13-67","number":67,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاحْتَمَلَ السَّيْلُ زَبَدًا رَابِيًا﴾؟","answer":"جعل الزبد محمولًا طافيًا ليجسد ظهور الباطل مؤقتًا مع خفته وانفصاله عن جوهر النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص42–44، تحت «دلالة وصف الزبد بالرابي في الآية الكريمة»","url":""}]},{"id":"s13-68","number":68,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ عدم التصريح بإخراج المعادن من الأرض في المثل، مع التصريح بإنزال الماء من السماء؟","answer":"تذكر الموسوعة أن إخراج المعادن داخل ضمن المثل، فلا يحتاج إلى تصريح مستقل. وانتقل البيان إلى إيقاد النار عليها وظهور زبدها؛ وهو مشهد يعرفه أهل الحضر، فيكمل مثل السيل الذي يعرفه أهل البدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص47–48، تحت «سرّ العدول عن ذكر إخراج ما يوقدون عليه من الأرض»","url":""}]},{"id":"s13-69","number":69,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ إفراد ﴿الزَّبَدُ﴾ مع وروده في مثَلَي الماء والمعدن؟","answer":"لأن زبد الماء وزبد المعدن متحدان في الصفة المقصودة: الطفو والذهاب بلا نفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص53–54، تحت «سرّ إفراد الزبد في قوله «فأمّا الزبد»»","url":""}]},{"id":"s13-70","number":70,"surah":13,"verses":[17],"references":[{"surah":13,"verses":[17]}],"verseLabel":"الرعد: 17","question":"ما سرّ تكرار ﴿كَذَلِكَ يَضْرِبُ اللَّهُ﴾ في آية مثَل الحق والباطل؟","answer":"يؤكد التكرار المثل ويعظّم شأنه بعد تفصيله، وتنتقل الخاتمة من مثل الحق والباطل المذكور إلى تقرير سنة أعمّ في ضرب الأمثال للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص59، تحت «نكتة تكرار جملة «كذلك يضرب الله»»","url":""}]},{"id":"s13-71","number":71,"surah":13,"verses":[18],"references":[{"surah":13,"verses":[18]}],"verseLabel":"الرعد: 18","question":"ما دلالة إجمال جزاء المستجيبين في كلمة ﴿الْحُسْنَى﴾؟","answer":"توحي بغاية الحسن، وتترك الجزاء مجملًا تعظيمًا له؛ فهو أجلّ من أن يحيط وصف بتفاصيله. وتذكر الموسوعة أن الجنة أبلغ ما يتحقق فيه هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص68–69، تحت «إيثار الإجمال في جزاء المستجيبين»","url":""}]},{"id":"s13-72","number":72,"surah":13,"verses":[18],"references":[{"surah":13,"verses":[18]}],"verseLabel":"الرعد: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿سُوءُ الْحِسَابِ﴾ لا سوء العقاب؟","answer":"الحساب يستحضر المناقشة والاستقصاء فيما قُدّم من الأعمال، وقد يسوء الإنسان به ولو لم يعقبه عقاب. فالتعبير أوسع من ذكر العقاب وحده، وفيه تخويف من شدة المحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص74–75، تحت «إيثار لفظ «الحساب» دون (العقاب والعذاب)»","url":""}]},{"id":"s13-73","number":73,"surah":13,"verses":[19],"references":[{"surah":13,"verses":[19]}],"verseLabel":"الرعد: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَمَنْ يَعْلَمُ﴾ لا أفمن يرى؟","answer":"لأن المراد علم يجمع النظر الصحيح والاعتبار حتى يفضي إلى يقين يستقرّ في القلب ويتحقق به الإيمان؛ فلا يقتصر على مجرد الرؤية أو النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص85، تحت «سرّ اختيار العلم دون غيره»","url":""}]},{"id":"s13-74","number":74,"surah":13,"verses":[19],"references":[{"surah":13,"verses":[19]}],"verseLabel":"الرعد: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿أَعْمَى﴾ لا «لا يبصر»؟","answer":"العمى وصف متمكن يصور فساد البصيرة، بخلاف عدم الإبصار الذي قد يكون عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص89–90، تحت «دلالة التعبير بـ«أعمى» دون (لا يبصر)»","url":""}]},{"id":"s13-75","number":75,"surah":13,"verses":[19],"references":[{"surah":13,"verses":[19]}],"verseLabel":"الرعد: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّمَا يَتَذَكَّرُ أُولُو الْأَلْبَابِ﴾؟","answer":"يقصر التذكّر النافع على أصحاب العقول السليمة التي تنتفع بما تعلم؛ فاللُّبّ هو العقل الصافي الذي يهدي صاحبه، لا مجرد عقل يمتلكه ثم يعطّله عن إدراك الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص91–93، تحت «دلالة أسلوب القصر»","url":""}]},{"id":"s13-76","number":76,"surah":13,"verses":[20],"references":[{"surah":13,"verses":[20]}],"verseLabel":"الرعد: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿يُوفُونَ بِعَهْدِ اللَّهِ﴾ بالمضارع؟","answer":"للدلالة على أن الوفاء خُلُق متجدد ملازم، لا موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص99، تحت «دلالة التعبير بالمضارع»","url":""}]},{"id":"s13-77","number":77,"surah":13,"verses":[20],"references":[{"surah":13,"verses":[20]}],"verseLabel":"الرعد: 20","question":"ما سرّ الجمع بين الوفاء بالعهد وعدم نقض الميثاق؟","answer":"الأول إثبات للأداء، والثاني نفي للإفساد بعد التوثيق؛ فاجتمع كمال الفعل والسلامة من ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص102، 105، تحت «سرّ الجمع بين الوفاء بالعهد، وعدم نقض الميثاق»","url":""}]},{"id":"s13-78","number":78,"surah":13,"verses":[20],"references":[{"surah":13,"verses":[20]}],"verseLabel":"الرعد: 20","question":"ما سرّ التعبير بقوله تعالى: ﴿الميثاق﴾ بعد ﴿العهد﴾؟","answer":"من توجيهات الموسوعة أن ذكر الميثاق يوسّع الدلالة إلى ما التزمه الإنسان، فيشمل مواثيق الناس وعهودهم إلى جانب عهد الله؛ وهو تأكيد لإحكام التزامهم، لا تكرار خالٍ من فائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص105–106، تحت «سرّ اختيار التعبير بالميثاق دون العهد»","url":""}]},{"id":"s13-79","number":79,"surah":13,"verses":[21],"references":[{"surah":13,"verses":[21]}],"verseLabel":"الرعد: 21","question":"ما دلالة تكرار ﴿الَّذِينَ﴾ في صفات أولي الألباب؟","answer":"لتجديد التنبيه إلى استقلال كل طائفة من الصفات بالعناية والمدح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص111، تحت «سرّ تكرار اسم الموصول «الذين»»","url":""}]},{"id":"s13-80","number":80,"surah":13,"verses":[21],"references":[{"surah":13,"verses":[21]}],"verseLabel":"الرعد: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا أَمَرَ اللَّهُ بِهِ أَنْ يُوصَلَ﴾ ولم يحدد؟","answer":"عمّم ليشمل الأرحام والإيمان والعهود وكل صلة أمر الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص111–112، تحت «دلالة التعبير بـ«ما» دون (الذي)»","url":""}]},{"id":"s13-81","number":81,"surah":13,"verses":[21],"references":[{"surah":13,"verses":[21]}],"verseLabel":"الرعد: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الْحِسَابِ﴾؟","answer":"الخشية مقرونة بتعظيم المخشيّ والعلم بجلاله، فناسب تعلقها بربهم؛ والخوف من سوء الحساب يبعث على الطاعة واجتناب المخالفة. وقُدّمت الخشية لأنها الأصل الذي ينشأ عنه الخوف من عقابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص114–116، تحت «سرّ اختلاف متعلّق الخشية والخوف»","url":""}]},{"id":"s13-82","number":82,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما دلالة حذف متعلّق الصبر في ﴿صَبَرُوا﴾؟","answer":"ليعم الصبر على الطاعة وعن المعصية وعلى البلاء، فلا يحصر في لون واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص121، تحت «سرّ التعبير بالصبر وحذف متعلّقه»","url":""}]},{"id":"s13-83","number":83,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿ابْتِغَاءَ وَجْهِ رَبِّهِمْ﴾؟","answer":"«الابتغاء» طلب واجتهاد، ويقيّد التعبير صبرهم بقصد رضا الله وثوابه، لا بطلب السمعة أو مباهاة الناس. فالمقصود إبراز إخلاص الدافع إلى الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص122–123، تحت «بلاغة التعبير بقوله: «وجه ربهم»»","url":""}]},{"id":"s13-84","number":84,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿أَقَامُوا الصَّلَاةَ﴾ لا أدّوها؟","answer":"الإقامة تتضمن إتمام أركانها وحدودها والمحافظة عليها، لا مجرد وقوع الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص124–125، تحت «سرّ التعبير بـ(إقامة الصلاة)، دون أدائها»","url":""}]},{"id":"s13-85","number":85,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْفَقُوا مِمَّا رَزَقْنَاهُمْ﴾ ولم يخص الزكاة؟","answer":"ليشمل الواجب والتطوع، و«مِن» تذكر أن المطلوب بعض الرزق لا كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص125–126، تحت «سرّ التعبير عن الزكاة بالإنفاق»","url":""}]},{"id":"s13-86","number":86,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]},{"surah":14,"verses":[31]}],"verseLabel":"الرعد: 22؛ إبراهيم: 31","question":"ما سرّ تقديم ﴿سِرًّا﴾ على ﴿عَلَانِيَةً﴾؟","answer":"في الرعد: 22: تقديم السر يلفت إلى أنه الأصل عند انتفاء سبب يرجّح الإعلان؛ لبعده عن الرياء. وقد تكون العلانية أفضل إذا حققت مقصدًا شريفًا، كالقدوة.\n\nفي إبراهيم: 31: تقديم السر يبرز الإخلاص وصيانة كرامة المتصدَّق عليه، مع بقاء فضل الإعلان إذا دعا الناس إلى الاقتداء والتعاون.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص130، تحت «دلالة البدء بالسرّ»","url":""}]},{"id":"s13-87","number":87,"surah":13,"verses":[22],"references":[{"surah":13,"verses":[22]}],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿يَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ﴾ لا يدفعون؟","answer":"«يدرؤون» يجمع وجوه مدافعة السيئة بالحسنة: بالتوبة والعمل الصالح بعد الذنب، وبالعدول عن السيئة، وبمقابلة إساءة الآخرين بالإحسان. فاختير لسعة دلالته في هذا المقام، لا لمجرد دفع الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص130–132، تحت «سرّ اصطفاء «يدرؤون» دون (يدفعون)»","url":""}]},{"id":"s13-88","number":88,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿جَنَّاتُ عَدْنٍ﴾ بالجمع؟","answer":"يدل الجمع على تعدّد الجنات وتنوّع النعيم، وتذكر الموسوعة أنه يلائم كذلك تفاوت درجات أهلها؛ فليس الجميع في درجة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص140–141، تحت «سرّ التعبير بالجمع دون الإفراد»","url":""}]},{"id":"s13-89","number":89,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿يَدْخُلُونَهَا﴾ لا يسكنونها؟","answer":"الدخول هو أول لحظات الفرح واللقاء بعد الانتظار، فاستحضره لتجديد المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص141، تحت «سرّ التعبير بالفعل «يدخلونها» دون (يسكنونها)»","url":""}]},{"id":"s13-90","number":90,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ صَلَحَ﴾ لا «والذين صلحوا»؟","answer":"«من» تفيد العموم، فتشمل كل من صلح من آبائهم وأزواجهم وذرياتهم. فيجتمع عموم اللحاق مع شرط الصلاح؛ ولا تكفي القرابة وحدها دون إيمان وعمل صالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص142، تحت «سرّ التعبير بـ«من» دون (الذي)»","url":""}]},{"id":"s13-91","number":91,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما سرّ تفصيل الآباء والأزواج والذريات بدل الاكتفاء بلفظ «الأهل»؟","answer":"التفصيل يلفت إلى أهمية كل صنف على حدة، وإلى ما يجد أهل الجنة في اجتماعه بهم من تمام الأنس والسرور؛ مع القيد السابق: ﴿وَمَنْ صَلَحَ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص143–144، تحت «دلالة ذكر هذه الأصناف دون التعبير عنهم بالأهل»","url":""}]},{"id":"s13-92","number":92,"surah":13,"verses":[23],"references":[{"surah":13,"verses":[23]}],"verseLabel":"الرعد: 23","question":"ما دلالة إفراد ﴿بَابٍ﴾ في ﴿مِنْ كُلِّ بَابٍ﴾؟","answer":"يدل على دخول الملائكة من كل باب مختصّ بأهل الجنة المقصودين بالسلام؛ ومع «كل» يشمل الدخول أبوابهم بابًا بابًا، فيظهر كثرة الوفود وتتابع التكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص146–147، تحت «دلالة التعبير بالإفراد «باب» دون الجمع (أبواب)»","url":""}]},{"id":"s13-93","number":93,"surah":13,"verses":[24],"references":[{"surah":13,"verses":[24]}],"verseLabel":"الرعد: 24","question":"ما سرّ التعبير بقوله تعالى: ﴿سَلَامٌ عَلَيْكُمْ﴾ بالتنكير؟","answer":"يفيد تعظيم هذا السلام وتفخيمه؛ فهو سلام من الله تبشّرهم به ملائكته، ومعه كمال الأمان. أما استمراره فتدل عليه الجملة الاسمية، فلا يُنسب التجدد إلى التنكير وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص151، تحت «دلالة التنكير في «سلام عليكم»»","url":""}]},{"id":"s13-94","number":94,"surah":13,"verses":[24],"references":[{"surah":13,"verses":[24]}],"verseLabel":"الرعد: 24","question":"ما دلالة تعدية السلام بـ﴿عَلَيْكُمْ﴾ بدل «لكم»؟","answer":"تذكر الموسوعة أن «سلام عليكم» تحية وبشارة بالأمان صادرة من الملائكة، أما «سلام لكم» فقد تُحمل على الدعاء وطلب السلامة. فاختير ما يلائم تهنئة أهل الجنة بسلام حاصل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص151، تحت «دلالة تعدّي السلام بـ(على) دون اللام»","url":""}]},{"id":"s13-95","number":95,"surah":13,"verses":[24],"references":[{"surah":13,"verses":[24]}],"verseLabel":"الرعد: 24","question":"ما سرّ نسبة هذا التكريم إلى الصبر في ﴿بِمَا صَبَرْتُمْ﴾؟","answer":"لأنه الجامع الذي يحفظ جميع خصالهم: لا وفاء ولا صلاة ولا إحسان بلا صبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص151–152، تحت «سرّ اختيار الصبر دون بقية الصفات المذكورة لهم»","url":""}]},{"id":"s13-96","number":96,"surah":13,"verses":[25],"references":[{"surah":13,"verses":[25]}],"verseLabel":"الرعد: 25","question":"ما سرّ بدء وصف الناقضين في الرعد بـ﴿وَالَّذِينَ يَنْقُضُونَ عَهْدَ اللَّهِ﴾، دون الواو في نظيره من البقرة؟","answer":"في الرعد عُطفت صفات الناقضين على صفات الموفين بالعهد لإبراز المقابلة بين الفريقين. أما في البقرة فجاء ﴿الَّذِينَ يَنْقُضُونَ﴾ بيانًا للفاسقين المذكورين قبله، فاتصل الوصف بالموصوف دون حاجة إلى الواو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص155–156، تحت «سرّ ذكر الواو هنا وحذفها في سورة البقرة»","url":""}]},{"id":"s13-97","number":97,"surah":13,"verses":[25],"references":[{"surah":13,"verses":[25]}],"verseLabel":"الرعد: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿لَهُمُ اللَّعْنَةُ﴾ لا «عليهم اللعنة»؟","answer":"اللام تثبت اختصاصهم واستحقاقهم لها، لا مجرد نزولها عليهم في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص161، تحت «سرّ التعبير بقوله: «لهم اللعنة»، ولم يقل: (عليهم اللعنة)»","url":""}]},{"id":"s13-98","number":98,"surah":13,"verses":[26],"references":[{"surah":13,"verses":[26]}],"verseLabel":"الرعد: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿يَبْسُطُ الرِّزْقَ... وَيَقْدِرُ﴾ لا يوسع ويضيق؟","answer":"«يبسط» يصوّر انتشار الرزق وسعته، وأما «يقدر» فتذكر الموسوعة أنه يدل هنا على تضييق شديد يلائم مقابلة ذلك البسط. فلا يُختزل معنى «يقدر» في مجرد ضبط المقدار دون التضييق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص167–168، تحت «سرّ اختيار الفعل «يبسط» دون (يوسّع)»","url":""}]},{"id":"s13-99","number":99,"surah":13,"verses":[26],"references":[{"surah":13,"verses":[26]}],"verseLabel":"الرعد: 26","question":"ما دلالة تنكير ﴿مَتَاعٌ﴾ في وصف الحياة الدنيا؟","answer":"للتحقير والتقليل: شيء قليل عابر إذا قيس بالآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص171، تحت «سرّ تنكير «متاع»»","url":""}]},{"id":"s13-100","number":100,"surah":13,"verses":[27],"references":[{"surah":13,"verses":[27]}],"verseLabel":"الرعد: 27","question":"ما دلالة ذكر المشيئة مع الإضلال والإنابة مع الهداية في ﴿إِنَّ اللَّهَ يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ أَنَابَ﴾؟","answer":"الهداية والإضلال كلاهما تحت مشيئة الله؛ وذكر الإنابة في جانب الهداية يرغّب في الرجوع إليه والإقبال عليه، ويبيّن قبول المنيب بفضله. فلا يدل اختلاف التعبير على خروج الهداية عن مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص183–184، تحت «سرّ ذكر المشيئة مع الإضلال، وعدم ذكرها مع الهداية»","url":""}]},{"id":"s13-101","number":101,"surah":13,"verses":[28],"references":[{"surah":13,"verses":[28]}],"verseLabel":"الرعد: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿تَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ﴾ بالمضارع؟","answer":"لتصوير السكينة وهي تتجدد كلما تجدد الذكر، لا أثرًا وقع وانتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص189، تحت «سرّ التعبير بالمضارع «وتطمئنّ»»","url":""}]},{"id":"s13-102","number":102,"surah":13,"verses":[28],"references":[{"surah":13,"verses":[28]}],"verseLabel":"الرعد: 28","question":"ما دلالة التعبير عن القرآن بـ﴿ذِكْرِ اللَّهِ﴾ على هذا الوجه من تفسير الآية؟","answer":"تذكر الموسوعة أنه سُمّي ذكرًا لما فيه من المواعظ وأخبار الأمم، وتلحظ في الذكر معنى الشرف أيضًا؛ فهو شرف لمن ينتفع به. وهذا وجه في تفسير الذكر، ولا يحصر الآية في قراءة القرآن وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص190، تحت «سرّ التعبير عن القرآن بالذكر»","url":""}]},{"id":"s13-103","number":103,"surah":13,"verses":[29],"references":[{"surah":13,"verses":[29]}],"verseLabel":"الرعد: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿طُوبَى لَهُمْ وَحُسْنُ مَآبٍ﴾؟","answer":"«طوبى» تجمع الخير والغبطة، ثم «حسن مآب» يثبت جمال النهاية والمرجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص203، تحت «سرّ الجمع بين «طوبى» و«حسن مآب»»","url":""}]},{"id":"s13-104","number":104,"surah":13,"verses":[30],"references":[{"surah":13,"verses":[30]}],"verseLabel":"الرعد: 30","question":"ما سرّ اختيار اسم ﴿الرَّحْمَنِ﴾ في ﴿وَهُمْ يَكْفُرُونَ بِالرَّحْمَنِ﴾؟","answer":"لتفظيع كفرهم: يجحدون من عمّت رحمته، فيقابلون الإنعام بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص224، تحت «نكتة اختيار اسم (الرحمن)»","url":""}]},{"id":"s13-105","number":105,"surah":13,"verses":[30],"references":[{"surah":13,"verses":[30]}],"verseLabel":"الرعد: 30","question":"ما سرّ التعبير في قول النبي ﷺ: ﴿عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ﴾؟","answer":"تقديم «عليه» و«إليه» يخصّ الله بالتوكل والرجوع والتوبة، ويناسب المقابلة مع من يستعين بالأصنام. فالمعنى إعلان الاعتماد عليه وحده والإقبال إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص230–232، تحت «سرّ القصر بالتقديم في: «وإليه متاب»»","url":""}]},{"id":"s13-106","number":106,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما دلالة ترتيب تسيير الجبال ثم تقطيع الأرض ثم تكليم الموتى؟","answer":"تذكر الموسوعة وجوهًا للترتيب؛ منها موافقة ترتيب مطالب المعاندين كما حُكيت، ومنها البدء بالجبال لمناسبتها طبيعة مكة، ثم الأرض وما يتصل بها، ثم الموتى. فلا يُحصر الترتيب في تعليل واحد بالتدرّج من الأسهل إلى الأصعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص242، 244–245، تحت «دلالة ترتيب الأمور الثلاثة في الآية»","url":""}]},{"id":"s13-107","number":107,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿بَلْ لِلَّهِ الْأَمْرُ جَمِيعًا﴾؟","answer":"إضراب عن جدوى اقتراحاتهم إلى الحقيقة الحاكمة: كل أمر الهداية والآيات لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص250–253، تحت «التعبير بـ«بل» في: «بل لله الأمر جميعًا» دون غيره»","url":""}]},{"id":"s13-108","number":108,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَلَمْ يَيْأَسِ الَّذِينَ آمَنُوا﴾؟","answer":"من وجوه التفسير أن «ييأس» بمعنى يعلم ويتبيّن، وتذكر الموسوعة توجيهه مجازًا من اليأس إلى العلم، وتذكر أيضًا معنى قطع الرجاء في إيمان المعاندين. والمقصود ألا يُعلّق المؤمنون الهداية بتحقق المقترحات؛ فلو شاء الله لهدى الناس جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص254–256، تحت «بلاغة المجاز في إطلاق لفظ اليأس»","url":""}]},{"id":"s13-109","number":109,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير بـ﴿جَمِيعًا﴾ في ﴿لَهَدَى النَّاسَ جَمِيعًا﴾؟","answer":"تبرز «جميعًا» اجتماع الناس على الهداية في حال واحدة، فتظهر شمول القدرة؛ وتناسب لفظها السابق في الآية: ﴿بَلْ لِلَّهِ الْأَمْرُ جَمِيعًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص259، تحت «نكتة التعبير بـ«جميعًا» دون (كلّهم)»","url":""}]},{"id":"s13-110","number":110,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿قَارِعَةٌ﴾ بالإفراد؟","answer":"يفيد الإفراد التهويل: فقارعة واحدة تكفي لإفزاعهم، فكيف إذا تكاثرت القوارع؟ وتذكر الموسوعة وجهًا آخر هو وحدة مقصد هذه القوارع في زجر المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص267–268، تحت «دلالة الإفراد في: «قارعة»»","url":""}]},{"id":"s13-111","number":111,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿تَحُلُّ قَرِيبًا مِنْ دَارِهِمْ﴾؟","answer":"على عود الضمير إلى القارعة، يوسّع قربها من دارهم التخويف: فقد يفزعهم ما يحيط بهم قبل أن يصيبهم مباشرة. والمضارع يستحضر دوام التهديد وتجدّده. وتذكر الموسوعة وجهًا آخر أن الخطاب للنبي ﷺ بحلوله قريبًا من ديارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص269–271، 274، تحت «دلالة التعبير بقوله: «قريبًا»»","url":""}]},{"id":"s13-112","number":112,"surah":13,"verses":[31],"references":[{"surah":13,"verses":[31]}],"verseLabel":"الرعد: 31","question":"ما دلالة إفراد ﴿الْمِيعَادَ﴾ وتعريفه؟","answer":"تربط الموسوعة الإفراد باستواء المواعيد عند الله في سهولة إنجازها ودقته، مع اختلاف آثارها على العباد. والتعريف يرسّخ الثقة بتحقّق الميعاد والعدل فيه، فلا يدل الإفراد على نفي تعدّد المواعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص280، تحت «سرّ إفراد لفظة «الميعاد» لا جمعها»","url":""}]},{"id":"s13-113","number":113,"surah":13,"verses":[33],"references":[{"surah":13,"verses":[33]}],"verseLabel":"الرعد: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَمَنْ هُوَ قَائِمٌ عَلَى كُلِّ نَفْسٍ﴾؟","answer":"استفهام إنكاري ينفي التسوية بين الله القائم على كل نفس، المحصي لأعمالها، وبين معبودات عاجزة. ومن توجيهات النظم حذف الخبر لدلالة السياق عليه، كالتقدير: أهو كمن ليس كذلك؟ وفي الحذف تحقير للمقابل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص302–305، تحت «دلالة حذف خبر «أفمن»»","url":""}]},{"id":"s13-114","number":114,"surah":13,"verses":[33],"references":[{"surah":13,"verses":[33]}],"verseLabel":"الرعد: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا كَسَبَتْ﴾ لا اكتسبت؟","answer":"«كسبت» أعم في الخير والشر، والمقام في إحاطة العلم بكل ما يصدر عن النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص307–308، تحت «سرّ اختيار «كسبت» دون (اكتسبت)»","url":""}]},{"id":"s13-115","number":115,"surah":13,"verses":[33],"references":[{"surah":13,"verses":[33]}],"verseLabel":"الرعد: 33","question":"ما سرّ التعبير بـ﴿شُرَكَاءَ﴾ دون «أنداد»، وما دلالة جمعها؟","answer":"«شركاء» يوافق اعترافهم بالله مع إشراك آلهة أخرى في عبادته، دون ادعاء مماثلتها له من كل وجه. والجمع يحكي كثرة معبوداتهم وتعدّدها، ثم يأتي ﴿سَمُّوهُمْ﴾ لإظهار عجز ما عظّموه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص310–311، تحت «سرّ التعبير بـ«شركاء» دون أنداد»","url":""}]},{"id":"s13-116","number":116,"surah":13,"verses":[35],"references":[{"surah":13,"verses":[35]}],"verseLabel":"الرعد: 35","question":"ما دلالة قوله تعالى: ﴿مَثَلُ الْجَنَّةِ الَّتِي وُعِدَ الْمُتَّقُونَ﴾؟","answer":"«مثل الجنة» يبيّن صفتها وشأنها العجيب، ويقرّب نعيمها الغائب إلى الفهم بما يُعرف من الأنهار والثمر والظل؛ مع أن حقيقة نعيمها أعظم مما يحيط به الوصف المألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص338–339، تحت «سرّ التعبير بالمثل دون الوصف في الآية»","url":""}]},{"id":"s13-117","number":117,"surah":13,"verses":[35],"references":[{"surah":13,"verses":[35]}],"verseLabel":"الرعد: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿أُكُلُهَا دَائِمٌ وَظِلُّهَا﴾؟","answer":"يبشّر الوصف بنعيم لا يزول ولا ينقطع، بخلاف نعيم الدنيا. ودلّ ﴿دَائِمٌ﴾ المذكور مع الأكل على دوام الظل أيضًا، فاستُغني عن تكراره إيجازًا: أكلها دائم وظلّها دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص346–348، تحت «سرّ وصف الأكل بالدوام في الآية»","url":""}]},{"id":"s13-118","number":118,"surah":13,"verses":[36],"references":[{"surah":13,"verses":[36]}],"verseLabel":"الرعد: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿يَفْرَحُونَ بِمَا أُنْزِلَ إِلَيْكَ﴾؟","answer":"المضارع يصور تجدد فرح أهل الكتاب الصادقين كلما وافق الوحي ما عندهم من الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص359–360، تحت «دلالة التعبير بالفعل المضارع «يفرحون»»","url":""}]},{"id":"s13-119","number":119,"surah":13,"verses":[37],"references":[{"surah":13,"verses":[37]}],"verseLabel":"الرعد: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿حُكْمًا عَرَبِيًّا﴾ لا كتابًا عربيًا؟","answer":"ليبرز وظيفة القرآن في الفصل والهداية والتشريع، لا مجرد لغته أو صورته المكتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص378–380، تحت «سرّ التعبير بقوله تعالى: «حكمًا»»","url":""}]},{"id":"s13-120","number":120,"surah":13,"verses":[38],"references":[{"surah":13,"verses":[38]}],"verseLabel":"الرعد: 38","question":"ما دلالة توكيد ﴿وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ﴾ في سياق ذكر الأزواج والذرية؟","answer":"يؤكد أن إرسال الرسل حقيقة ثابتة، وأن كونهم بشرًا لهم أزواج وذرية لا ينافي رسالتهم؛ ففيه ردّ على الاعتراض على النبي ﷺ بذلك، وتسلية له بسنة الرسل قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص390–392، تحت «دلالة دخول (قد) على «أرسلنا»»","url":""}]},{"id":"s13-121","number":121,"surah":13,"verses":[38],"references":[{"surah":13,"verses":[38]}],"verseLabel":"الرعد: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا بِإِذْنِ اللَّهِ﴾ وأظهر الاسم؟","answer":"يبين الاستثناء أن الرسول لا يأتي بالآية من تلقاء نفسه، وإنما بأمر الله ومشيئته. وإظهار اسم الله بعد «أرسلنا» و«جعلنا» يربّي المهابة ويؤكد أن الإذن صادر من صاحب العلم والقدرة المحيطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص399–401، تحت «بلاغة الالتفات في قوله: «إلا بإذن الله»»","url":""}]},{"id":"s13-122","number":122,"surah":13,"verses":[39],"references":[{"surah":13,"verses":[39]}],"verseLabel":"الرعد: 39","question":"كيف نفهم ﴿يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ﴾ مع ﴿وَعِنْدَهُ أُمُّ الْكِتَابِ﴾؟","answer":"تذكر الموسوعة أوجهًا للمحو والإثبات، منها نسخ بعض الأحكام وإبقاء غيرها، وتغيير ما يشاء الله من أحوال الخلق. أما «أمّ الكتاب» فهو الأصل الجامع عنده الذي يرجع إليه ذلك كله؛ فلا تعني الآية تجدّد علم لله بعد جهل، بل تصرّفه بعلمه ومشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص406–408، 411–413، تحت «سرّ التعبير بقوله: «وعنده أمّ الكتاب»»","url":""}]},{"id":"s13-123","number":123,"surah":13,"verses":[41],"references":[{"surah":13,"verses":[41]},{"surah":21,"verses":[44]}],"verseLabel":"الرعد: 41؛ الأنبياء: 44","question":"ما سرّ التعبير في الرعد بقوله تعالى: ﴿ننقصها من أطرافها﴾؟","answer":"من توجيهات التعبير تصوير تقلص سلطان المشركين وامتداد سلطان المسلمين تدريجيًا، وإسناده إلى الله بيان لتدبيره ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص431، تحت «سرّ التعبير بقوله: «ننقصها»»","url":""}]},{"id":"s13-131","number":131,"surah":13,"verses":[41],"references":[{"surah":13,"verses":[41]},{"surah":21,"verses":[44]}],"verseLabel":"الرعد: 41؛ الأنبياء: 44","question":"ما بلاغة التمثيل في قوله تعالى في الأنبياء: ﴿نأتي الأرض ننقصها من أطرافها﴾؟","answer":"يمثل التعبير تراجع سلطان المعاندين أمام ظهور الحق، مع اتساع اللفظ لأوجه أخرى من النقص؛ فلا ينحصر في نقصان جغرافي مادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص417، تحت «بلاغة التمثيل في الآية»","url":""}]},{"id":"s13-124","number":124,"surah":13,"verses":[42],"references":[{"surah":13,"verses":[42]}],"verseLabel":"الرعد: 42","question":"ما دلالة وصف تدبيرهم بالمكر ثم قوله: ﴿فَلِلَّهِ الْمَكْرُ جَمِيعًا﴾؟","answer":"يصف المكر تدبيرهم الخفي وحيلهم لصدّ الدعوة؛ ثم يقصر التدبير النافذ على الله: فهو محيط بمكرهم وقادر على إبطاله وأخذهم من حيث لا يشعرون. وتعرض الموسوعة لإسناد المكر إليه توجيه الحقيقة أو المجاز والمشاكلة، فلا يحمل على مكر البشر المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص440–443، تحت «سرّ التعبير بلفظ «المكر»»","url":""}]},{"id":"s13-125","number":125,"surah":13,"verses":[43],"references":[{"surah":13,"verses":[43]}],"verseLabel":"الرعد: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ﴾ ولم يسمِّهم؟","answer":"يبرز الموصول صفة العلم بالكتاب بوصفها موضع الحجة، ويحتمل العموم دون حصره في شخص مسمّى. وعلى تفسير المراد بعلماء أهل الكتاب يدخل من عرف دلائل صدق الرسول؛ وتذكر الموسوعة أقوالًا أخرى في تعيين المراد فلا يُقطع بقول واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص460–462، تحت «دلالة التعبير بالاسم الموصول»","url":""}]},{"id":"s14-1","number":1,"surah":14,"verses":[1],"references":[{"surah":14,"verses":[1]}],"verseLabel":"إبراهيم: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتُخْرِجَ النَّاسَ﴾ لا المؤمنين؟","answer":"لأن الرسالة موجهة إلى الناس جميعًا في كل زمان ومكان؛ فالتعبير يدفع توهم اختصاصها بالعرب أو بفئة دون أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص480–481، تحت «بلاغة الاحتراس في لفظ الناس»","url":""}]},{"id":"s14-2","number":2,"surah":14,"verses":[1,23],"references":[{"surah":14,"verses":[1,23]}],"verseLabel":"إبراهيم: 1؛ إبراهيم: 23","question":"ما دلالة ﴿بإذن ربهم﴾ في مطلع سورة إبراهيم؟","answer":"إخراج الناس من الظلمات إلى النور من آثار تربية الله لعباده؛ فذكر الربوبية يلائم الرعاية والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص484، تحت «نكتة ذكر عنوان الربوبية دون الألوهية»","url":""}]},{"id":"s14-163","number":163,"surah":14,"verses":[1,23],"references":[{"surah":14,"verses":[1,23]}],"verseLabel":"إبراهيم: 1؛ إبراهيم: 23","question":"ما دلالة إضافة الرب إلى ضمير المؤمنين في قوله: ﴿خالدين فيها بإذن ربهم﴾؟","answer":"تظهر الإضافة مزيد اللطف بالمؤمنين؛ فدخول الجنة ونعيمها من فضل ربهم ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص774، تحت «سر إضافة الضمير، إلى الرب القدير»","url":""}]},{"id":"s14-3","number":3,"surah":14,"verses":[1],"references":[{"surah":14,"verses":[1]}],"verseLabel":"إبراهيم: 1","question":"ما سرّ جمع ﴿الظلمات﴾ وإفراد ﴿النور﴾؟","answer":"لأن مسالك الضلال كثيرة متشعبة، والحق في أصله طريق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص483، تحت «نكتة جمع الظلمات وإفراد النور»","url":""}]},{"id":"s14-4","number":4,"surah":14,"verses":[1],"references":[{"surah":14,"verses":[1]}],"verseLabel":"إبراهيم: 1","question":"ما دلالة وصف صاحب الصراط بـ﴿الْعَزِيزِ الْحَمِيدِ﴾؟","answer":"العزيز غالب لا تُعجزه معارضة، والحميد مستحق للحمد على نعمة الوحي والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص486–487، تحت «مناسبة تلازم صفتي العزيز الحميد»","url":""}]},{"id":"s14-5","number":5,"surah":14,"verses":[2],"references":[{"surah":14,"verses":[2]}],"verseLabel":"إبراهيم: 2","question":"ما بلاغة وصف الله بالموصول في قوله: ﴿الذي له ما في السماوات وما في الأرض﴾؟","answer":"تكشف الصلة ملك الله الشامل لكل شيء، فتقرر عظمته واستحقاقه وحده للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص489، تحت «بلاغة التعبير بالموصول»","url":""}]},{"id":"s14-164","number":164,"surah":14,"verses":[2],"references":[{"surah":14,"verses":[2]}],"verseLabel":"إبراهيم: 2","question":"ما التعريض بالمشركين في قوله: ﴿الذي له ما في السماوات وما في الأرض﴾؟","answer":"يعرض بمن عدل عن صراط المالك لكل شيء إلى عبادة من لا يملك شيئا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص489، تحت «بلاغة التعريض بالمشركين»","url":""}]},{"id":"s14-6","number":6,"surah":14,"verses":[2],"references":[{"surah":14,"verses":[2]}],"verseLabel":"إبراهيم: 2","question":"ما دلالة ﴿مِنْ﴾ في قوله تعالى: ﴿وَوَيْلٌ لِلْكَافِرِينَ مِنْ عَذَابٍ شَدِيدٍ﴾؟","answer":"تدل على ابتداء الويل من عذاب شديد؛ وفي ذلك تهويل لما يلقونه، فإذا كان هذا مبدأ ويلهم فكيف بسائر العذاب؟","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص494، تحت «معنى حرف الجر من»","url":""}]},{"id":"s14-7","number":7,"surah":14,"verses":[3],"references":[{"surah":14,"verses":[3]}],"verseLabel":"إبراهيم: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَحِبُّونَ الْحَيَاةَ الدُّنْيَا عَلَى الْآخِرَةِ﴾ لا يحبون؟","answer":"تفيد الصيغة شدة الحب وتكلفه؛ فهم يؤثرون الدنيا ويطلبونها حتى يجعلوها أحب إليهم من الآخرة، لا مجرد ميل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص502–503، تحت «معنى السين والتاء في قوله يستحبون»","url":""}]},{"id":"s14-8","number":8,"surah":14,"verses":[3],"references":[{"surah":14,"verses":[3]}],"verseLabel":"إبراهيم: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يَبْغُونَهَا عِوَجًا﴾ لا ميلًا؟","answer":"العوج ميل مضطرب لا استقامة معه؛ فاختياره يصور رغبتهم في صرف سبيل الله عن استقامته، وهو أدل على الفساد من مطلق الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص514، تحت «العوج والميل»","url":""}]},{"id":"s14-9","number":9,"surah":14,"verses":[3],"references":[{"surah":14,"verses":[3]}],"verseLabel":"إبراهيم: 3","question":"ما بلاغة ﴿في﴾ في قوله: ﴿في ضلال﴾؟","answer":"تصور ﴿في﴾ إحاطة الضلال بهم كأنه ظرف لا ينفكون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص511، تحت «بلاغة استعمال حرف الظرفية في»","url":""}]},{"id":"s14-165","number":165,"surah":14,"verses":[3],"references":[{"surah":14,"verses":[3]}],"verseLabel":"إبراهيم: 3","question":"لماذا وصف الضلال بأنه ﴿بعيد﴾؟","answer":"يصور شدة ابتعادهم عن الحق وصعوبة رجوعهم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص512، تحت «سر وصف لفظ ضلال بالبعيد»","url":""}]},{"id":"s14-10","number":10,"surah":14,"verses":[4],"references":[{"surah":14,"verses":[4]}],"verseLabel":"إبراهيم: 4","question":"ما سرّ إفراد ﴿لِسَانِ﴾ في قوله تعالى: ﴿بِلِسَانِ قَوْمِهِ﴾؟","answer":"لأن المراد اللغة، و«اللسان» بهذا المعنى اسم جنس يقع على القليل والكثير؛ فصح إفراده مع إضافته إلى القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص519–520، تحت «وجه إفراد اللسان»","url":""}]},{"id":"s14-11","number":11,"surah":14,"verses":[4],"references":[{"surah":14,"verses":[4]}],"verseLabel":"إبراهيم: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيُبَيِّنَ لَهُمْ﴾ بالمضارع؟","answer":"تدل صيغة المضارع على تجدد البيان واستمراره؛ إذ تتجدد حاجة المدعوين إلى بيان الرسالة وتوضيحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص522، تحت «دلالة صيغة المضارعة في ليبين»","url":""}]},{"id":"s14-12","number":12,"surah":14,"verses":[4],"references":[{"surah":14,"verses":[4]}],"verseLabel":"إبراهيم: 4","question":"ما دلالة ختام الآية بـ﴿الْعَزِيزُ الْحَكِيمُ﴾؟","answer":"العزيز لا يغلب في مشيئته ولا يخرج شيء عن قدرته، والحكيم يضع الأشياء مواضعها؛ فالهداية والإضلال جاريان على عزته وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص524–525، تحت «بلاغة التذييل في جملة الفاصلة»","url":""}]},{"id":"s14-13","number":13,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما سرّ التعبير في أمر موسى بـ﴿أَخْرِجْ قَوْمَكَ﴾؟","answer":"لفظ «قومك» يستحضر صلته بمن أرسل إليهم، ويبعث رحمته بهم وإحساسه بمسؤوليته عن هدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص533، تحت «توجيه إيثار لفظ قوم»","url":""}]},{"id":"s14-14","number":14,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما سرّ جمع ﴿الظلمات﴾ وإفراد ﴿النور﴾ في أمر موسى بإخراج قومه؟","answer":"جُمعت الظلمات لتعدد مصادر الضلال ومظاهر الكفر، وأفرد النور لأن الحق واحد ومصدر الهداية واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص535، تحت «نكتتا جمع الظلمات وإفراد النور»","url":""}]},{"id":"s14-15","number":15,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما المراد بـ﴿أيام الله﴾؟","answer":"هي الأيام ذات الأحداث العظيمة من إنعام الله ونصره وإهلاك المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص538، تحت «بلاغة المجاز في قوله بأيام الله»","url":""}]},{"id":"s14-166","number":166,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما سر إضافة الأيام إلى الله؟","answer":"تعظم الإضافة شأنها وتبرز ما ظهر فيها من تدبير الله ونصره وعقابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص539، تحت «نكتة الإضافة في قوله بأيام الله»","url":""}]},{"id":"s14-16","number":16,"surah":14,"verses":[5],"references":[{"surah":14,"verses":[5]}],"verseLabel":"إبراهيم: 5","question":"ما دلالة ختام الآية بـ﴿لِكُلِّ صَبَّارٍ شَكُورٍ﴾؟","answer":"لأن المنتفع بآيات الله هو من يصبر عند البلاء ويشكر عند النعمة؛ فجمع الوصفين يلائم ما في أيام الله من الشدة والرخاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص543، تحت «سر اقتران وصفي صبار شكور»","url":""}]},{"id":"s14-17","number":17,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قول موسى: ﴿اذْكُرُوا نِعْمَةَ اللَّهِ﴾ بالإفراد؟","answer":"«نعمة» هنا اسم جنس يشمل نعم الله المتعددة، وفي إفرادها توجيه للنظر إلى جنس النعمة وما يندرج فيه من فضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص552–553، تحت «نكتة إفراد النعمة»","url":""}]},{"id":"s14-18","number":18,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سرّ أمر بني إسرائيل بذكر نعمة الله في هذا الموضع؟","answer":"لأنهم كانوا متعلقين بالنعم الحسية؛ فجاء تذكيرهم بالنعم طريقًا إلى تذكيرهم بالمنعم وشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص553، تحت «نكتة الأمر بذكر النعمة لا المنعم»","url":""}]},{"id":"s14-20","number":20,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يُذَبِّحُونَ أَبْنَاءَكُمْ﴾ لا أولادكم؟","answer":"لأن المقصود قتل الذكور دون الإناث، ولفظ «الأولاد» يشملهما؛ فالتعبير بالأبناء يحدد من وقع عليهم التذبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص560، تحت «فائدة التعبير بالأبناء دون الأولاد»","url":""}]},{"id":"s14-21","number":21,"surah":14,"verses":[6],"references":[{"surah":14,"verses":[6]}],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَحْيُونَ نِسَاءَكُمْ﴾ بالمضارع؟","answer":"ليصور تجدد استحيائهن واستمراره، ويستحضر الإذلال المتكرر الذي كان يصاحب إبقاءهن أحياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص561، تحت «نكتة استعمال لفظ الاستحياء بصيغة المضارع»","url":""}]},{"id":"s14-22","number":22,"surah":14,"verses":[7],"references":[{"surah":14,"verses":[7]}],"verseLabel":"إبراهيم: 7","question":"ما سرّ حذف المفعول الثاني في قوله تعالى: ﴿لَأَزِيدَنَّكُمْ﴾؟","answer":"لإفادة عموم الزيادة دون حصرها في نعمة معينة؛ فقد تكون في الدنيا أو الآخرة أو فيهما، وتشمل ما يخطر للإنسان وما لا يخطر له.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص570–571، تحت «نكتة حذف المفعول»","url":""}]},{"id":"s14-23","number":23,"surah":14,"verses":[7],"references":[{"surah":14,"verses":[7]}],"verseLabel":"إبراهيم: 7","question":"ما سرّ قوله تعالى: ﴿إِنَّ عَذَابِي لَشَدِيدٌ﴾ بدل «لأعذبنكم»؟","answer":"صرح بالوعد بالزيادة، وجاء الوعيد بالعذاب تعريضًا؛ وهذا ألطف بالمخاطبين وأوقع في نفوسهم، والجملة أعم من تخصيصهم وحدهم بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص572، تحت «بلاغة اختلاف التعبير في المقابلات القرآنية»","url":""}]},{"id":"s14-24","number":24,"surah":14,"verses":[8],"references":[{"surah":14,"verses":[8]}],"verseLabel":"إبراهيم: 8","question":"ما سرّ التعبير في قول موسى: ﴿إِنْ تَكْفُرُوا أَنْتُمْ﴾ مع ذكر الضمير المنفصل؟","answer":"جاء ﴿أنتم﴾ لتوكيد ضمير الجماعة في ﴿تكفروا﴾، وللتمهيد لعطف ﴿ومن في الأرض﴾ عليه؛ وفي هذا التوكيد مزيد توجيه للزجر إلى المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص577، تحت «فائدة الضمير المنفصل»","url":""}]},{"id":"s14-25","number":25,"surah":14,"verses":[8],"references":[{"surah":14,"verses":[8]}],"verseLabel":"إبراهيم: 8","question":"ما دلالة ختام الآية بـ﴿لَغَنِيٌّ حَمِيدٌ﴾؟","answer":"غني عن شكر عباده وتعظيمهم، وحميد مستحق للحمد على إنعامه الدائم؛ فلا يضره كفرهم ولا تنقص به صفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص579، تحت «نكتة الختم بصفتي لغني حميد»","url":""}]},{"id":"s14-26","number":26,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿نَبَأُ الَّذِينَ مِنْ قَبْلِكُمْ﴾ لا خبرهم؟","answer":"لأن النبأ خبر ذو شأن وفائدة مهمة، فيلائم خبر الأمم السابقة الذي يستحق أن يتلقاه الجميع للعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص583، تحت «سر إيثار لفظ نبأ»","url":""}]},{"id":"s14-27","number":27,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما سرّ ذكر قوم نوح وعاد وثمود ثم قوله: ﴿وَالَّذِينَ مِنْ بَعْدِهِمْ﴾؟","answer":"ذكرت تلك الأمم لقرب أخبار هلاكها من المخاطبين، ثم وسع الكلام إلى أمم أخرى كثيرة لا يحصيها إلا الله؛ فتجتمع العبرة بالمعلوم مع التنبيه إلى ما خفي من أخبار الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص584، تحت «توجيه الخصوص بالذكر»","url":""}]},{"id":"s14-28","number":28,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَعْلَمُهُمْ إِلَّا اللَّهُ﴾؟","answer":"فيها بيان كثرة الأمم التي لا يحيط البشر بعددها وأحوالها، وأن علمها عند الله وحده؛ فلا يصح ادعاء الإحاطة بأخبار جميع الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص585، تحت «أثر الإعراب في بيان المعاني»","url":""}]},{"id":"s14-29","number":29,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما دلالة صورة ﴿فَرَدُّوا أَيْدِيَهُمْ فِي أَفْوَاهِهِمْ﴾ في التعبير عن رفض الرسل؟","answer":"من أوجه تفسيرها أنهم ردوا أيديهم في أفواه الرسل لإسكاتهم؛ فتجسد الصورة شدة الغيظ والإصرار على إنهاء الحوار ومنع سماع الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص590، تحت «بلاغة استعمال حرف الظرفية»","url":""}]},{"id":"s14-30","number":30,"surah":14,"verses":[9],"references":[{"surah":14,"verses":[9]}],"verseLabel":"إبراهيم: 9","question":"ما دلالة وصف الشك بـ﴿مُرِيبٍ﴾ في قولهم: ﴿وَإِنَّا لَفِي شَكٍّ مِمَّا تَدْعُونَنَا إِلَيْهِ مُرِيبٍ﴾؟","answer":"«مريب» صفة للشك، تزيده توكيدًا وتصف ما يصاحبه من قلق واضطراب؛ فهم يبالغون في إظهار تشككهم في دعوة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص593، تحت «علة وصف الشك بالمريب»","url":""}]},{"id":"s14-31","number":31,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما سرّ تقديم ﴿فِي اللَّهِ﴾ في قول الرسل: ﴿أَفِي اللَّهِ شَكٌّ﴾؟","answer":"لأن الإنكار منصب على تعلق الشك بالله مع ظهور أدلة وحدانيته؛ فقدم ما هو موضع الإنكار، لا مجرد وجود الشك في أي أمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص600، تحت «نكتة تقديم الجار والمجرور»","url":""}]},{"id":"s14-32","number":32,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما دلالة وصف الله بـ﴿فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ﴾ في مقام إنكار الشك؟","answer":"السماوات والأرض آيتان عظيمتان على وجود خالقهما ووحدانيته؛ فذكر إبداعهما يقيم الحجة على من يشك في فاطرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص600، تحت «فائدة إيثار اسم فاطر»","url":""}]},{"id":"s14-33","number":33,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما بلاغة المجاز في قوله: ﴿يدعوكم﴾؟","answer":"ينسب الدعوة إلى الله إظهارا لعنايته ولطفه، إذ يدعوهم إلى الإيمان بواسطة رسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص602، تحت «بلاغة المجاز في لفظ الدعاء»","url":""}]},{"id":"s14-167","number":167,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما دلالة اللام في ﴿ليغفر لكم﴾؟","answer":"تبين أن المغفرة غاية الدعوة وثمرتها، وفي ذلك ترغيب في الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص603، تحت «دلالة تعدي الفعل باللام»","url":""}]},{"id":"s14-34","number":34,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُؤَخِّرَكُمْ﴾ لا يمهلكم؟","answer":"لأن المقام مقام وعد بالمغفرة والسلامة إلى الأجل المقدر؛ فناسبه «التأخير»، بخلاف «الإمهال» الذي يكثر وروده في سياق الوعيد والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص604–605، تحت «نكتة إيثار استعمال لفظ التأخير دون الإمهال»","url":""}]},{"id":"s14-35","number":35,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما دلالة ﴿إلى﴾ في ﴿إلى أجل مسمى﴾؟","answer":"تدل على انتهاء مدة التأخير عند غاية محددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص605، تحت «فائدة استعمال حرف انتهاء الغاية»","url":""}]},{"id":"s14-168","number":168,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما دلالة وصف الأجل بأنه ﴿مسمى﴾؟","answer":"يبين أنه محدد معلوم لله وتستوفى مدته من غير تعجيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص605، تحت «فائدة النعت ودلالته»","url":""}]},{"id":"s14-36","number":36,"surah":14,"verses":[10],"references":[{"surah":14,"verses":[10]}],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿تَصُدُّونَا﴾ لا تمنعوننا؟","answer":"الصد يجمع المنع والصرف؛ وفي هذا السياق هو صرفهم عن عبادة الأصنام بالحجة والبرهان، ولذلك كان أدق من مطلق المنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص607، تحت «نكتة التعبير بالصد دون المنع»","url":""}]},{"id":"s14-37","number":37,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ إضافة الرسل إلى أقوامهم في قوله: ﴿قَالَتْ لَهُمْ رُسُلُهُمْ﴾؟","answer":"لتذكيرهم بأن الرسل منهم، يعرفون صدقهم ولسانهم، فتقوم الحجة أقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص616، تحت «سر إضافة الرسل إلى ضمير أقوام»","url":""}]},{"id":"s14-38","number":38,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ التعبير في قول الرسل: ﴿إِنْ نَحْنُ إِلَّا بَشَرٌ مِثْلُكُمْ﴾؟","answer":"أقروا بالمماثلة البشرية ثم أبطلوا لوازمها الفاسدة؛ فالنبوة فضل من الله لا خروج عن البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص617، تحت «سر تقييد الخبر بوصف مثلكم»","url":""}]},{"id":"s14-39","number":39,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿يَمُنُّ عَلَى مَنْ يَشَاءُ مِنْ عِبَادِهِ﴾؟","answer":"يبين التعبير أن النبوة فضل من الله يمن به على من يشاء من عباده؛ فالمماثلة في البشرية لا تمنع اختصاص بعض البشر بالرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص620، تحت «دلالة التعبير بالمضارع يشاء»","url":""}]},{"id":"s14-40","number":40,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿بِسُلْطَانٍ﴾ نكرة؟","answer":"التنكير هنا لتعظيم شأن المعجزة التي طلبوها؛ فهي أمر لا يملكه الرسل من عند أنفسهم، وإنما تكون بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص622، تحت «غرض تنكير سلطان»","url":""}]},{"id":"s14-41","number":41,"surah":14,"verses":[11],"references":[{"surah":14,"verses":[11]}],"verseLabel":"إبراهيم: 11","question":"ما سرّ إظهار اسم الله في ﴿وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ﴾؟","answer":"ليجدد الاهتمام ويعظم شأن التوكل على الله، فيثبت في النفس أن الاعتماد والنصرة منه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص624، تحت «نكتة إظهار لفظ الجلالة في موضع الإضمار»","url":""}]},{"id":"s14-42","number":42,"surah":14,"verses":[11,12],"references":[{"surah":14,"verses":[11,12]}],"verseLabel":"إبراهيم: 11-12","question":"ما دلالة ﴿وعلى الله فليتوكل المؤمنون﴾؟","answer":"يربط التوكل بالإيمان؛ فالثقة بالله شأن المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص625، تحت «معنى ال في قوله المؤمنون»","url":""}]},{"id":"s14-169","number":169,"surah":14,"verses":[11,12],"references":[{"surah":14,"verses":[11,12]}],"verseLabel":"إبراهيم: 11-12","question":"ما دلالة ﴿وعلى الله فليتوكل المتوكلون﴾؟","answer":"يؤكد التوكل فيمن اتصف به ويحثهم على الثبات عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص638، تحت «جناس الاشتقاق فليتوكل المتوكلون»","url":""}]},{"id":"s14-43","number":43,"surah":14,"verses":[12],"references":[{"surah":14,"verses":[12]}],"verseLabel":"إبراهيم: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا لَنَا أَلَّا نَتَوَكَّلَ عَلَى اللَّهِ﴾؟","answer":"هو استفهام إنكاري عن ترك التوكل: أي عذر لنا فيه وقد أنعم الله علينا بالهداية؟ فيقرر أن التوكل مقتضى الإيمان بنعمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص629، تحت «غرض الاستفهام وما لنا»","url":""}]},{"id":"s14-44","number":44,"surah":14,"verses":[12],"references":[{"surah":14,"verses":[12]}],"verseLabel":"إبراهيم: 12","question":"ما سرّ جمع ﴿سُبُلَنَا﴾ في كلام الرسل؟","answer":"لأن لكل رسول شريعة ومنهاجًا يهدي قومه به؛ فجمعت السبل باعتبار شرائع الرسل، مع وحدة أصل الهداية إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص631–632، تحت «سبب جمع سبيل في وقد هدانا سبلنا»","url":""}]},{"id":"s14-45","number":45,"surah":14,"verses":[12],"references":[{"surah":14,"verses":[12]}],"verseLabel":"إبراهيم: 12","question":"ما دلالة توالي المؤكدات في ﴿وَلَنَصْبِرَنَّ عَلَى مَا آذَيْتُمُونَا﴾؟","answer":"لام القسم ونون التوكيد الثقيلة تظهران رسوخ عزم الرسل على الصبر؛ وصيغة المضارع تصور تجدد ثباتهم كلما تجدد الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص632–633، تحت «نكتة توالي المؤكدات في ولنصبرن»","url":""}]},{"id":"s14-46","number":46,"surah":14,"verses":[12],"references":[{"surah":14,"verses":[12]}],"verseLabel":"إبراهيم: 12","question":"ما سرّ عدم تقييد الإيذاء بنوع معين في ﴿عَلَى مَا آذَيْتُمُونَا﴾؟","answer":"ليتسع لما يلقاه الرسل من العناد واقتراح الآيات وسائر الأذى، فيعلنوا الصبر عليه كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص633، تحت «نكتة حذف متعلق الإيذاء آذيتمونا»","url":""}]},{"id":"s14-47","number":47,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"ما دلالة المؤكدات في تهديد الكفار: ﴿لَنُخْرِجَنَّكُمْ﴾ و﴿لَتَعُودُنَّ﴾؟","answer":"لام القسم ونون التوكيد تكشفان شدة إصرارهم على تنفيذ أحد الأمرين: إخراج الرسل أو حملهم على الدخول في ملتهم؛ فيظهر بلوغ العناد حد الإكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص643، تحت «نكتة توالي المؤكدات لنخرجنكم»","url":""}]},{"id":"s14-48","number":48,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"كيف يُفهم قولهم: ﴿لَتَعُودُنَّ فِي مِلَّتِنَا﴾ مع أن الرسل لم يكونوا عليها؟","answer":"من أوجه تفسيره أن «العود» بمعنى الصيرورة: أي لتصيرن في ملتنا، لا الرجوع إلى كفر سابق. ويذكر المصدر أيضًا حمل الخطاب على الأتباع بطريق التغليب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص645، تحت «نكتة التعبير بالعود رغم أنهم لم يكونوا على دينهم»","url":""}]},{"id":"s14-49","number":49,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"ما سرّ تقديم الإخراج على العودة في الملة؟","answer":"لأن المقام مقام تهديد وتخويف، فبدؤوا بالإخراج وهو العقوبة التي يقدرون عليها، وجعلوا الدخول في ملتهم سبيل النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص645، تحت «نكتة تقديم لنخرجنكم على لتعودن»","url":""}]},{"id":"s14-50","number":50,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"لماذا قيل: ﴿فأوحى إليهم ربهم﴾ بلفظ الرب؟","answer":"يناسب لفظ الرب تدبير أمر الرسل ونصرتهم وإهلاك الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص647، تحت «نكتة الإتيان بلفظ الرب دون لفظ الجلالة»","url":""}]},{"id":"s14-170","number":170,"surah":14,"verses":[13],"references":[{"surah":14,"verses":[13]}],"verseLabel":"إبراهيم: 13","question":"ما دلالة إضافة الرب إلى ضمير الرسل؟","answer":"في الإضافة تشريف وتأنيس وتأكيد أنهم في رعاية ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص648، تحت «نكتة إضافة الرب إلى ضمير الرسل»","url":""}]},{"id":"s14-51","number":51,"surah":14,"verses":[13,14],"references":[{"surah":14,"verses":[13,14]}],"verseLabel":"إبراهيم: 13-14","question":"ما دلالة التوكيد في ﴿لَنُهْلِكَنَّ الظَّالِمِينَ﴾ و﴿لَنُسْكِنَنَّكُمُ الْأَرْضَ﴾؟","answer":"لام القسم ونون التوكيد تثبتان تحقق الوعد بإهلاك الظالمين وإسكان الرسل والمؤمنين الأرض؛ فيطمئنون إلى وعد الله في مواجهة تهديد الكفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص648، تحت «نكتة توالي المؤكدات في لنهلكن»","url":""}]},{"id":"s14-52","number":52,"surah":14,"verses":[14],"references":[{"surah":14,"verses":[14]}],"verseLabel":"إبراهيم: 14","question":"ما دلالة ﴿ذلك لمن خاف مقامي﴾؟","answer":"يدل على خوف الوقوف بين يدي الله وهيبة مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص655، تحت «دلالة جملة الصلة»","url":""}]},{"id":"s14-171","number":171,"surah":14,"verses":[14],"references":[{"surah":14,"verses":[14]}],"verseLabel":"إبراهيم: 14","question":"لماذا عطف ﴿وخاف وعيد﴾؟","answer":"يجمع إلى تعظيم مقام الله الحذر من عقابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص656، تحت «نكتة عطف وخاف وعيد»","url":""}]},{"id":"s14-53","number":53,"surah":14,"verses":[14],"references":[{"surah":14,"verses":[14]}],"verseLabel":"إبراهيم: 14","question":"ما سرّ تقديم خوف المقام على خوف الوعيد؟","answer":"لأن تعظيم الله أصل، والخوف من العقوبة أثر تابع له.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص657، تحت «نكتة تقديم خوف المقام على الوعيد»","url":""}]},{"id":"s14-54","number":54,"surah":14,"verses":[15],"references":[{"surah":14,"verses":[15]}],"verseLabel":"إبراهيم: 15","question":"ما دلالة صيغة ﴿استفتحوا﴾؟","answer":"تدل زيادة المبنى على طلب الفتح والحكم والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص662، تحت «نكتة زيادة المبنى في واستفتحوا»","url":""}]},{"id":"s14-172","number":172,"surah":14,"verses":[15],"references":[{"surah":14,"verses":[15]}],"verseLabel":"إبراهيم: 15","question":"إلى من يعود ضمير ﴿استفتحوا﴾؟","answer":"يحتمل الرسل الذين طلبوا النصر، أو الكفار الذين طلبوا الفصل والعذاب تهكما.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص661، تحت «معنى الواو ودلالتها في واستفتحوا»","url":""}]},{"id":"s14-55","number":55,"surah":14,"verses":[15],"references":[{"surah":14,"verses":[15]}],"verseLabel":"إبراهيم: 15","question":"ما دلالة الجمع بين ﴿جَبَّارٍ عَنِيدٍ﴾؟","answer":"«جبار» يصور تكبره وامتناعه عن قبول الحق، و«عنيد» يصور ميله عن الحق ومعاندته له؛ فاجتمع الاستكبار والإصرار على المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص664، تحت «نكتة الجمع بين جبار وعنيد»","url":""}]},{"id":"s14-56","number":56,"surah":14,"verses":[15],"references":[{"surah":14,"verses":[15]}],"verseLabel":"إبراهيم: 15","question":"ما سرّ تنكير ﴿جَبَّارٍ﴾ و﴿عَنِيدٍ﴾؟","answer":"لتهوين شأنه وتحقيره؛ فمهما اشتد تجبره وعناده في الدنيا فمآله الخيبة والخذلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص665، تحت «نكتة تنكير جبار وعنيد»","url":""}]},{"id":"s14-57","number":57,"surah":14,"verses":[16],"references":[{"surah":14,"verses":[16]}],"verseLabel":"إبراهيم: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ وَرَائِهِ جَهَنَّمُ﴾؟","answer":"تصور العبارة جهنم مترصدة له لا يفلت منها؛ ومن معانيها أن عذابها آتٍ بعد حياته وخيبته في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص668، تحت «بلاغة الاستعارة في من ورائه جهنم»","url":""}]},{"id":"s14-58","number":58,"surah":14,"verses":[16],"references":[{"surah":14,"verses":[16]}],"verseLabel":"إبراهيم: 16","question":"ما سرّ بناء ﴿يُسْقَى﴾ للمفعول؟","answer":"لأن الغرض تصوير ما يلقاه من السقيا والعذاب، فلا يتعلق المقصود بتسمية الساقي؛ فيبقى النظر منصبًا على حال المعذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص669، تحت «نكتة التعبير بالفعل المبني للمفعول ويسقى»","url":""}]},{"id":"s14-59","number":59,"surah":14,"verses":[16],"references":[{"surah":14,"verses":[16]}],"verseLabel":"إبراهيم: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿مَاءٍ صَدِيدٍ﴾؟","answer":"يذكر الماء أولًا فيثير توقع الارتواء، ثم يبين أنه صديد فينقلب التوقع إلى نفور وعذاب؛ وهذا الإيضاح بعد الإبهام يزيد الصورة تهويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص671، تحت «نكتة الإيضاح بعد الإبهام»","url":""}]},{"id":"s14-60","number":60,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتَجَرَّعُهُ﴾؟","answer":"التفعل يصور ابتلاعه جرعة بعد جرعة بمشقة، لا شربًا طبيعيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص675، تحت «دلالة التعبير بيتجرعه»","url":""}]},{"id":"s14-61","number":61,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَأْتِيهِ الْمَوْتُ مِنْ كُلِّ مَكَانٍ﴾؟","answer":"تصور العبارة أسباب الموت وآلامه محيطة به من كل جهة، كأنها تهاجمه؛ ومع اجتماعها لا يموت فيستريح، بل يستمر عذابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص677، تحت «نكتة الكناية في ويأتيه الموت من كل مكان»","url":""}]},{"id":"s14-62","number":62,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا هُوَ بِمَيِّتٍ﴾ جملة اسمية مؤكدة بالباء؟","answer":"لترسيخ نفي الموت تمامًا مع تكرر أسبابه، فلا يجد نهاية للألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص679، تحت «فائدة التعبير بالجملة الاسمية وما هو بميت»","url":""}]},{"id":"s14-63","number":63,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما دلالة تكرار ﴿مِنْ وَرَائِهِ﴾ في وصف العذاب؟","answer":"يجدد التهديد بما ينتظره من العذاب، ويصور مجيئه من جهة خافية يغفل عنها؛ فلا ينتهي هوله بما وصف من الصديد وآلام الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص681، تحت «نكتة تكرار من ورائه»","url":""}]},{"id":"s14-64","number":64,"surah":14,"verses":[17],"references":[{"surah":14,"verses":[17]}],"verseLabel":"إبراهيم: 17","question":"ما دلالة وصف العذاب بـ﴿غَلِيظٌ﴾؟","answer":"استعير الغلظ، وهو ضد الرقة في المحسوسات، لشدة العذاب واستمراره؛ فيوحي بعذاب لا يخف ولا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص681، تحت «نكتة التعبير بالاستعارة عذاب غليظ»","url":""}]},{"id":"s14-65","number":65,"surah":14,"verses":[18],"references":[{"surah":14,"verses":[18]}],"verseLabel":"إبراهيم: 18","question":"ما سرّ تشبيه أعمال الكافرين بالرماد؟","answer":"الرماد يتفرق فلا يبقى منه نفع، وكذلك أعمالهم لا تنفعهم في الآخرة لفقد أصل الإيمان. وهو أثر احتراق، فيناسب تصوير ما أبطله الكفر من ثمرات الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص691، تحت «أوجه الشبه بين أعمال الكفار وبين الرماد»","url":""}]},{"id":"s14-66","number":66,"surah":14,"verses":[18],"references":[{"surah":14,"verses":[18]}],"verseLabel":"إبراهيم: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿اشْتَدَّتْ بِهِ الرِّيحُ﴾ بالإفراد؟","answer":"يلائم الإفراد هنا صورة الريح الشديدة التي تذرو الرماد. ويذكر المصدر أن جمع الرياح يكثر في سياق الرحمة؛ وهذا فرق أغلبِيّ، لا قاعدة تمنع ورود قراءة «الرياح» في الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص696، تحت «الريح والرياح»","url":""}]},{"id":"s14-67","number":67,"surah":14,"verses":[18],"references":[{"surah":14,"verses":[18]}],"verseLabel":"إبراهيم: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَقْدِرُونَ مِمَّا كَسَبُوا عَلَى شَيْءٍ﴾، وفي البقرة: ﴿لَا يَقْدِرُونَ عَلَى شَيْءٍ مِمَّا كَسَبُوا﴾؟","answer":"في إبراهيم يدور المثل على أعمال الكافرين وما كسبوه بها، فقدم ﴿مما كسبوا﴾ اهتمامًا بالكسب. أما في البقرة فالسياق في إبطال الصدقة بالمن والأذى، فقدم نفي القدرة على أي شيء من ثمرتها ثم ذكر الكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص693–694، تحت «المتشابه اللفظي بين آيتي البقرة وإبراهيم»","url":""}]},{"id":"s14-68","number":68,"surah":14,"verses":[18],"references":[{"surah":14,"verses":[18]}],"verseLabel":"إبراهيم: 18","question":"ما دلالة تنكير ﴿شَيْءٍ﴾ في ﴿لَا يَقْدِرُونَ مِمَّا كَسَبُوا عَلَى شَيْءٍ﴾؟","answer":"يشمل النفي أدنى ما ينتفع به من العمل؛ فلا يقدرون على قليل ولا كثير من ثمراته، وفيه بيان ضياع ما كانوا يرجون.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص695، تحت «الغرض من تنكير شيء»","url":""}]},{"id":"s14-69","number":69,"surah":14,"verses":[19],"references":[{"surah":14,"verses":[19]}],"verseLabel":"إبراهيم: 19","question":"ما سرّ تقديم السماوات على الأرض في الاستدلال بالخلق؟","answer":"لأن خلق السماوات وما فيهن أعظم وأعجب، فناسب البدء بها في مقام الاستدلال على قدرة الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص702، تحت «نكتة تقديم السماوات على الأرض في السياق»","url":""}]},{"id":"s14-71","number":71,"surah":14,"verses":[19,20],"references":[{"surah":14,"verses":[19,20]}],"verseLabel":"إبراهيم: 19-20","question":"ما دلالة الخطاب في ﴿يذهبكم ويأت بخلق جديد﴾؟","answer":"يحول دليل الخلق إلى تهديد مباشر بالاستبدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص706، تحت «دلالة التعبير بضمير الخطاب في يذهبكم»","url":""}]},{"id":"s14-173","number":173,"surah":14,"verses":[19,20],"references":[{"surah":14,"verses":[19,20]}],"verseLabel":"إبراهيم: 19-20","question":"ما دلالة ﴿وما ذلك على الله بعزيز﴾؟","answer":"ينفي عن الإذهاب والإبدال كل صعوبة؛ فهو هين على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص709، تحت «دلالة العطف في قوله وما ذلك في السياق»","url":""}]},{"id":"s14-72","number":72,"surah":14,"verses":[20],"references":[{"surah":14,"verses":[20]}],"verseLabel":"إبراهيم: 20","question":"ما سرّ تقديم ﴿عَلَى اللَّهِ﴾ على ﴿بِعَزِيزٍ﴾؟","answer":"لإبراز تعلق نفي العجز بقدرة الله؛ فإذهابهم والإتيان بخلق جديد لا يصعب عليه، وهو تعريض بضعفهم أمام قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص710، تحت «سر تقديم على الله على بعزيز»","url":""}]},{"id":"s14-73","number":73,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَرَزُوا لِلَّهِ جَمِيعًا﴾ بالماضي؟","answer":"لتحقيق وقوع القيامة حتى كأنها حدثت وشوهدت.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص716–717، تحت «دلالة العدول إلى التعبير بالماضي في برزوا»","url":""}]},{"id":"s14-74","number":74,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قول الضعفاء: ﴿إِنَّا كُنَّا لَكُمْ تَبَعًا﴾ بالمصدر؟","answer":"على تفسير «تبعًا» بالمصدر، فيه مبالغة في شدة انقيادهم حتى كأنهم نفس التبعية؛ ويحتمل اللفظ أيضًا أن يكون جمعًا لتابع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص722–723، تحت «دلالة التعبير بلفظ تبعًا دون تابعين»","url":""}]},{"id":"s14-75","number":75,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما دلالة الفاء في قوله تعالى: ﴿فَقَالَ الضُّعَفَاءُ﴾ بعد ﴿وَبَرَزُوا لِلَّهِ جَمِيعًا﴾؟","answer":"تصل مشهد البروز بمواجهة الأتباع لقادتهم؛ فما إن يظهروا للحساب حتى يحتج الضعفاء بتبعيتهم، فينكشف عجز من اتبعوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص719، تحت «دلالة الفاء في جملة فقال الضعفاء»","url":""}]},{"id":"s14-76","number":76,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قول المستكبرين: ﴿لَهَدَيْنَاكُمْ﴾ مع نسبة الهداية إلى أنفسهم؟","answer":"من تفسير الكلام: لو أرشدنا الله إلى طريق النجاة من العذاب لأرشدناكم. وإسناد هدايتهم إلى أنفسهم يصور بقاء نزعة التسلط؛ فكأن الأتباع لا يزالون تابعين لهم حتى في طلب الخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص730، تحت «نكتة لهديناكم بدل إسنادها لله تعالى لهداكم»","url":""}]},{"id":"s14-77","number":77,"surah":14,"verses":[21],"references":[{"surah":14,"verses":[21]}],"verseLabel":"إبراهيم: 21","question":"ما دلالة تقديم ﴿سَوَاءٌ﴾ في قولهم: ﴿سَوَاءٌ عَلَيْنَا أَجَزِعْنَا أَمْ صَبَرْنَا﴾؟","answer":"لتأكيد اليأس من النجاة قبل ذكر الجزع والصبر؛ فكلاهما لا يغير مصيرهم، وفيه تيئيس للأتباع الذين رجوا من قادتهم الإغاثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص731، تحت «الغرض من تقديم الخبر سواء في السياق»","url":""}]},{"id":"s14-78","number":78,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما سرّ التعبير في قول الشيطان: ﴿لَمَّا قُضِيَ الْأَمْرُ﴾ بالبناء للمفعول؟","answer":"لأن القاضي هو الله، وحذف ذكره يصور تفرده بالحكم وعدم وجود شريك له؛ وينصب الاهتمام على نفاذ القضاء وانتهاء الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص743، تحت «دلالة التعبير بالفعل المبني للمفعول قضي»","url":""}]},{"id":"s14-79","number":79,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما دلالة المقابلة بين ﴿وَعَدَكُمْ وَعْدَ الْحَقِّ﴾ و﴿وَوَعَدْتُكُمْ فَأَخْلَفْتُكُمْ﴾؟","answer":"وصف وعد الله بالحق يقرر صدقه وتحققه، والتصريح بإخلاف الشيطان يكشف كذب وعده. ويُفهم من الجملتين وفاء الله بوعده وبطلان ما أغراهم به الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص750، تحت «بلاغة الاحتباك في السياق المحكم»","url":""}]},{"id":"s14-80","number":80,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا تَلُومُونِي وَلُومُوا أَنْفُسَكُمْ﴾؟","answer":"يفرع اللوم على استجابتهم له باختيارهم؛ فقد دعاهم ولم يجبرهم، فاختاروا وسوسته مع قيام الحجج. والكلام لا ينفي استحقاق الشيطان للوم، بل يبين مسؤوليتهم عن اتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص756، تحت «الغرض من التعبير بفعل الأمر ولوموا»","url":""}]},{"id":"s14-81","number":81,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما سرّ تقديم ﴿مَا أَنَا بِمُصْرِخِكُمْ﴾ على ﴿وَمَا أَنْتُمْ بِمُصْرِخِيَّ﴾؟","answer":"بدأ بعجزه عن إنقاذهم لأنه ما تعلق به رجاؤهم، ثم نفى قدرتهم على إنقاذه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص760، تحت «نكتة تقديم نفي إغاثته على نفي إغاثتهم»","url":""}]},{"id":"s14-82","number":82,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما دلالة التوكيد في ﴿إن الظالمين لهم عذاب أليم﴾؟","answer":"يؤكد ثبوت العذاب وانقطاع الطمع في النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص764، تحت «سر التوكيد بإن واسمية الجملة»","url":""}]},{"id":"s14-174","number":174,"surah":14,"verses":[22],"references":[{"surah":14,"verses":[22]}],"verseLabel":"إبراهيم: 22","question":"ما دلالة تقديم ﴿لهم﴾؟","answer":"يبرز اختصاص الظالمين بالعذاب واستحقاقهم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص765، تحت «سر تقديم الخبر لهم على المبتدأ عذاب»","url":""}]},{"id":"s14-85","number":85,"surah":14,"verses":[23],"references":[{"surah":14,"verses":[23]}],"verseLabel":"إبراهيم: 23","question":"ما سرّ تقديم ﴿فِيهَا﴾ على ﴿سَلَامٌ﴾ في قوله: ﴿تَحِيَّتُهُمْ فِيهَا سَلَامٌ﴾؟","answer":"للاهتمام بالسلام الذي يلقاه أهل الجنة فيها، وإبراز خصوصية تلك الدار بسلامها الكامل؛ فالاهتمام منصب على ما ينتظرهم من نعيم وأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص776، تحت «سر تقديم فيها على خبر المبتدأ»","url":""}]},{"id":"s14-86","number":86,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"إلى من يتوجه الخطاب في ﴿ألم تر﴾؟","answer":"إلى الرسول ﷺ، ويدخل فيه كل من يصلح للتأمل والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص783، تحت «المقصود بالخطاب في جملة ألم تر»","url":""}]},{"id":"s14-175","number":175,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما دلالة الاستفهام بـ﴿كيف﴾؟","answer":"يوجه النظر إلى هيئة المثل العجيبة وطريقة تصويره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص783، تحت «سر الاستفهام بالأداة كيف»","url":""}]},{"id":"s14-87","number":87,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿ضَرَبَ اللَّهُ مَثَلًا﴾ وذكر اسم الجلالة؟","answer":"إسناد ضرب المثل إلى اسم الله يعظم شأنه؛ فهو صادر عمن له كمال العلم، فيدعو إلى تلقيه بالتدبر واليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص784، تحت «سر التعبير باسم الجلالة الله مسندًا إليه»","url":""}]},{"id":"s14-88","number":88,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما دلالة وصف ﴿كَلِمَةً﴾ بأنها ﴿طَيِّبَةً﴾؟","answer":"يشير الوصف إلى الكلمة التي تستقيم بها النفس ويظهر خيرها؛ وفي مقدمتها كلمة التوحيد، بما يترتب عليها من إيمان راسخ وعمل صالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص786، تحت «الغرض من وصف الكلمة بوصف طيبة»","url":""}]},{"id":"s14-89","number":89,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما دلالة تشبيه الكلمة الطيبة بشجرة؟","answer":"تجمع الشجرة أصلًا راسخًا وفروعًا عالية وثمرًا نافعًا؛ فيقرب هذا المشهد معنى الإيمان الثابت وما يثمره من قول طيب وعمل صالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص788، تحت «بلاغة التشبيه التمثيلي في السياق»","url":""}]},{"id":"s14-90","number":90,"surah":14,"verses":[24],"references":[{"surah":14,"verses":[24]}],"verseLabel":"إبراهيم: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَاءِ﴾؟","answer":"ثبات الأصل يصور رسوخ الإيمان في القلب، وارتفاع الفرع يصور سمو الكلمة الطيبة وخيراتها؛ فجمع المثل بين الثبات والعلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص790، تحت «سر تقديم جملة أصلها ثابت على وفرعها في السماء»","url":""}]},{"id":"s14-91","number":91,"surah":14,"verses":[25],"references":[{"surah":14,"verses":[25]}],"verseLabel":"إبراهيم: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿تُؤْتِي أُكُلَهَا كُلَّ حِينٍ﴾ لا ثمرها؟","answer":"الأُكُل هو ما يؤكل من الثمر، فهو أخص منه ويصرح بصلاحه للانتفاع؛ وهذا أنسب بصورة الشجرة الطيبة كاملة النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص802–803، تحت «أكلها وثمرها»","url":""}]},{"id":"s14-92","number":92,"surah":14,"verses":[25],"references":[{"surah":14,"verses":[25]}],"verseLabel":"إبراهيم: 25","question":"ما دلالة القيد ﴿بإذن﴾ في إثمار الشجرة؟","answer":"يبين أن استمرار إثمارها لا يكون إلا بتقدير خالقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص798، تحت «دلالة القيد بشبه الجملة بإذن»","url":""}]},{"id":"s14-176","number":176,"surah":14,"verses":[25],"references":[{"surah":14,"verses":[25]}],"verseLabel":"إبراهيم: 25","question":"ما سر الإضافة في ﴿بإذن ربها﴾؟","answer":"تذكر برعاية الله للشجرة وتدبيره لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص798، تحت «سر الإضافة إلى الربوبية»","url":""}]},{"id":"s14-93","number":93,"surah":14,"verses":[26],"references":[{"surah":14,"verses":[26]}],"verseLabel":"إبراهيم: 26","question":"ما دلالة وصف الشجرة الخبيثة بـ﴿اجْتُثَّتْ مِنْ فَوْقِ الْأَرْضِ﴾؟","answer":"تصورها مقتَلعة لا جذور راسخة لها؛ فيقابل ذلك ثبات الشجرة الطيبة، ويمثل افتقار الكلمة الخبيثة إلى الحجة والثبات والنفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص16، تحت «سر تقييد الاجتثاث من فوق الأرض»","url":""}]},{"id":"s14-94","number":94,"surah":14,"verses":[26],"references":[{"surah":14,"verses":[26]}],"verseLabel":"إبراهيم: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا لَهَا مِنْ قَرَارٍ﴾؟","answer":"الجملة الاسمية والنكرة في سياق النفي، مع «من» المؤكدة للاستغراق، تنفي عنها كل ثبات؛ فتلائم صورة الكلمة الخبيثة التي لا حجة لها ولا رسوخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص17، تحت «دلالة حرف الجر في من قرار»","url":""}]},{"id":"s14-95","number":95,"surah":14,"verses":[27],"references":[{"surah":14,"verses":[27]}],"verseLabel":"إبراهيم: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ﴾؟","answer":"بعد تمثيل الكلمة الطيبة بالشجرة الراسخة، يبين أن الله يثبت أهل الإيمان بالقول الحق في الدنيا والآخرة؛ فيتصل ثبات الكلمة بثبات أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص21، تحت «دلالة الاستئناف في الآية»","url":""}]},{"id":"s14-96","number":96,"surah":14,"verses":[27],"references":[{"surah":14,"verses":[27]}],"verseLabel":"إبراهيم: 27","question":"ما سر الجناس بين ﴿يُثَبِّتُ﴾ و﴿الثَّابِتِ﴾؟","answer":"اشتُق وصف ﴿الثابت﴾ من مادة الفعل ﴿يثبت﴾؛ للإشارة إلى توفيق الله للمؤمنين وتثبيته إياهم بالقول الثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص23، تحت «نكتة الجناس في يثبت والثابت»","url":""}]},{"id":"s14-97","number":97,"surah":14,"verses":[28],"references":[{"surah":14,"verses":[28]}],"verseLabel":"إبراهيم: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿بَدَّلُوا نِعْمَتَ اللَّهِ كُفْرًا﴾؟","answer":"صور مقابلة النعمة بالكفر بالتبديل: جعلوا الكفر موضع الشكر الذي تقتضيه نعمة الله، وفي ذلك تقبيح لجحودهم وسوء اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص32–33، تحت «غرض الاستعارة في الفعل بدلوا»","url":""}]},{"id":"s14-98","number":98,"surah":14,"verses":[29],"references":[{"surah":14,"verses":[29]}],"verseLabel":"إبراهيم: 29","question":"ما سرّ تقديم ﴿جَهَنَّمَ﴾ في ﴿جَهَنَّمَ يَصْلَوْنَهَا﴾؟","answer":"لتعجيل بيان المصير وتهويله؛ فبعد ذكر ﴿دار البوار﴾ يأتي اسم جهنم كاشفًا عن ذلك الهلاك ومفزعًا للسامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص40، تحت «غرض تقديم المفعول به جهنم»","url":""}]},{"id":"s14-99","number":99,"surah":14,"verses":[30],"references":[{"surah":14,"verses":[30]}],"verseLabel":"إبراهيم: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿جَعَلُوا لِلَّهِ أَنْدَادًا﴾ وقدّم ﴿لله﴾؟","answer":"لتعجيل الإنكار وتفظيع الشرك؛ فقد جعلوا الأنداد لله الذي يعلمون أنه خالقهم ورازقهم، فاشتد تقبيح صنيعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص45، تحت «غرض تقديم لله على أندادًا»","url":""}]},{"id":"s14-100","number":100,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"ما دلالة التعبير عن الأمر بـ﴿يُقِيمُوا الصَّلَاةَ وَيُنْفِقُوا﴾ بصيغة المضارع؟","answer":"للدلالة على تجدد الإقامة والإنفاق واستمرارهما، لا أداء مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص54–55، تحت «نكتة الأمر بالمضارع يقيموا وينفقوا»","url":""}]},{"id":"s14-101","number":101,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"لماذا حُذفت لام الأمر قبل ﴿يُقِيمُوا﴾؟","answer":"على توجيه المضارع بالأمر المقدر، الأصل «ليقيموا»، فحذفت لام الأمر تخفيفًا لدلالة السياق عليها؛ واستعمال المضارع يفيد طلب دوام الفعل وتجديده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص54–55، تحت «نكتة الأمر بالمضارع يقيموا وينفقوا»","url":""}]},{"id":"s14-103","number":103,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لَا بَيْعٌ فِيهِ وَلَا خِلَالٌ﴾؟","answer":"ينبه نفي البيع والخلال إلى انقطاع وسائل التدارك الدنيوية؛ فلا بيع ولا صداقة تتيح تعويض العمل الفائت. وفي ذلك حث على المبادرة بالصلاة والإنفاق قبل مجيء ذلك اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص58، تحت «غرض التعبير بالكناية في نفي البيع والخلال»","url":""}]},{"id":"s14-104","number":104,"surah":14,"verses":[32],"references":[{"surah":14,"verses":[32]}],"verseLabel":"إبراهيم: 32","question":"ما سرّ تقديم ﴿مِنَ السَّمَاءِ﴾ على ﴿مَاءً﴾؟","answer":"للاهتمام بجهة نزول الماء وإبراز المنة بها، ولتشويق السامع إلى ما أنزل منها قبل التصريح بالماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص65، تحت «غرض تقديم من السماء على ماء»","url":""}]},{"id":"s14-105","number":105,"surah":14,"verses":[32],"references":[{"surah":14,"verses":[32]}],"verseLabel":"إبراهيم: 32","question":"ما دلالة جمع ﴿الثَّمَرَاتِ﴾ وتعريفها؟","answer":"الجمع يستحضر كثرة الثمار وتنوعها في مقام الامتنان، والتعريف يشير إلى الثمار المعهودة التي يعرف المخاطبون نفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص66، تحت «دلالة الجمع والتعريف الثمرات»","url":""}]},{"id":"s14-106","number":106,"surah":14,"verses":[32],"references":[{"surah":14,"verses":[32]}],"verseLabel":"إبراهيم: 32","question":"ما سرّ تقديم ﴿لَكُمُ﴾ على الفلك والأنهار؟","answer":"للاهتمام بأن تسخير الفلك والأنهار لنفع المخاطبين، وتعجيل تذكيرهم بالنعمة قبل ذكر ما سخر لهم؛ فيقوى الامتنان والتشويق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص68، تحت «غرض تقديم لكم على الفلك»","url":""}]},{"id":"s14-107","number":107,"surah":14,"verses":[32],"references":[{"surah":14,"verses":[32]}],"verseLabel":"إبراهيم: 32","question":"ما سرّ جمع ﴿الْأَنْهَارَ﴾ وإفراد ﴿الْبَحْرِ﴾ في الآية؟","answer":"جُمعت الأنهار لاستحضار كثرتها وتفرقها في البلاد، وأفرد البحر لأن المراد جنسه؛ فالتسخير يشمل البحر الذي تجري فيه الفلك دون اختصاص ببحر معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص71، تحت «علة الجمع الأنهار وإفراد البحر»","url":""}]},{"id":"s14-108","number":108,"surah":14,"verses":[33],"references":[{"surah":14,"verses":[33]}],"verseLabel":"إبراهيم: 33","question":"ما سرّ تقديم ﴿لَكُمُ﴾ قبل الشمس والقمر؟","answer":"للاهتمام بالمخاطبين بوصفهم المنتفعين بهذه النعمة، وتعجيل الامتنان عليهم؛ ثم يأتي ذكر الشمس والقمر بعد تشويق النفس إليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص73، تحت «غرض تقديم لكم على الشمس»","url":""}]},{"id":"s14-109","number":109,"surah":14,"verses":[33],"references":[{"surah":14,"verses":[33]}],"verseLabel":"إبراهيم: 33","question":"ما دلالة الجمع بين الشمس والقمر والليل والنهار في تعداد النعم؟","answer":"يبين تكامل النعم مع اختلافها؛ فالشمس والقمر والليل والنهار تجتمع آثارها في الضوء والسكون والحركة وسائر مصالح الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص75، تحت «نكتة جمع الأضداد»","url":""}]},{"id":"s14-110","number":110,"surah":14,"verses":[33],"references":[{"surah":14,"verses":[33]},{"surah":16,"verses":[12]}],"verseLabel":"إبراهيم: 33؛ النحل: 12","question":"ما نكتة تقديم الليل على النهار في إبراهيم؟","answer":"يراعى سبقه في الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص75، تحت «نكتة الترتيب في الليل والنهار»","url":""}]},{"id":"s14-177","number":177,"surah":14,"verses":[33],"references":[{"surah":14,"verses":[33]},{"surah":16,"verses":[12]}],"verseLabel":"إبراهيم: 33؛ النحل: 12","question":"ما بلاغة ترتيب الليل والنهار والشمس والقمر في النحل؟","answer":"يراعي قرب النعم وظهور الانتفاع بها؛ فالليل للسكن والنهار للحركة ثم الشمس والقمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص156، تحت «بلاغة الترتيب بين النعم في الآية»","url":""}]},{"id":"s14-111","number":111,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما وجه الجمع بين ﴿من﴾ و﴿كل﴾ في ﴿من كل ما سألتموه﴾؟","answer":"تفيد ﴿من﴾ أنه آتاهم من مطلوباتهم ما تقتضيه حكمته، مع شمول ﴿كل﴾ لأجناسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص79، تحت «وجه الجمع بين من وكل»","url":""}]},{"id":"s14-178","number":178,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما دلالة ﴿ما﴾ وإضافة ﴿كل﴾ إليها؟","answer":"تشمل ما سألوه نطقا وما دل عليه احتياجهم مما تقوم به حياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص80، تحت «دلالة ما وإضافة كل إليها»","url":""}]},{"id":"s14-112","number":112,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ تَعُدُّوا نِعْمَتَ اللَّهِ﴾ بالإفراد؟","answer":"النعمة في معنى المصدر، فيؤدي المفرد معنى الجنس دون حاجة إلى جمعه. وفي إفراده تنبيه إلى أن النعمة الواحدة قد تنطوي على نعم كثيرة لا تحصى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص82، تحت «نكتة إفراد نعمت»","url":""}]},{"id":"s14-113","number":113,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما دلالة ختام تعداد النعم بـ﴿إِنَّ الْإِنْسَانَ لَظَلُومٌ كَفَّارٌ﴾؟","answer":"يكشف عن ظلم الإنسان لنفسه حين يغفل شكر المنعم، ومبالغته في كفران نعمه؛ فصيغة «ظلوم» و«كفار» تؤكدان شدة الجحود في مقابل كثرة الإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص85، تحت «دلالة صيغة كفار وسر مجيئها بعد لظلوم»","url":""}]},{"id":"s14-115","number":115,"surah":14,"verses":[35],"references":[{"surah":14,"verses":[35]}],"verseLabel":"إبراهيم: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاجْنُبْنِي وَبَنِيَّ أَنْ نَعْبُدَ الْأَصْنَامَ﴾؟","answer":"طلب الإبعاد التام عن عبادة الأصنام وما يتصل بها؛ فلفظ الاجتناب يصور جعل الإنسان وعبادتها في جانبين متباعدين، تحقيقًا للإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص92، تحت «إيثار استعمال لفظ واجنبني»","url":""}]},{"id":"s14-116","number":116,"surah":14,"verses":[36],"references":[{"surah":14,"verses":[36]}],"verseLabel":"إبراهيم: 36","question":"لماذا قيل: ﴿فمن تبعني﴾؟","answer":"الاتباع اقتداء بإبراهيم في التوحيد والسير على ملته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص100، تحت «إيثار لفظ تبعني دون غيره»","url":""}]},{"id":"s14-179","number":179,"surah":14,"verses":[36],"references":[{"surah":14,"verses":[36]}],"verseLabel":"إبراهيم: 36","question":"ما دلالة ﴿فإنه مني﴾؟","answer":"تصور شدة اتصال التابع به في الدين وأن رابطة الإيمان هي المقصودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص100، تحت «سر الإخبار بالجار والمجرور مني»","url":""}]},{"id":"s14-117","number":117,"surah":14,"verses":[36],"references":[{"surah":14,"verses":[36]}],"verseLabel":"إبراهيم: 36","question":"ما دلالة قوله: ﴿وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ﴾ بدل الدعاء عليه بالعقوبة؟","answer":"يفوض أمر من عصاه إلى الله، ويتلطف في الدعاء بذكر مغفرته ورحمته؛ وفي ذلك أدب ورجاء من إبراهيم، مع ترك الحكم لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص102، تحت «بيان مناسبة فاصلة الآية لسياقها»","url":""}]},{"id":"s14-118","number":118,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما دلالة تكرار ﴿ربنا﴾؟","answer":"يجدد الالتجاء والتضرع عند كل مطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص106، تحت «موقع إني أسكنت وسر افتتاحها بالنداء وتكرره»","url":""}]},{"id":"s14-180","number":180,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما بلاغة حذف حرف النداء؟","answer":"يصور قرب المدعو وعلمه بحال الداعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص107، تحت «بلاغة حذف حرف النداء»","url":""}]},{"id":"s14-119","number":119,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿بِوَادٍ﴾ لا بمكان؟","answer":"لأن اللفظ يحدد طبيعة الموضع الذي أسكن فيه ذريته: فضاء منخفض بين جبال تجري به السيول؛ فهو أدق تصويرًا من لفظ المكان العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص109، تحت «إيثار الوادي دون غيره من المرادفات»","url":""}]},{"id":"s14-120","number":120,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"لماذا وصف البيت بـ﴿الْمُحَرَّمِ﴾ لا الحرام؟","answer":"صيغة «المحرَّم» تدل على أن الله جعل للبيت حرمة ومنع التعرض له؛ فتبرز فعل التحريم وحماية البيت، مع ما يدل عليه السياق من عظمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص111، تحت «إيثار صيغة المفعول المحرم»","url":""}]},{"id":"s14-121","number":121,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيُقِيمُوا الصَّلَاةَ﴾ فجعلها غاية الإسكان؟","answer":"اللام للتعليل؛ أي إن علة إسكانهم بهذا الوادي أن يقيموا الصلاة، فدلّ على أن العبادة هي مقصد الإسكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص112، تحت «البلاغة في قوله ليقيموا الصلاة»","url":""}]},{"id":"s14-122","number":122,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"لماذا استعمل لفظ ﴿أفئدة﴾؟","answer":"يستحضر القلوب المتقدة شوقا، فيناسب قوة الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص113، تحت «سر استعمال أفئدة»","url":""}]},{"id":"s14-181","number":181,"surah":14,"verses":[37],"references":[{"surah":14,"verses":[37]}],"verseLabel":"إبراهيم: 37","question":"ما بلاغة الاستعارة في ﴿تهوي إليهم﴾؟","answer":"تصور شدة اندفاع القلوب إليهم بالحب والرغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص113، تحت «بلاغة الاستعارة التصريحية تهوي»","url":""}]},{"id":"s14-123","number":123,"surah":14,"verses":[38],"references":[{"surah":14,"verses":[38]}],"verseLabel":"إبراهيم: 38","question":"ما سرّ تقديم ﴿مَا نُخْفِي﴾ على ﴿وَمَا نُعْلِنُ﴾؟","answer":"لأن الخفي أدق وأغمض، فذكر العلم به يبرز إحاطة علم الله؛ وكثير مما يعلن يسبقه خفاء، والله يعلمه في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص123، تحت «نكتة تقديم ما نخفي على وما نعلن»","url":""}]},{"id":"s14-124","number":124,"surah":14,"verses":[38],"references":[{"surah":14,"verses":[38]}],"verseLabel":"إبراهيم: 38","question":"لماذا استعمل المضارع ﴿تَعْلَمُ﴾؟","answer":"للدلالة على استمرار علم الله وإحاطته بكل شيء، فلا ينقطع علمه بما يخفيه الناس وما يعلنونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص122، تحت «إيثار صيغة المضارع تعلم»","url":""}]},{"id":"s14-125","number":125,"surah":14,"verses":[39],"references":[{"surah":14,"verses":[39]}],"verseLabel":"إبراهيم: 39","question":"لماذا قال: ﴿وهب لي﴾ لا أعطاني؟","answer":"الهبة عطاء بلا عوض فتبرز محض فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص131، تحت «إيثار استعمال لفظ وهب دون غيره»","url":""}]},{"id":"s14-182","number":182,"surah":14,"verses":[39],"references":[{"surah":14,"verses":[39]}],"verseLabel":"إبراهيم: 39","question":"ما نكتة ذكر الكبر؟","answer":"يعظم النعمة لأنها جاءت في سن لا تجري فيها عادة الولادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص133، تحت «نكتة ذكر حال الكبر»","url":""}]},{"id":"s14-126","number":126,"surah":14,"verses":[39],"references":[{"surah":14,"verses":[39]}],"verseLabel":"إبراهيم: 39","question":"ما دلالة الجمع بين إسماعيل وإسحاق في هذا الحمد؟","answer":"يجمع النعمتين اللتين وهبهما الله لإبراهيم على كبر، إظهارًا لامتنانه وسروره بما قرت به عينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص132، تحت «نكتة الجمع بين إسماعيل وإسحاق»","url":""}]},{"id":"s14-127","number":127,"surah":14,"verses":[40],"references":[{"surah":14,"verses":[40]}],"verseLabel":"إبراهيم: 40","question":"ما سرّ التعبير بـ﴿مُقِيمَ الصَّلَاةِ﴾ في دعاء إبراهيم؟","answer":"اسم الفاعل «مقيم» يطلب رسوخ الصفة ودوامها؛ فهو يسأل أن يكون محافظًا على الصلاة قائمًا بها على وجهها، لا أن يقع منه فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص137–138، تحت «نكتة التعبير بمقيم دون الفعل»","url":""}]},{"id":"s14-128","number":128,"surah":14,"verses":[40],"references":[{"surah":14,"verses":[40]}],"verseLabel":"إبراهيم: 40","question":"ما دلالة الانتقال من ﴿رَبِّ﴾ إلى ﴿رَبَّنَا﴾؟","answer":"بدأ متكلمًا عن نفسه وهو يدعو له ولذريته، ثم جمع في ﴿ربنا﴾ مراعيًا من تبعه من ذريته؛ فكأنه يجمعهم معه في سؤال قبول الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص138، تحت «سر العدول عن المفرد في ربنا»","url":""}]},{"id":"s14-129","number":129,"surah":14,"verses":[40],"references":[{"surah":14,"verses":[40]}],"verseLabel":"إبراهيم: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَقَبَّلْ دُعَاءِ﴾ لا اقبل؟","answer":"صيغة التفعّل تفيد المبالغة في سؤال القبول والعناية بالدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص139، تحت «لطيفة إيثار صيغة التفعل وتقبل»","url":""}]},{"id":"s14-130","number":130,"surah":14,"verses":[41],"references":[{"surah":14,"verses":[41]}],"verseLabel":"إبراهيم: 41","question":"ما دلالة جمع إبراهيم نفسه ووالديه والمؤمنين في دعاء المغفرة؟","answer":"بدأ بنفسه ثم والديه ثم عمم المؤمنين؛ فجمع بين العناية بالأقربين والحرص على شمول الدعاء لأهل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص142–143، تحت «فائدة تخصيص القيود»","url":""}]},{"id":"s14-131","number":131,"surah":14,"verses":[42],"references":[{"surah":14,"verses":[42]}],"verseLabel":"إبراهيم: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا﴾ مع أن المؤمن لا يظن ذلك؟","answer":"النهي تثبيت للرسول ووعيد للظالمين؛ تأخر العقوبة ليس غفلة بل إمهال إلى يوم معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص146، تحت «بلاغة الكناية في النهي بلا تحسبن»","url":""}]},{"id":"s14-132","number":132,"surah":14,"verses":[42],"references":[{"surah":14,"verses":[42]}],"verseLabel":"إبراهيم: 42","question":"ما سرّ التعبير بقوله تعالى: ﴿عَمَّا يَعْمَلُ الظَّالِمُونَ﴾ بالمضارع؟","answer":"تصور صيغة المضارع تجدد ظلمهم واستمرارهم فيه؛ فيتوجه الوعيد إلى ما يواصلون ارتكابه من الكفر والاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص149، تحت «سر إيثار صيغة المضارع يعمل»","url":""}]},{"id":"s14-133","number":133,"surah":14,"verses":[42],"references":[{"surah":14,"verses":[42]}],"verseLabel":"إبراهيم: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿تَشْخَصُ فِيهِ الْأَبْصَارُ﴾؟","answer":"يصوّر اللفظ الأبصار مفتوحة ثابتة لا تطرف من شدة الفزع، فتجتمع فيه دلالة النظر المذهول والجمود أمام الهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص150–151، تحت «إيثار التعبير بتشخص»","url":""}]},{"id":"s14-134","number":134,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"ما دلالة وصفهم بـ﴿مهطعين﴾؟","answer":"يصور إسراعهم إلى الحساب في ذل وخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص157، تحت «إيثار لفظ مهطعين»","url":""}]},{"id":"s14-183","number":183,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"ما دلالة ﴿مقنعي رؤوسهم﴾؟","answer":"يصور رؤوسا مرفوعة وعيونا شاخصة من الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص158، تحت «إيثار الوصف الفريد مقنعي ودلالته»","url":""}]},{"id":"s14-135","number":135,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"ما سرّ إفراد ﴿طَرْفُهُمْ﴾ مع تعدد أصحابه؟","answer":"يشير الإفراد إلى تشابه حال أبصارهم في الجمود والشخوص، حتى كأنها طرف واحد؛ واسم الجنس المفرد يناسب هذا العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص160، تحت «نكتة إفراد طرفهم والعدول عن الجمع»","url":""}]},{"id":"s14-136","number":136,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"لماذا عبر بالفؤاد لا القلب؟","answer":"يستحضر موضع الشعور والتوقد فيبرز شدة الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص161، تحت «إيثار استعمال لفظ الفؤاد دون القلب»","url":""}]},{"id":"s14-184","number":184,"surah":14,"verses":[43],"references":[{"surah":14,"verses":[43]}],"verseLabel":"إبراهيم: 43","question":"ما سر التشبيه في ﴿وأفئدتهم هواء﴾؟","answer":"يصور القلوب فارغة حائرة قد ذهب إدراكها من شدة الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص162، تحت «سر التشبيه البليغ للقلوب بالهواء»","url":""}]},{"id":"s14-137","number":137,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة إسناد الإتيان إلى العذاب في قوله: ﴿يَوْمَ يَأْتِيهِمُ الْعَذَابُ﴾؟","answer":"أُسند الإتيان إلى العذاب مجازًا بمعنى وقوعه عليهم؛ تهويلًا له وتفظيعًا، حتى كأنه يتحرك نحوهم بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص170–171، تحت «بلاغة المجاز العقلي في إسناد الإتيان إلى العذاب»","url":""}]},{"id":"s14-138","number":138,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما سرّ الاقتصار على ذكر العذاب دون الثواب في هذا الإنذار؟","answer":"لأن الخطاب إنذار للظالمين، فذكر ما يطابق المقام ويزلزل غفلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص170، تحت «فائدة الاقتصار بذكر إتيان العذاب دون الثواب»","url":""}]},{"id":"s14-139","number":139,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة صيغة المضارع في ﴿فَيَقُولُ الَّذِينَ ظَلَمُوا﴾؟","answer":"تستحضر مشهد تضرعهم، وتصور تكرر قولهم وإلحاحهم في طلب الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص171، تحت «فائدة التعبير بالفعل المضارع في فيقول»","url":""}]},{"id":"s14-140","number":140,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة وصف الأجل بـ﴿قَرِيبٍ﴾ في طلبهم الإمهال؟","answer":"القريب هنا بمعنى القليل؛ شُبّه قِصر الزمن بقرب المسافة، فهم يسألون مهلة قليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص174، تحت «دلالة الاستعارة في وصف الأجل بالقرب»","url":""}]},{"id":"s14-141","number":141,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة الجمع بين ﴿نُجِبْ دَعْوَتَكَ﴾ و﴿نَتَّبِعِ الرُّسُلَ﴾؟","answer":"إجابة الدعوة تشمل الإيمان والتوحيد، ثم خص اتباع الرسل بالذكر إظهارًا لكمال الانقياد واستدراكًا لتكذيبهم السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص174، تحت «فائدة العطف والتتميم في جملة ونتبع الرسل»","url":""}]},{"id":"s14-142","number":142,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿أَوَلَمْ تَكُونُوا أَقْسَمْتُمْ مِنْ قَبْلُ﴾؟","answer":"الاستفهام يقرر قسمهم السابق ويوبخهم عليه، وذكر الكون يستحضر رسوخهم في الغرور والإنكار؛ فيرد طلبهم بالإمهال بما شهدوا به على أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص175، تحت «سر الجواب بالاستفهام»","url":""}]},{"id":"s14-143","number":143,"surah":14,"verses":[44],"references":[{"surah":14,"verses":[44]}],"verseLabel":"إبراهيم: 44","question":"ما دلالة التنكير في ﴿مَا لَكُمْ مِنْ زَوَالٍ﴾؟","answer":"ينفي الزوال على سبيل العموم؛ أي إنهم كانوا ينكرون الانتقال إلى دار الحساب. وجاء تذكيرهم بهذا الزعم تقريرًا لغرورهم وتوبيخًا لهم.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 44] موسوعة التفسير البلاغي، ج25، ص178، تحت «معنى الزوال في هذا الموضع ونكتة تنكير لفظه»","url":""}]},{"id":"s14-144","number":144,"surah":14,"verses":[45],"references":[{"surah":14,"verses":[45]}],"verseLabel":"إبراهيم: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿وَسَكَنْتُمْ فِي مَسَاكِنِ الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ﴾؟","answer":"يجعل ديار الأمم الهالكة شاهدًا قريبًا على عاقبة الظلم؛ فقد عرفوا آثارهم ومروا بمساكنهم، ومع ذلك لم يعتبروا بما حل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص182، تحت «سر تعدية الفعل سكن بحرف الظرفية»","url":""}]},{"id":"s14-145","number":145,"surah":14,"verses":[45],"references":[{"surah":14,"verses":[45]}],"verseLabel":"إبراهيم: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿وَضَرَبْنَا لَكُمُ الْأَمْثَالَ﴾ وقدّم ﴿لكم﴾؟","answer":"للاهتمام بأن الأمثال سيقت لبيان الحجة لهم، ولتشويقهم إلى ما يذكر بعدها؛ وتكرار «لكم» يشدد التوبيخ على ترك الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص184، تحت «فائدة تقديم الجار والمجرور لكم»","url":""}]},{"id":"s14-146","number":146,"surah":14,"verses":[46],"references":[{"surah":14,"verses":[46]}],"verseLabel":"إبراهيم: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقَدْ مَكَرُوا مَكْرَهُمْ﴾؟","answer":"إضافة المكر إليهم تستوعب أقصى ما دبروه، ثم تضعه كله في علم الله وسلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص189، تحت «الموقع النحوي لمكرهم ونكتة الإسناد»","url":""}]},{"id":"s14-147","number":147,"surah":14,"verses":[46],"references":[{"surah":14,"verses":[46]}],"verseLabel":"إبراهيم: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ الْجِبَالُ﴾؟","answer":"يختلف التوجيه باختلاف القراءة والإعراب: فعلى النفي يصور عجز مكرهم عن إزالة ما ثبت من آيات الله، وعلى الإثبات يبالغ في تصوير شدته؛ وفي الحالين لا يعجز الله ولا يخرج عن سلطانه.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 46] موسوعة التفسير البلاغي، ج25، ص191–192، تحت «دلالة إن واللام وأثر دخولهما في الجملة؛ توجيه القراءات في لتزول»","url":""}]},{"id":"s14-148","number":148,"surah":14,"verses":[47],"references":[{"surah":14,"verses":[47]}],"verseLabel":"إبراهيم: 47","question":"ما سرّ تقديم ﴿وَعْدِهِ﴾ على ﴿رُسُلَهُ﴾ في قوله: ﴿فَلَا تَحْسَبَنَّ اللَّهَ مُخْلِفَ وَعْدِهِ رُسُلَهُ﴾؟","answer":"قدم الوعد للاهتمام بأنه لا يتخلف، ثم ذكر الرسل زيادة في التثبيت؛ فإذا كان الله لا يخلف وعده أصلًا فكيف بوعده رسله بالنصر؟","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص196، تحت «سر تقديم المفعول الثاني على الأول»","url":""}]},{"id":"s14-149","number":149,"surah":14,"verses":[47],"references":[{"surah":14,"verses":[47]}],"verseLabel":"إبراهيم: 47","question":"ما دلالة ختام الآية بـ﴿عَزِيزٌ ذُو انْتِقَامٍ﴾؟","answer":"العزة تؤكد أن قدرته لا تغلب، والانتقام يلائم وعيد المكذبين الظالمين ونصرة المظلومين؛ فيطمئن الرسل إلى تحقق الوعد.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 47] موسوعة التفسير البلاغي، ج25، ص198، تحت «إيثار صفة العزة والانتقام»","url":""}]},{"id":"s14-150","number":150,"surah":14,"verses":[48],"references":[{"surah":14,"verses":[48]}],"verseLabel":"إبراهيم: 48","question":"ما سرّ تقديم تبديل الأرض على تبديل السماوات؟","answer":"قُدّم تبديل الأرض لقربها منا، ولأن تبديلها أعظم أثرًا بالنسبة إلينا.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 48] موسوعة التفسير البلاغي، ج25، ص204، تحت «نكتة تقديم تبديل الأرض على تبديل السماوات»","url":""}]},{"id":"s14-151","number":151,"surah":14,"verses":[48],"references":[{"surah":14,"verses":[48]}],"verseLabel":"إبراهيم: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ﴾؟","answer":"«الواحد» يبطل تعلقهم بالشركاء الذين لا يملكون لهم شيئًا، و«القهار» يصور خضوعهم التام لسلطان الله؛ فيشتد التهديد ويظهر عجزهم عن دفع الحساب.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 48] موسوعة التفسير البلاغي، ج25، ص207، تحت «مناسبة صفتي الواحد القهار للسياق»","url":""}]},{"id":"s14-152","number":152,"surah":14,"verses":[49],"references":[{"surah":14,"verses":[49]}],"verseLabel":"إبراهيم: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَرَى الْمُجْرِمِينَ﴾ بالمضارع؟","answer":"لاستحضار المشهد حتى يراه المخاطب رأي العين.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 49] موسوعة التفسير البلاغي، ج25، ص213–214، تحت «نكتة التعبير بالفعل المضارع وترى»","url":""}]},{"id":"s14-153","number":153,"surah":14,"verses":[49],"references":[{"surah":14,"verses":[49]}],"verseLabel":"إبراهيم: 49","question":"ما دلالة وصفهم بـ﴿الْمُجْرِمِينَ﴾ في هذا المشهد؟","answer":"يستحضر ما اكتسبوه من جرائم في الاعتقاد والعمل، فيربط مشهد العقوبة بسببها، ويبين أنهم عوقبوا على جناياتهم.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 49] موسوعة التفسير البلاغي، ج25، ص214، تحت «إيثار وصف المجرمين دون الظالمين»","url":""}]},{"id":"s14-154","number":154,"surah":14,"verses":[49],"references":[{"surah":14,"verses":[49]}],"verseLabel":"إبراهيم: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿مُقَرَّنِينَ﴾ لا مقرونين؟","answer":"تضعيف الراء يدل على شدة قرنهم وإحكام وثاقهم وكثرته؛ فيصور ربط بعضهم ببعض أو بقرنائهم مع تضييق القيود عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص215، تحت «علة العدول عن مقرونين إلى مقرنين»","url":""}]},{"id":"s14-155","number":155,"surah":14,"verses":[49],"references":[{"surah":14,"verses":[49]}],"verseLabel":"إبراهيم: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الْأَصْفَادِ﴾؟","answer":"تصور الظرفية شدة إحاطة القيود بهم، كأن الأصفاد صارت ظرفًا يستغرق أجسادهم؛ فيبرز ضيق وثاقهم وقسوته.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 49] موسوعة التفسير البلاغي، ج25، ص215، تحت «فائدة قيد في الأصفاد»","url":""}]},{"id":"s14-156","number":156,"surah":14,"verses":[50],"references":[{"surah":14,"verses":[50]}],"verseLabel":"إبراهيم: 50","question":"ما دلالة المضارع في ﴿تغشى وجوههم النار﴾؟","answer":"يستحضر المشهد ويدل على استمرار الغشيان وتجدده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص217، تحت «فائدة استعمال صيغة المضارع وتغشى»","url":""}]},{"id":"s14-185","number":185,"surah":14,"verses":[50],"references":[{"surah":14,"verses":[50]}],"verseLabel":"إبراهيم: 50","question":"لماذا خصت الوجوه بالذكر؟","answer":"لإبراز إصابة أشرف مواضع الإنسان بالعذاب المهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص217، تحت «علة اختصاص الوجوه بالذكر»","url":""}]},{"id":"s14-157","number":157,"surah":14,"verses":[50],"references":[{"surah":14,"verses":[50]}],"verseLabel":"إبراهيم: 50","question":"ما سرّ تقديم ﴿وُجُوهَهُمُ﴾ على ﴿النار﴾؟","answer":"لأن الوجه أشرف ما في الإنسان، فذُكر وقُدّم تعجيلًا بإهانة المجرمين؛ وإهانته إهانة عظيمة لصاحبه.","sources":[{"label":"[الموضع الصحيح: إبراهيم: 50] موسوعة التفسير البلاغي، ج25، ص218، تحت «سر تقديم المفعول وتغشى وجوههم النار»","url":""}]},{"id":"s14-158","number":158,"surah":14,"verses":[51],"references":[{"surah":14,"verses":[51]}],"verseLabel":"إبراهيم: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيَجْزِيَ اللَّهُ كُلَّ نَفْسٍ مَا كَسَبَتْ﴾؟","answer":"عُبّر بأن الجزاء هو ما كسبته النفس، لا بأنه جزاء عملها؛ للإشارة إلى المساواة التامة بين العمل وجزائه، حتى كأن الجزاء هو العمل نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص224، تحت «إيثار استعمال الجزاء وإسناده إلى اسم الجلالة»","url":""}]},{"id":"s14-159","number":159,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿هَذَا بَلَاغٌ لِلنَّاسِ﴾ لا للمؤمنين؟","answer":"لأن القرآن حجة ورسالة عامة لكل الناس، وإن اختص أولو الألباب بكمال الاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص233، تحت «معنى لام التعريف ونوعها في الناس»","url":""}]},{"id":"s14-160","number":160,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما سرّ تقديم ﴿وَلِيُنْذَرُوا بِهِ﴾ قبل العلم بالوحدانية والتذكر؟","answer":"الإنذار يبعث على الخشية والنظر، ثم تهدي الدلائل إلى معرفة وحدانية الله، ويثمر التذكر اتعاظًا وعملًا؛ فالترتيب يبين تتابع آثار البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص236، تحت «سر ترتيب الصفات الواردة في الآية الكريمة»","url":""}]},{"id":"s14-161","number":161,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِيَعْلَمُوا أَنَّمَا هُوَ إِلَهٌ وَاحِدٌ﴾؟","answer":"أسلوب القصر يقرر وحدانية الله وينفي الشريك؛ فالعلم بهذه الحقيقة من مقاصد البلاغ والإنذار ودلائل القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص235، تحت «بلاغة القصر وليعلموا أنما هو إله واحد»","url":""}]},{"id":"s14-162","number":162,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"لماذا خص أولو الألباب بالتذكر؟","answer":"لأنهم ينتفعون بالمواعظ والحجج فيثمر علمهم عملا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص235، تحت «علة اختصاص أولي الألباب بالذكر وختم الآية بها»","url":""}]},{"id":"s14-186","number":186,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما علاقة خاتمة إبراهيم بأولها؟","answer":"تعود إلى مقصد الكتاب في أولها: إخراج الناس من الظلمات إلى النور.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص236، تحت «علاقة خاتمة السورة بأولها»","url":""}]},{"id":"s15-1","number":1,"surah":15,"verses":[1],"references":[{"surah":15,"verses":[1]}],"verseLabel":"الحجر: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ آيَاتُ الْكِتَابِ وَقُرْآنٍ مُبِينٍ﴾؟","answer":"جمع الوصفان بين كونه كتابًا مشتملًا على كمالات الكتب الإلهية، وقرآنًا مقروءًا متميزًا عنها؛ وفي وصفه بالكتاب أيضًا إشارة إلى أنه سيكتب ويحفظ، مع كونه متلوًّا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص263، تحت «نكتة تأخير وصف قرآن على وصف الكتاب»","url":""}]},{"id":"s15-2","number":2,"surah":15,"verses":[1],"references":[{"surah":15,"verses":[1]}],"verseLabel":"الحجر: 1","question":"ما دلالة إضافة ﴿آيَاتُ﴾ إلى ﴿الْكِتَابِ﴾؟","answer":"تحتمل الإضافة أن تكون بمعنى «من»، أي آيات من الكتاب، فيكون القرآن بعضه شبيهًا ببعض في البيان. ويجوز أن يراد وصف الآيات بصفات الكتاب كله، تعظيمًا لشأنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص262، تحت «سر الإضافة في قوله آيات الكتاب»","url":""}]},{"id":"s15-3","number":3,"surah":15,"verses":[1],"references":[{"surah":15,"verses":[1]}],"verseLabel":"الحجر: 1","question":"ما سرّ تأخير وصف ﴿قُرْآنٍ﴾ عن وصف ﴿الْكِتَابِ﴾؟","answer":"أُخّر وصف القرآنية لأنه أدخل في المدح وأرسخ في التعريف بهذا الوحي، بعد التنبيه أولًا على اشتماله على كمالات الكتب الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص263، تحت «نكتة تأخير وصف قرآن على وصف الكتاب»","url":""}]},{"id":"s15-4","number":4,"surah":15,"verses":[1],"references":[{"surah":15,"verses":[1]}],"verseLabel":"الحجر: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿مُبِينٍ﴾ وحذف ما يبينه؟","answer":"على تفسير «مبين» بمعنى مُظهِر، حُذف متعلقه ليفيد العموم: فهو يبيّن الحق والهدى، وسبل الضلال ليُتجنّب، وكل ما يحتاج الناس إلى بيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص264، تحت «فائدة حذف متعلق الوصف مبين»","url":""}]},{"id":"s15-5","number":5,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿رُبَمَا يَوَدُّ الَّذِينَ كَفَرُوا﴾ مع أن الندم محقق؟","answer":"ليس المراد الشك في الندم؛ ومن توجيهاته أن «ربما» للتقليل تهديدًا: لو وقع هذا التمني مرة واحدة لكفى باعثًا على الإيمان، فكيف وهو يتكرر؟ وقيل: هي هنا للتكثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص267، تحت «بلاغة التعبير بقوله ربما في السياق»","url":""}]},{"id":"s15-6","number":6,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير بالمضارع في ﴿يَوَدُّ﴾؟","answer":"يصور تجدد تمنيهم الإسلام كلما ظهرت لهم حقيقته، ويستحضر الأمر المستقبل كأنه واقع؛ تأكيدًا لتحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص268، تحت «فائدة التعبير بصيغة المضارع في قوله يود»","url":""}]},{"id":"s15-7","number":7,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ كَفَرُوا﴾ لا الكافرون؟","answer":"تُبيّن الصلة سبب ندامتهم؛ فكفرهم بالقرآن هو الذي أفضى إلى هذا التمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص268، تحت «بلاغة التعبير بالاسم الموصول الذين وصلته كفروا»","url":""}]},{"id":"s15-8","number":8,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما دلالة حذف متعلّق ﴿كَفَرُوا﴾؟","answer":"يُفهم من السياق كفرهم بالكتاب المنزل، وحذف المتعلق يجعل الكفر كالوصف اللازم لهم، وفيه تعظيم لشأن الإيمان وتهويل لعاقبة الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص269، تحت «نكتة حذف متعلق الفعل في قوله كفروا»","url":""}]},{"id":"s15-9","number":9,"surah":15,"verses":[2],"references":[{"surah":15,"verses":[2]}],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لَوْ كَانُوا مُسْلِمِينَ﴾ بصيغة الغيبة؟","answer":"حُكِي تمنيهم بضمير الغائب إظهارًا لحقارتهم وإهمال شأنهم، مع إبقاء السياق على نسق واحد في الإخبار عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص270، تحت «سبب إيثار التعبير بصيغة الغيبة لو كانوا»","url":""}]},{"id":"s15-10","number":10,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما دلالة الأمر في قوله تعالى: ﴿ذرهم﴾؟","answer":"الأمر للتهديد والوعيد؛ أي اتركهم فيما اختاروه حتى يلقوا عاقبة إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص273، تحت «بلاغة المجاز بالأمر في قوله ذرهم»","url":""}]},{"id":"s15-164","number":164,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما بلاغة التعريض في قوله تعالى: ﴿يأكلوا ويتمتعوا﴾؟","answer":"في الاقتصار على الأكل والمتاع تعريض بانحصار همهم في الشهوات وإعراضهم عن الإيمان والعمل للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص274، تحت «بلاغة التعريض في سياق الآية البليغ»","url":""}]},{"id":"s15-11","number":11,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما سرّ تقديم الضمير في ﴿وَيُلْهِهِمُ الْأَمَلُ﴾؟","answer":"تقدّم الضمير على الفاعل الظاهر لتأكيد استيلاء الأمل عليهم؛ وفيه قصر إضافي كأن الأمل لم يله أحدًا مثلهم، توبيخًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص276، تحت «فائدة تقديم المفعول الضمير على الفاعل الظاهر»","url":""}]},{"id":"s15-12","number":12,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما دلالة حذف ما يلهيهم عنه الأمل؟","answer":"يفيد الحذف عموم ما شغلهم عنه الأمل، من الإيمان والطاعة والخير؛ فلا ينحصر إلهاؤه في أمر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص276، تحت «سبب إيثار حذف متعلق الفعل ويلههم»","url":""}]},{"id":"s15-13","number":13,"surah":15,"verses":[3],"references":[{"surah":15,"verses":[3]}],"verseLabel":"الحجر: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَوْفَ يَعْلَمُونَ﴾ ولم يذكر ما يعلمون؟","answer":"حُذف المفعول للتهويل؛ فيُترك ما سيعلمونه من وبال وعاقبة مفتوحًا، فيشتد وقع التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص277، 278، تحت «مناسبة حذف متعلق الفعل يعلمون»","url":""}]},{"id":"s15-14","number":14,"surah":15,"verses":[4],"references":[{"surah":15,"verses":[4]}],"verseLabel":"الحجر: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أَهْلَكْنَا مِنْ قَرْيَةٍ﴾ لا من أهل قرية؟","answer":"ذكر القرية يُشعر بأن الإهلاك يتناول الناس وموضع اجتماعهم، فيصور الاستئصال وعظم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص282، تحت «نكتة التعبير بلفظ قرية في السياق»","url":""}]},{"id":"s15-15","number":15,"surah":15,"verses":[4],"references":[{"surah":15,"verses":[4]}],"verseLabel":"الحجر: 4","question":"ما دلالة ﴿مِنْ﴾ مع النكرة في ﴿مَا أَهْلَكْنَا مِنْ قَرْيَةٍ﴾؟","answer":"النكرة في سياق النفي تفيد العموم، وزيادة «من» تؤكد استغراقه: فما من قرية إلا ويجري إهلاكها وفق الأجل المعلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص281، تحت «دلالة مجيء من في قوله من قرية»","url":""}]},{"id":"s15-16","number":16,"surah":15,"verses":[4],"references":[{"surah":15,"verses":[4]}],"verseLabel":"الحجر: 4","question":"ما بلاغة الاستعارة في وصف أجل الأمة بأنه ﴿كتاب﴾؟","answer":"شُبّه الأجل المحدود بكتاب مضبوط لا يقبل زيادة ولا نقصًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص282، تحت «بلاغة الاستعارة في قوله كتاب»","url":""}]},{"id":"s15-165","number":165,"surah":15,"verses":[4],"references":[{"surah":15,"verses":[4]}],"verseLabel":"الحجر: 4","question":"ما دلالة وصف كتاب الأجل بأنه ﴿معلوم﴾؟","answer":"يؤكد أنه ثابت معلوم عند الله، فلا يُنسى ولا يتقدم ولا يتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص283، تحت «دلالة صفة الأجل في قوله معلوم»","url":""}]},{"id":"s15-17","number":17,"surah":15,"verses":[5],"references":[{"surah":15,"verses":[5]}],"verseLabel":"الحجر: 5","question":"ما سرّ إسناد السبق والاستئخار إلى ﴿أُمَّةٍ﴾ بعد ذكر ﴿قَرْيَةٍ﴾؟","answer":"إسناده إلى الأمة يبين أن جماعة الناس، مهما بلغت قوتها واجتماعها، لا تستطيع تقديم أجلها أو تأخيره؛ أما ذكر القرية قبل ذلك فيناسب تصوير الاستئصال الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص288، 289، تحت «نكتة الإسناد إلى الأمة دون القرية»","url":""}]},{"id":"s15-18","number":18,"surah":15,"verses":[5],"references":[{"surah":15,"verses":[5]}],"verseLabel":"الحجر: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَسْبِقُ... وَمَا يَسْتَأْخِرُونَ﴾ بالمضارع؟","answer":"صيغة المضارع تدل على دوام هذا الحكم في الأمم الماضية والباقية: لا تتجاوز أمة أجلها المقدر بتقديم أو تأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص289، 290، تحت «سر ورود صيغة المضارع تسبق ويستأخرون»","url":""}]},{"id":"s15-19","number":19,"surah":15,"verses":[5],"references":[{"surah":15,"verses":[5]}],"verseLabel":"الحجر: 5","question":"ما دلالة صيغة الاستفعال في ﴿يَسْتَأْخِرُونَ﴾؟","answer":"تصوّر الصيغة تعلق نفوسهم بطلب التأخير، ثم تنفي حصوله؛ فيشتد الزجر عما يوقعهم في العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص289، تحت «نكتة إيثار صيغة الاستفعال يستأخرون»","url":""}]},{"id":"s15-20","number":20,"surah":15,"verses":[6],"references":[{"surah":15,"verses":[6]}],"verseLabel":"الحجر: 6","question":"ما وجه قولهم ساخرين: ﴿يَا أَيُّهَا الَّذِي نُزِّلَ عَلَيْهِ الذِّكْرُ﴾؟","answer":"نادوه بالوصف الذي كانوا يجحدونه، ثم وصفوه بالجنون؛ فكان ذكر التنزيل حكاية لزعمه في اعتقادهم، على سبيل التهكم والاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص295، تحت «بلاغة التهكم على خلاف مقتضى الظاهر»","url":""}]},{"id":"s15-21","number":21,"surah":15,"verses":[6],"references":[{"surah":15,"verses":[6]}],"verseLabel":"الحجر: 6","question":"ما سرّ اختيارهم البناء للمفعول في قولهم: ﴿نُزِّلَ عَلَيْهِ﴾؟","answer":"حكاية كلامهم بالبناء للمفعول تُظهر إنكارهم أن يكون الذكر من عند الله، مع تركهم ذكر المنزِّل طعنًا في الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص295، تحت «سر إيثار التعبير بصيغة المبني للمفعول نزل»","url":""}]},{"id":"s15-22","number":22,"surah":15,"verses":[6],"references":[{"surah":15,"verses":[6]}],"verseLabel":"الحجر: 6","question":"ما دلالة تسمية القرآن ﴿الذِّكْرَ﴾ هنا؟","answer":"اختير وصف «الذكر» الجامع لما يذكّر به القرآن من الحق، وهو أيضًا كتاب يُتلى فيبقى ذكره متجددًا؛ فدل الوصف على حقيقة القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص296، تحت «نكتة التعبير بلفظ الذكر»","url":""}]},{"id":"s15-23","number":23,"surah":15,"verses":[6],"references":[{"surah":15,"verses":[6]}],"verseLabel":"الحجر: 6","question":"ما سرّ توالي التأكيد في قولهم: ﴿إِنَّكَ لَمَجْنُونٌ﴾؟","answer":"بالغوا في تأكيد اتهامهم ليظهروا الجزم به، مع علمهم بصدق الرسول؛ فهو إصرار على الباطل، وقد يُراد به تثبيت هذا الزعم عند الحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص297، 298، تحت «فائدة تتابع التأكيد في إنك لمجنون»","url":""}]},{"id":"s15-24","number":24,"surah":15,"verses":[7],"references":[{"surah":15,"verses":[7]}],"verseLabel":"الحجر: 7","question":"ما دلالة تخصيص الملائكة في طلبهم: ﴿لَوْ مَا تَأْتِينَا بِالْمَلَائِكَةِ﴾؟","answer":"طلبوا أن تأتي الملائكة لتشهد بنبوته وتصدق وعيده، أو لتعاقبهم إن كذبوه؛ وهو طلب عناد وتحدٍّ، لا طلب هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص301، تحت «نكتة إيثار ذكر الملائكة»","url":""}]},{"id":"s15-25","number":25,"surah":15,"verses":[7],"references":[{"surah":15,"verses":[7]}],"verseLabel":"الحجر: 7","question":"ما وجه قولهم: ﴿إِنْ كُنْتَ مِنَ الصَّادِقِينَ﴾ مع حذف المتعلق؟","answer":"حذف المتعلق يعم ما أخبر به الرسول من نبوته ونزول القرآن ووعيد المكذبين؛ فكأنهم يطالبونه بالملائكة شاهدًا على صدقه في ذلك كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص301، 302، تحت «سر حذف متعلق الاسم المشتق الصادقين»","url":""}]},{"id":"s15-26","number":26,"surah":15,"verses":[8],"references":[{"surah":15,"verses":[8]}],"verseLabel":"الحجر: 8","question":"لماذا جاء الجواب: ﴿مَا نُنَزِّلُ الْمَلَائِكَةَ إِلَّا بِالْحَقِّ﴾؟","answer":"رد الجواب على أصل اقتراحهم: إنزال الملائكة من أمر الله، ولا يكون إلا بالحق والحكمة، وليس تابعًا لتعنتهم أو اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص304، تحت «بلاغة الجواب في سياق الآية البليغ»","url":""}]},{"id":"s15-27","number":27,"surah":15,"verses":[8],"references":[{"surah":15,"verses":[8]}],"verseLabel":"الحجر: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿بِالْحَقِّ﴾؟","answer":"الباء للملابسة: لا ينفك تنزيل الملائكة عن الحق والحكمة. ومن تفسير الحق هنا الأمر الفاصل بالعذاب، وعندئذ لا يبقى للمكذبين إمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص306، تحت «دلالة لفظ بالحق في السياق»","url":""}]},{"id":"s15-28","number":28,"surah":15,"verses":[8],"references":[{"surah":15,"verses":[8]}],"verseLabel":"الحجر: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا كَانُوا إِذًا مُنْظَرِينَ﴾؟","answer":"تفيد «إذًا» جواب شرط مقدر: لو نزلت الملائكة على الوجه الذي طلبوه، لما أُمهلوا؛ فصار مقترحهم نفسه سببًا للوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص308، تحت «براعة التعبير بحرف الجزاء إذا في السياق»","url":""}]},{"id":"s15-29","number":29,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما دلالة توالي التأكيد في ﴿إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ﴾؟","answer":"لرد إنكارهم واستهزائهم بأقوى تقرير: المنزّل هو الله نفسه لا مدخل لبشر في مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص315، تحت «دلالة تتابع المؤكدات في آية الحفظ»","url":""}]},{"id":"s15-30","number":30,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿نَزَّلْنَا﴾ لا أنزلنا؟","answer":"صيغة التفعيل تفيد تكثير التنزيل وتعظيمه، وتناسب نزول القرآن متدرجًا مفرقًا على الرسول، مع بيان عناية الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص313، تحت «دلالة صيغة فعل في قوله نزلنا»","url":""}]},{"id":"s15-31","number":31,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّا لَهُ لَحَافِظُونَ﴾ جملة اسمية؟","answer":"لإفادة الثبات والدوام، لا حفظًا مؤقتًا ينتهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص314، تحت «فائدة ورود الجملة الاسمية في السياق»","url":""}]},{"id":"s15-32","number":32,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما سرّ تقديم ﴿لَهُ﴾ على ﴿لَحَافِظُونَ﴾؟","answer":"يفيد تقديم «له» تخصيص الذكر بهذا الحفظ المضمون من الله، دون سائر الكتب التي وُكل حفظها إلى أهلها، مع تأكيد العناية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص315، تحت «دلالة تقديم له على لحافظون»","url":""}]},{"id":"s15-33","number":33,"surah":15,"verses":[9],"references":[{"surah":15,"verses":[9]}],"verseLabel":"الحجر: 9","question":"ما دلالة حذف متعلّق ﴿لَحَافِظُونَ﴾؟","answer":"يفيد الحذف شمول الحفظ من كل ما لا يليق بالقرآن، من طعن وزيادة ونقص وتبديل، مع استمرار حفظه في كل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص316، تحت «إيثار حذف متعلق اسم الفاعل لحافظون»","url":""}]},{"id":"s15-34","number":34,"surah":15,"verses":[10],"references":[{"surah":15,"verses":[10]}],"verseLabel":"الحجر: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَقَدْ أَرْسَلْنَا مِنْ قَبْلِكَ﴾؟","answer":"يؤكد القسم و«قد» سبق إرسال الرسل، وفي تذكير النبي بما لقوه من قومهم تسلية له وتثبيت أمام استهزاء المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص318، تحت «فائدة التأكيد بقوله ولقد»","url":""}]},{"id":"s15-35","number":35,"surah":15,"verses":[10],"references":[{"surah":15,"verses":[10]}],"verseLabel":"الحجر: 10","question":"ما دلالة التعبير بـ﴿في﴾ في قوله تعالى: ﴿في شيع الأولين﴾؟","answer":"تشعر ﴿في﴾ بتمكن الرسل في أقوامهم ومخالطتهم لهم مع قيام الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص319، تحت «نكتة إيثار التعبير بفي في السياق»","url":""}]},{"id":"s15-166","number":166,"surah":15,"verses":[10],"references":[{"surah":15,"verses":[10]}],"verseLabel":"الحجر: 10","question":"ما سرّ التعبير بلفظ ﴿شيع﴾؟","answer":"الشيع فرق يجتمع أفرادها على ما يتبعونه، وفي اللفظ تصوير لاتباع المكذبين بعضهم بعضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص320، تحت «سر التعبير بلفظ شيع في السياق»","url":""}]},{"id":"s15-36","number":36,"surah":15,"verses":[11],"references":[{"surah":15,"verses":[11]}],"verseLabel":"الحجر: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا يَأْتِيهِمْ مِنْ رَسُولٍ﴾؟","answer":"«من» تؤكد الاستغراق: ما جاءهم رسول قط إلا قابلوه بالنمط نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص322، تحت «فائدة مجيء من»","url":""}]},{"id":"s15-38","number":38,"surah":15,"verses":[12],"references":[{"surah":15,"verses":[12]}],"verseLabel":"الحجر: 12","question":"ما نكتة التعبير بـ﴿نسلكه﴾؟","answer":"السلك إدخال دقيق كإدخال الخيط في الإبرة، فيصوّر تمكن ما أُدخل في قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص329، تحت «نكتة التعبير بلفظ نسلكه»","url":""}]},{"id":"s15-167","number":167,"surah":15,"verses":[12],"references":[{"surah":15,"verses":[12]}],"verseLabel":"الحجر: 12","question":"إلى ماذا يعود الضمير في قوله تعالى: ﴿نسلكه﴾؟","answer":"يحتمل عوده إلى التكذيب فيتمكن في قلوبهم، أو إلى القرآن فيدخلها وهم يستقبلونه بالاستهزاء فلا ينتفعون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص329، تحت «دلالة عود الضمير في قوله نسلكه»","url":""}]},{"id":"s15-39","number":39,"surah":15,"verses":[12],"references":[{"surah":15,"verses":[12]}],"verseLabel":"الحجر: 12","question":"ما سرّ وصفهم بـ﴿الْمُجْرِمِينَ﴾ بدل الإضمار؟","answer":"عُدل عن الضمير إلى وصف «المجرمين» لبيان سبب رسوخ التكذيب في قلوبهم: إجرامهم واجتراحهم الذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص330، تحت «بلاغة الإظهار في موضع الإضمار»","url":""}]},{"id":"s15-40","number":40,"surah":15,"verses":[13],"references":[{"surah":15,"verses":[13]}],"verseLabel":"الحجر: 13","question":"ما دلالة النفي بـ﴿لَا﴾ في ﴿لَا يُؤْمِنُونَ بِهِ﴾؟","answer":"يناسب النفي بـ«لا» تمكّن الشك في قلوبهم، فيؤكد إصرارهم على عدم الإيمان رغم وصول الذكر إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص332، تحت «فائدة التعبير بلا النافية في السياق»","url":""}]},{"id":"s15-41","number":41,"surah":15,"verses":[14],"references":[{"surah":15,"verses":[14]}],"verseLabel":"الحجر: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ فَتَحْنَا عَلَيْهِمْ بَابًا مِنَ السَّمَاءِ﴾؟","answer":"يفرض لهم آية مشاهدة بالغة الوضوح، ثم يبين أنهم سيصرفونها إلى السحر؛ فالعائق عن الإيمان عنادهم، لا قلة الدليل. وتنكير الباب يعظّم شأنه ويُشعر بتعدد أبواب السماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص336، تحت «دلالة التعبير بأداة الشرط لو»","url":""}]},{"id":"s15-42","number":42,"surah":15,"verses":[14],"references":[{"surah":15,"verses":[14]}],"verseLabel":"الحجر: 14","question":"ما دلالة التعبير بـ﴿فظلوا﴾؟","answer":"يصور دوام المشاهدة ووضوحها كوضوح النهار، ويجوز حمله على استمرار العروج نهارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص338، تحت «بلاغة الاستعارة في قوله فظلوا»","url":""}]},{"id":"s15-168","number":168,"surah":15,"verses":[14],"references":[{"surah":15,"verses":[14]}],"verseLabel":"الحجر: 14","question":"ما نكتة التعبير بـ﴿يعرجون﴾؟","answer":"ذكر العروج يغني عن ذكر النزول؛ لأن رجوع البشر إلى الأرض مفهوم من حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص338، تحت «نكتة التعبير بلفظ يعرجون»","url":""}]},{"id":"s15-43","number":43,"surah":15,"verses":[15],"references":[{"surah":15,"verses":[15]}],"verseLabel":"الحجر: 15","question":"ما وجه قولهم: ﴿إِنَّمَا سُكِّرَتْ أَبْصَارُنَا﴾؟","answer":"حصروا ما شاهدوه في اختلال أبصارهم، زاعمين أنه تخيل لا حقيقة؛ وهو إمعان في المكابرة مع ظهور الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص339، تحت «بلاغة القصر في قوله إنما سكرت أبصارنا»","url":""}]},{"id":"s15-44","number":44,"surah":15,"verses":[15],"references":[{"surah":15,"verses":[15]}],"verseLabel":"الحجر: 15","question":"ما سرّ الانتقال بـ﴿بَلْ﴾ من ﴿سُكِّرَتْ أَبْصَارُنَا﴾ إلى ﴿قَوْمٌ مَسْحُورُونَ﴾؟","answer":"انتقلوا بـ«بل» إلى دعوى أشد: لم يختل البصر وحده، بل أصاب السحر العقول وسائر الحواس؛ فيظهر تصاعد عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص340، تحت «سر إيثار التعبير بالأداة بل»","url":""}]},{"id":"s15-45","number":45,"surah":15,"verses":[16],"references":[{"surah":15,"verses":[16]}],"verseLabel":"الحجر: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿جَعَلْنَا فِي السَّمَاءِ بُرُوجًا﴾؟","answer":"«جعلنا» هنا بمعنى أوجدنا وأبدعنا؛ فالتعبير يبرز آية الخلق والإبداع الدالة على قدرة الله وتوحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص345، تحت «نكتة التعبير بجعلنا»","url":""}]},{"id":"s15-46","number":46,"surah":15,"verses":[16],"references":[{"surah":15,"verses":[16]}],"verseLabel":"الحجر: 16","question":"ما سرّ تقديم ﴿فِي السَّمَاءِ﴾ على ﴿بُرُوجًا﴾؟","answer":"يفيد تخصيص جعل البروج بالسماء وتأكيد هذا الموضع، مع توجيه النظر إلى آيات ظاهرة أمام المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص346، تحت «سر تقديم في السماء على بروجا»","url":""}]},{"id":"s15-47","number":47,"surah":15,"verses":[16],"references":[{"surah":15,"verses":[16]}],"verseLabel":"الحجر: 16","question":"ما دلالة حذف ما زُيّنت به السماء في ﴿وَزَيَّنَّاهَا﴾؟","answer":"حذف ما زُيّنت به السماء يفيد تنوع زينتها من أشكال وهيئات وتكثرها وعظمتها، فلا تنحصر في صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص348، تحت «سبب إيثار حذف متعلق الفعل وزيناها»","url":""}]},{"id":"s15-48","number":48,"surah":15,"verses":[18],"references":[{"surah":15,"verses":[18]}],"verseLabel":"الحجر: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿اسْتَرَقَ السَّمْعَ﴾؟","answer":"شُبّه اختلاس السمع بأخذ السارق شيئًا في خفاء؛ وتصوّر صيغة الافتعال ما يبذله الشيطان من تكلف واجتهاد في هذا الاختلاس.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص357، تحت «بلاغة الاستعارة استرق السمع»","url":""}]},{"id":"s15-49","number":49,"surah":15,"verses":[19],"references":[{"surah":15,"verses":[19]}],"verseLabel":"الحجر: 19","question":"ما دلالة وصل ﴿وَالْأَرْضَ مَدَدْنَاهَا﴾ بما قبلها بالواو؟","answer":"عطف دلائل الأرض على دلائل السماء يجمع المشهدين في الاستدلال على قدرة الله وتوحيده، مع المقابلة بين بديع صنعه في كل منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص361، تحت «فائدة الوصل بالواو والأرض مددناها»","url":""}]},{"id":"s15-50","number":50,"surah":15,"verses":[19],"references":[{"surah":15,"verses":[19]}],"verseLabel":"الحجر: 19","question":"ما دلالة قوله تعالى: ﴿وألقينا﴾ في خلق الجبال؟","answer":"يصور الإلقاء سهولة خلق الجبال العظيمة على الله وكمال قدرته عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص364، تحت «دلالة قوله تعالى وألقينا»","url":""}]},{"id":"s15-169","number":169,"surah":15,"verses":[19],"references":[{"surah":15,"verses":[19]}],"verseLabel":"الحجر: 19","question":"ما نكتة التعبير بلفظ ﴿رواسي﴾؟","answer":"يبرز ثبات الجبال ورسوخها، فيعظم المخلوق ويبين قدرة خالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص364، تحت «نكتة التعبير بلفظ رواسي»","url":""}]},{"id":"s15-51","number":51,"surah":15,"verses":[19],"references":[{"surah":15,"verses":[19]}],"verseLabel":"الحجر: 19","question":"ما سرّ تقديم ﴿فِيهَا﴾ في ﴿وَأَلْقَيْنَا فِيهَا رَوَاسِيَ﴾؟","answer":"التقديم يؤكد موضع إلقاء الرواسي، ويوجه النظر إلى عظم أثرها في الأرض، من غير أن يلزم منه الحصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص363، 364، تحت «فائدة تقديم فيها»","url":""}]},{"id":"s15-52","number":52,"surah":15,"verses":[20],"references":[{"surah":15,"verses":[20]}],"verseLabel":"الحجر: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وَجَعَلْنَا لَكُمْ فِيهَا مَعَايِشَ﴾ وقدّم ﴿لكم﴾؟","answer":"يفيد التقديم تأكيد اختصاص المعايش بهم على سبيل القصر الإضافي، فيزيد تذكيرهم بفضل الله وامتنانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص368، تحت «فائدة تقديم لكم»","url":""}]},{"id":"s15-53","number":53,"surah":15,"verses":[20],"references":[{"surah":15,"verses":[20]}],"verseLabel":"الحجر: 20","question":"من المقصود بـ﴿وَمَنْ لَسْتُمْ لَهُ بِرَازِقِينَ﴾؟","answer":"يدخل فيه العيال والخدم والدواب ونحوهم؛ فرزقهم في الحقيقة من الله، والناس أسباب في إيصال الرزق إليهم. واستعمال «من» يغلب جانب العقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص370، تحت «فائدة التعبير بمن»","url":""}]},{"id":"s15-54","number":54,"surah":15,"verses":[21],"references":[{"surah":15,"verses":[21]}],"verseLabel":"الحجر: 21","question":"ما بلاغة الحصر في قوله تعالى: ﴿وإن من شيء إلا عندنا خزائنه﴾؟","answer":"يقصر ملك أصول النعم والقدرة عليها على الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص376، تحت «بلاغة الحصر وإن من شيء إلا عندنا خزائنه»","url":""}]},{"id":"s15-170","number":170,"surah":15,"verses":[21],"references":[{"surah":15,"verses":[21]}],"verseLabel":"الحجر: 21","question":"ما نكتة التعبير بلفظ ﴿خزائنه﴾؟","answer":"يصوّر وفرة ما عند الله وسهولة إخراجه وإمداد الخلق به متى شاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص377، تحت «نكتة التعبير بلفظ خزائنه»","url":""}]},{"id":"s15-55","number":55,"surah":15,"verses":[21],"references":[{"surah":15,"verses":[21]}],"verseLabel":"الحجر: 21","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿وما ننزله﴾؟","answer":"صُوّر الإيجاد والإمداد بإنزال العطاء من خزائن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص379، تحت «بلاغة الاستعارة في ننزله»","url":""}]},{"id":"s15-171","number":171,"surah":15,"verses":[21],"references":[{"surah":15,"verses":[21]}],"verseLabel":"الحجر: 21","question":"ما دلالة وصف القدر بأنه ﴿معلوم﴾؟","answer":"يبين أن العطاء مقدر بعلم الله وحكمته، لا عن عجز ولا جزاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص381، تحت «دلالة الصفة معلوم»","url":""}]},{"id":"s15-56","number":56,"surah":15,"verses":[22],"references":[{"surah":15,"verses":[22]}],"verseLabel":"الحجر: 22","question":"ما دلالة وصف الرياح بـ﴿لَوَاقِحَ﴾؟","answer":"تحتمل «لواقح» أنها حوامل للسحاب، تشبيهًا بالناقة الحامل، أو أنها تُلقح السحاب والشجر؛ فتجمع الصورة بين الحمل والإثمار وأسباب النماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص385، 386، تحت «بلاغة قوله وأرسلنا الرياح لواقح بين التشبيه والمجاز»","url":""}]},{"id":"s15-57","number":57,"surah":15,"verses":[22],"references":[{"surah":15,"verses":[22]}],"verseLabel":"الحجر: 22","question":"ما سرّ التعبير بـ﴿فَأَسْقَيْنَاكُمُوهُ﴾ بدل «فسقيناكم»؟","answer":"«أسقيناكم» تفيد أن الله جعل الماء مُعَدًّا لهم ومكّنهم من تناوله متى أرادوا؛ فهي أوسع من مجرد إعطائهم شربة ترويهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص387، 388، تحت «نكتة التعبير بلفظ فأسقيناكموه»","url":""}]},{"id":"s15-58","number":58,"surah":15,"verses":[23],"references":[{"surah":15,"verses":[23]}],"verseLabel":"الحجر: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّا لَنَحْنُ نُحْيِي وَنُمِيتُ﴾؟","answer":"تأكيد الخبر وتقوية إسناده إلى الله يقرران اختصاصه بالإحياء والإماتة، ويردان إنكار البعث؛ فمن أوجد الحياة قادر على إعادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص393، تحت «دلالة الحصر في وإنا لنحن نحيي ونميت»","url":""}]}]);
